window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0167", [{"word":"satisfy","ipa_uk":"/ˈsætɪsfaɪ/","ipa_us":"/ˈsætɪsfaɪ/","definition_zh":"满足；使满意；符合（要求或条件）；偿清（债务）；使确信；解（方程）","definition_en":"to fill a need, meet a standard, or settle an obligation so completely that nothing more is required","core_image":"一只空碗被一勺一勺添到碗沿，最后一口汤倒进去，碗里再也装不下一滴","scene":"加班到深夜的人回到家，冰箱里只剩半盒冷饭，他热了又热，吃下去却仍觉得空。Nothing he found in the kitchen could satisfy his hunger that night.","sceneCN":"这里 satisfy 是「把需要填满」（第 1 个义项：饥饿这种缺口被填上）；句意为那晚厨房里找不到任何东西能填饱他的肚子。","pos":[{"tag":"vt.","zh":"满足；使满意；符合（要求、条件）；偿清（债务）；使确信"},{"tag":"vi.","zh":"足够；令人满意（较少用，多出现在书面语）"}],"collocations":[{"phrase":"satisfy a need","zh":"满足需要"},{"phrase":"satisfy the requirements","zh":"符合要求"},{"phrase":"satisfy a debt","zh":"偿清债务"},{"phrase":"satisfy the court","zh":"使法庭信服"},{"phrase":"satisfy curiosity","zh":"满足好奇心"},{"phrase":"satisfy the conditions","zh":"满足条件"}],"forms":[{"label":"三单（现在时）","form":"satisfies"},{"label":"过去式","form":"satisfied"},{"label":"过去分词","form":"satisfied"},{"label":"现在分词","form":"satisfying"}],"derivatives":[{"word":"satisfaction","pos":"n.","zh":"满足；欣慰（由 satisfy 加源自拉丁语的名词后缀，表示动作造成的结果状态）"},{"word":"satisfactory","pos":"adj.","zh":"合格的；令人满意的（由 satisfy 加源自拉丁语的形容词后缀，表示「足以达到标准」，从「够用」转为「达标」）"},{"word":"satisfying","pos":"adj.","zh":"给人满足感的（由 satisfy 加表示效果的形容词后缀，动作转为性质，指「带来满足的」）"},{"word":"dissatisfied","pos":"adj.","zh":"不满的（由否定前缀加 satisfied，指「本该被满足却落空的」）"},{"word":"unsatisfied","pos":"adj.","zh":"未获满足的（由否定前缀加 satisfied，指「缺口还没填上的」，与「不满」侧重不同）"}],"senses":[{"no":"01","title":"Filling a need completely","titleCN":"把需要填满","definition":"to give someone or something enough of what is needed, so that the need is gone","definitionCN":"给足所需，使这种需要消失","example":"One more bowl of soup should satisfy everyone at the table.","exampleCN":"再来一碗汤应该就能让桌上的人都吃饱。","why":"The Latin verb is built from a word meaning enough plus a verb meaning to make, so the first sense is simply making enough of something for hunger, thirst or curiosity.","whyCN":"这个拉丁动词由「足够」和「做」两部分构成，所以第一个义项就是为饥饿、口渴或好奇心「做出足够」。"},{"no":"02","title":"Making someone pleased","titleCN":"使某人满意","definition":"to please someone by meeting what they hoped for","definitionCN":"满足某人的期待，使其感到满意","example":"Her careful answer satisfied the anxious parent.","exampleCN":"她细致的回答让那位焦虑的家长放了心。","why":"When the empty space belongs to another person and is filled, the result is felt as pleasure; the same filling turns into an emotional effect.","whyCN":"当那个空位属于别人并被填上时，结果就表现为愉悦；同一次「填满」转成了情绪效果。"},{"no":"03","title":"Reaching a required standard","titleCN":"达到规定标准","definition":"to meet a level or requirement that someone has set","definitionCN":"达到他人设定的水平或要求","example":"The new bridge satisfies the safety requirements of the city.","exampleCN":"新桥符合该市的安全要求。","why":"A requirement is an empty space marked out in advance; to satisfy it is to bring the level up to that mark.","whyCN":"要求是事先画好的一个空格；满足它就是让水平升到那条线。"},{"no":"04","title":"Fulfilling every condition","titleCN":"符合每项条件","definition":"to fulfil the conditions or clauses attached to an agreement or rule","definitionCN":"履行协议或规则所附的每项条件","example":"You must satisfy the conditions of the visa before you travel.","exampleCN":"出行前你必须满足签证的各项条件。","why":"A condition is a list of separate items, each of which has to be ticked; satisfying means leaving no item empty.","whyCN":"条件是一份逐条列出的清单，每一条都得打勾；满足就是不留任何一条空白。"},{"no":"05","title":"Settling a debt","titleCN":"偿清债务","definition":"to pay a debt or claim in full, so that nothing remains owed","definitionCN":"全额偿还债务或索赔，使不再欠任何东西","example":"The estate was sold to satisfy the debts of the family.","exampleCN":"家产被变卖以偿清家里的债务。","why":"In law and commerce the same image counts: a debt is a space that must be filled, and payment fills it until the claim is closed.","whyCN":"在法律与商业里，同一个意象照样成立：债务是一个必须填满的空位，付款把它填上，索赔就此关闭。"},{"no":"06","title":"Convincing another person","titleCN":"使他人信服","definition":"to give someone enough evidence that their doubt disappears","definitionCN":"给出足够证据，使对方的疑虑消失","example":"The lawyer satisfied the court that the document was genuine.","exampleCN":"律师使法庭相信这份文件是真的。","why":"Doubt is also a gap; evidence fills it until no question is left open.","whyCN":"怀疑同样是一个缺口；证据把它填满，直到再没有悬而未决的问题。"},{"no":"07","title":"Convincing oneself by checking","titleCN":"核实后使自己放心","definition":"to check something until one is no longer in doubt","definitionCN":"反复核查直到自己不再怀疑","example":"He opened the box again to satisfy himself that the keys were inside.","exampleCN":"他又打开盒子，确认钥匙确实在里面。","why":"The same filling now points inward: the person supplies the evidence that removes their own doubt.","whyCN":"同一次填满转向内部：人自己提供证据，填掉自己的怀疑。"},{"no":"08","title":"Holding true in mathematics","titleCN":"满足方程","definition":"to make an equation or logical condition true when put in place of a variable","definitionCN":"代入变量后使方程或逻辑条件成立","example":"The value four satisfies the equation on the board.","exampleCN":"数值四使黑板上的那个方程成立。","why":"In mathematics a condition is a slot; the value that fills the slot and keeps the statement true is said to satisfy it.","whyCN":"在数学里，条件是一个空位；填进去并使陈述保持成立的值，就被说成满足它。"}],"etymology":{"intro":{"en":"Satisfy reached English through Old French from Latin satisfacere, a compound of satis meaning enough and facere meaning to do or make. Its earliest English uses were legal and religious before the word spread into everyday speech.","cn":"satisfy 经古法语进入英语，源头是拉丁复合动词 satisfacere，由 satis「足够」与 facere「做、使」构成。它在英语里最早的用法偏法律与宗教，后来才进入日常口语。"},"items":[{"era":"LATIN SATIS","en":"Satis is an indeclinable Latin word meaning enough or sufficiently; its deeper Indo-European source is a reconstructed form rather than a recorded word.","cn":"satis 是拉丁语中不变格的词，意为「足够、充分地」；它更深的印欧来源是重构形式，而非有记录的词。"},{"era":"LATIN FACERE","en":"Facere means to do or to make and is one of the most productive verbs in Latin; the same element appears in English verbs ending in -fy.","cn":"facere 意为「做、使」，是拉丁语中构词能力最强的动词之一；同一个成分也出现在英语中表示「使……」的动词词族里。"},{"era":"LATIN SATISFACERE","en":"Joined together, the two parts make satisfacere, literally to make enough, used for paying a debt or answering an accusation.","cn":"两部分合起来构成 satisfacere，字面是「做出足够」，用于偿债或回应指控。"},{"era":"OLD FRENCH","en":"Old French took the verb as satisfier and used it both for contenting a person and for paying what is owed.","cn":"古法语把它接成 satisfier，既表示「使满意」，也表示「偿还所欠」。"},{"era":"MIDDLE ENGLISH","en":"English borrowed the word in the fourteenth century, first in legal and religious settings such as satisfying a debt or doing penance.","cn":"英语在十四世纪借入这个词，最早出现在法律与宗教语境中，如偿债或苦修赎罪。"},{"era":"MODERN ENGLISH","en":"From those roots the word widened to mean meeting any standard, pleasing anyone, and convincing a listener.","cn":"从这些源头出发，词义扩展到达到任何标准、使任何人满意，以及使听者信服。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close to satisfy and are often confused with it; the second holds near neighbours that each fill a slightly different part of the same idea.","cn":"第一组是与 satisfy 形近或音近、常被混用的词；第二组是语义相近、但各自填的是同一念头不同角落的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"satiate","ipa":"/ˈsætieɪt/","tag":"related root","definition":"Built on Latin satiare, to fill full, which shares the element for enough; it stresses fullness up to the point of surfeit rather than the meeting of a standard.","definitionCN":"由拉丁 satiare「装满」构成，与表示「足够」的成分同源；它强调满到过量，而不是达到某个标准。"},{"word":"satisfice","ipa":"/ˈsætɪsfaɪs/","tag":"modern blend","definition":"A twentieth-century coinage blending satisfy and suffice; in decision theory it means choosing an option that is good enough rather than the best one.","definitionCN":"二十世纪把 satisfy 与 suffice 拼合而成的新词；在决策理论里指选一个「够好」而非最优的方案。"},{"word":"sate","ipa":"/seɪt/","tag":"different source","definition":"A native verb from Old English sadian, to fill or glut, with no Latin element in its history; it means to satisfy beyond the point of wanting more.","definitionCN":"本土动词，源自古英语 sadian「填满、使饱足」，历史上不含拉丁成分；指满足到再也不想多要。"},{"word":"sacrifice","ipa":"/ˈsækrɪfaɪs/","tag":"shares one element","definition":"From sacer, sacred, plus facere, to make; it shares the second element with satisfy but carries nothing of the enough idea.","definitionCN":"由 sacer「神圣的」加 facere「做」构成；与 satisfy 共用第二个成分，但完全没有「足够」的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fulfil","ipa":"/fʊlˈfɪl/","tag":"duty completed","definition":"To carry out what was promised or required; it points at the completion of a duty, while satisfy points at the removal of a need.","definitionCN":"把承诺或要求的事情做完；它指向义务的完成，而 satisfy 指向需要的消除。"},{"word":"meet","ipa":"/miːt/","tag":"level reached","definition":"To reach the level that is asked for; common with requirements and targets, and neutral about any feeling of pleasure.","definitionCN":"达到被要求的水平；常与要求和指标连用，对是否产生愉悦感保持中性。"},{"word":"content","ipa":"/kənˈtent/","tag":"quiet comfort","definition":"To make someone quietly happy with what they have; milder than satisfy and closer to emotional comfort.","definitionCN":"使某人对已有的东西安然满足；比 satisfy 温和，更接近情绪上的安适。"},{"word":"appease","ipa":"/əˈpiːz/","tag":"buying peace","definition":"To calm someone by conceding what they ask, often suggesting that peace is bought rather than the need truly met.","definitionCN":"靠让步让对方平静下来，常暗示只是买来安宁，而非真正满足需要。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The first part is the Latin word for enough; the second is the Latin verb to make. Together they say: make enough.","cn":"前半是拉丁语「足够」，后半是拉丁语「做」；合起来就是「做到够」。"},{"en":"The -fy family is large and regular: certify, notify and simplify all use the same make element.","cn":"表示「使……」的动词词族庞大而规则：certify、notify、simplify 都用同一个成分。"},{"en":"Fixed phrases show what is being filled: satisfy a need, satisfy the requirements, satisfy a debt.","cn":"固定搭配显示被填的是什么：满足需要、符合要求、偿清债务。"},{"en":"The noun satisfaction and the adjective satisfactory grow from this verb, not from separate roots.","cn":"名词 satisfaction 与形容词 satisfactory 都从这个动词长出，而不是另有词根。"},{"en":"In law a claim is satisfied when it is paid in full; in mathematics a value satisfies an equation when it keeps it true.","cn":"在法律上，索赔被全额付清就叫已满足；在数学上，能使方程保持成立的值就叫满足方程。"}],"abstract":[{"en":"Picture a bowl under a tap, filled until the water stands level with the rim.","cn":"想象一只碗放在水龙头下，水面一直升到与碗沿齐平。"},{"en":"Picture a judge nodding once, closing the file and reaching for the next case.","cn":"想象一位法官点一下头，合上卷宗，伸手去拿下一份案子。"},{"en":"Picture a door that finally clicks shut, and the hand that stops pushing it.","cn":"想象一扇门终于咔哒合上，那只一直推着门的手停了下来。"}]},"examples":[{"en":"The new policy satisfies both the workers and the management.","cn":"新政策让工人和管理层都满意。"},{"en":"Nothing he said could satisfy the committee's doubts.","cn":"他说什么都无法打消委员会的疑虑。"},{"en":"She satisfied the entrance requirements and was offered a place.","cn":"她符合入学要求，拿到了录取名额。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sat（够）+ isfy（做）」——做到够，心里就满足；也可谐音记成「塞替他饭」，把饭添到够。","word":"satisfy"},"root":"拉丁 satis「足够」加 facere「做、使」，合成 satisfacere「使足够、偿清」，经古法语 satisfier 入英语。satis 更深的印欧来源是重构形式，无法确证；同族有 satisfaction、satisfactory、satisfied 等。","sensesIntro":{"en":"Eight senses all grow from one image: a container filled up to the line. Fill a hungry body, fill a person's hopes, fill a required level, fill every clause, fill a debt, fill another person's doubt, fill one's own doubt, or fill the slot of an equation.","cn":"八个义项都从同一个画面长出：一个容器被填到刻度线。填饱身体、填满期待、填到规定水平、填上每项条款、填平债务、填掉别人的疑问、填掉自己的疑问，或填进方程的那个空位。"},"semanticMap":{"core":{"en":"CORE IMAGE: a container filled exactly to the line, with nothing left empty.","cn":"核心意象：一个容器被填到刻度线，不留一处空白。"},"chain":["FILL TO THE LINE","THE NEED COMES TO AN END","PLEASURE FOLLOWS","MEET A SET STANDARD","PAY WHAT IS OWED","DOUBT COMES TO AN END"],"branches":[{"senses":"01 · 02","en":"FULL AND PLEASED: the need is closed, and the pleasing feeling is the other side of that same filling.","cn":"填满与被取悦：需要被合上，而愉悦感正是同一次填满的另一面。"},{"senses":"03 · 04","en":"A LINE DRAWN IN ADVANCE: one branch is a level to reach, the other is a list of clauses to tick one by one.","cn":"事先画好的线：一支是须要达到的水平，另一支是须要逐条打勾的清单。"},{"senses":"05","en":"A DEBT AS A SPACE: money fills what was owed until nothing remains on the account.","cn":"债务作为空位：钱把欠的部分填上，直到账上不再剩任何东西。"},{"senses":"06 · 07","en":"DOUBT FILLED FROM OUTSIDE OR INSIDE: evidence quiets another person first, then the same person quiets themselves.","cn":"从外或从内填掉怀疑：证据先让别人的疑问安静下来，再让本人安静自己。"},{"senses":"08","en":"THE SLOT OF A CONDITION: in mathematics a value fills a condition and keeps the statement true.","cn":"条件的空位：在数学里，一个值填进条件，并让陈述保持成立。"}]},"affixes":{"intro":{"en":"Satisfy can be read as three pieces: a Latin word for enough, a Latin verb for making, and an English verb ending that carries that verb into a whole family of words.","cn":"satisfy 可以拆成三块读：一个意为「足够」的拉丁词、一个意为「做」的拉丁动词，以及把这个动词带进整个词族的英语动词词尾。"},"latinIntro":{"en":"The Latin family behind this word is small but exact: satis for enough, satisfacere for the verb, and satisfactio for the resulting state.","cn":"这个词背后的拉丁词族不大但很整齐：satis 表示足够，satisfacere 是动词，satisfactio 是结果状态。"},"items":[{"word":"satis","structure":"satis (Latin, indeclinable adjective and adverb, 'enough')","meaning":"enough; sufficiently","meaningCN":"足够；充分地","example":"This small word carries the whole idea of sufficiency.","exampleCN":"这个小小的词承载了「足够」的全部意思。"},{"word":"-fy","structure":"-fy (English verb ending, from Latin facere, 'to make')","meaning":"to make; to cause to be","meaningCN":"使……；使成为","example":"The ending turns a noun or adjective into a verb of making.","exampleCN":"这个词尾把名词或形容词变成表示「使成为」的动词。"},{"word":"satisfy","structure":"satis + -fy","meaning":"to make enough","meaningCN":"使足够；满足","example":"One bowl was enough to satisfy the child.","exampleCN":"一碗就足够让这个孩子吃饱。"},{"word":"satisfaction","structure":"satisfy + -tion (noun of result)","meaning":"the state of being filled or content","meaningCN":"被填满或满意的状态","example":"Her satisfaction with the result was obvious.","exampleCN":"她对结果很满意，这一点显而易见。"},{"word":"satisfactory","structure":"satisfy + -ory (adjective, 'serving to')","meaning":"serving to meet a standard","meaningCN":"足以达到标准的","example":"The repairs were satisfactory.","exampleCN":"维修结果合格。"},{"word":"satisfying","structure":"satisfy + -ing (adjective of effect)","meaning":"giving the feeling of fullness","meaningCN":"给人满足感的","example":"It was a satisfying meal.","exampleCN":"那是一顿让人满足的饭。"},{"word":"dissatisfied","structure":"dis- + satisfied","meaning":"not pleased with what was given","meaningCN":"对所给的不满意","example":"The customers were dissatisfied with the delay.","exampleCN":"顾客对延误感到不满。"},{"word":"unsatisfied","structure":"un- + satisfied","meaning":"still lacking what was needed","meaningCN":"仍然缺少所需","example":"The demand for housing remained unsatisfied.","exampleCN":"住房需求仍未得到满足。"},{"word":"certify","structure":"certus + -fy","meaning":"to make certain","meaningCN":"使确定；证明","example":"The same ending builds a verb of making from a different first element.","exampleCN":"同一个词尾换一个前半成分，就造出另一个表示「使」的动词。"}],"latinEntries":[{"word":"satis","structure":"satis (indeclinable adjective and adverb)","meaning":"enough, sufficient","meaningCN":"足够；充足"},{"word":"satisfacere","structure":"satisfacere, satisfeci, satisfactum (verb)","meaning":"to make enough, to satisfy, to pay","meaningCN":"使足够；使满意；偿清"},{"word":"satisfactio","structure":"satisfactio, satisfactionis (f., third declension)","meaning":"a satisfying, payment, atonement","meaningCN":"满足；偿付；赎罪"}],"derivatives":[{"word":"satisfaction","pos":"n.","zh":"满足；欣慰（动词加源自拉丁语的结果名词后缀，表示被填满的状态）"},{"word":"satisfactory","pos":"adj.","zh":"合格的（动词加源自拉丁语的形容词后缀，表示「足以达标」）"},{"word":"satisfying","pos":"adj.","zh":"令人满足的（动词加表示效果的形容词后缀，动作转为效果）"},{"word":"dissatisfied","pos":"adj.","zh":"不满的（否定前缀反转 satisfied，指向落空的人）"},{"word":"unsatisfied","pos":"adj.","zh":"未获满足的（否定前缀否定 satisfied，指向仍缺的口）"}]}},{"word":"satisfactory","ipa_uk":"/ˌsætɪsˈfæktəri/","ipa_us":"/ˌsætɪsˈfæktəri/","definition_zh":"令人满意的；符合要求的；尚可的；够用的；可接受的","definition_en":"good enough to meet a standard or need, though not necessarily excellent","core_image":"验收员在表格最后一格打勾，整页没有一处红叉，他合上文件放回架子","scene":"工头把验收单翻到最后一页，在合格栏上签了字，又把笔搁回桌上。The inspector found the repairs satisfactory and signed the form.","sceneCN":"这里 satisfactory 指「达到可接受的标准」（第 1 个义项：刚好越过合格线）；句意为验收员认为维修合格，并在单子上签了字。","pos":[{"tag":"adj.","zh":"令人满意的；符合标准的；尚可的；够用的"}],"collocations":[{"phrase":"satisfactory result","zh":"令人满意的结果"},{"phrase":"satisfactory explanation","zh":"令人信服的解释"},{"phrase":"satisfactory performance","zh":"合格的表现"},{"phrase":"satisfactory progress","zh":"令人满意的进展"},{"phrase":"satisfactory answer","zh":"合格的答复"},{"phrase":"find something satisfactory","zh":"觉得某事令人满意"},{"phrase":"satisfactory condition","zh":"良好状况"}],"forms":[{"label":"比较级","form":"more satisfactory"},{"label":"最高级","form":"most satisfactory"},{"label":"副词","form":"satisfactorily"},{"label":"名词（合格的性质）","form":"satisfactoriness"},{"label":"否定形容词","form":"unsatisfactory"}],"derivatives":[{"word":"satisfactorily","pos":"adv.","zh":"合格地；令人满意地（由 satisfactory 加副词后缀，转为「以达标的方式」）"},{"word":"satisfactoriness","pos":"n.","zh":"合格；够用（由 satisfactory 加名词后缀，指「达标的性质」）"},{"word":"unsatisfactory","pos":"adj.","zh":"不令人满意的（由否定前缀加 satisfactory，指「达不到标准」）"},{"word":"unsatisfactorily","pos":"adv.","zh":"不合格地（由否定前缀加 satisfactorily，指「以不达标的方式」）"}],"senses":[{"no":"01","title":"Meeting the required standard","titleCN":"达到规定标准","definition":"good enough to pass a standard that has been set in advance","definitionCN":"好到足以通过事先设定的标准","example":"The essay was not brilliant, but it was satisfactory.","exampleCN":"这篇文章不算出色，但达到了要求。","why":"The Latin verb underneath means to make enough; this adjective reports that the required amount has been reached, no more and no less.","whyCN":"底下的拉丁动词意为「做出足够」；这个形容词说明需要的量已经达到，不多也不少。"},{"no":"02","title":"Giving pleasure or contentment","titleCN":"带来愉悦与满足","definition":"pleasing enough to leave someone content","definitionCN":"好到足以让人心满意足","example":"We had a satisfactory meal at the small restaurant.","exampleCN":"我们在那家小馆子吃了一顿让人满意的饭。","why":"The same filling that closes a need also produces a feeling; when the feeling is the point, the word describes the thing that caused it.","whyCN":"同一次填满在合拢需要的同时也产生感受；当感受成为重点时，这个词就形容引起感受的事物。"},{"no":"03","title":"Merely adequate, nothing more","titleCN":"仅仅够格、并不出色","definition":"acceptable but ordinary, with no claim to excellence","definitionCN":"可以接受但平平，绝无优秀之意","example":"It was a satisfactory but forgettable film.","exampleCN":"那是一部合格却容易忘掉的电影。","why":"Because the word only marks the line, it can quietly imply that the line was all that was reached; praise has to come from another word.","whyCN":"因为这个词只标出那条线，它便暗示只走到了那条线；要表达赞美，得换别的词。"},{"no":"04","title":"Convincing as an explanation","titleCN":"作为解释令人信服","definition":"strong enough to answer a doubt or a question","definitionCN":"足够有力，能回应疑问","example":"She gave a satisfactory account of the missing money.","exampleCN":"她对那笔失踪的钱给出了令人信服的说法。","why":"A doubt is a gap that needs filling; an explanation that fills it is called satisfactory even when nobody is pleased.","whyCN":"疑问是一个需要填的缺口；把缺口填上的解释就叫 satisfactory，哪怕没有人因此高兴。"},{"no":"05","title":"A passing grade band","titleCN":"及格档的成绩","definition":"in education, the grade band that counts as a pass without distinction","definitionCN":"在教育中，算作及格但不出色的成绩档","example":"She received a satisfactory mark in chemistry.","exampleCN":"她的化学得了一个及格的分数。","why":"Schools divide results into bands; the band named by this word means the work cleared the bar and stopped there.","whyCN":"学校把成绩分成若干档；这个词所指的那一档，表示作业越过了及格线就停在那里。"},{"no":"06","title":"Legally or contractually sufficient","titleCN":"法律或合同上足够","definition":"enough in law or in a contract to support a claim or close a duty","definitionCN":"在法律或合同中足以支持主张或了结义务","example":"They produced satisfactory proof of ownership.","exampleCN":"他们出示了足以证明所有权的证据。","why":"A court or a contract fixes a threshold; the word reports that the evidence or performance has reached it.","whyCN":"法庭或合同会设定门槛；这个词说明证据或履行已经到达那道门槛。"},{"no":"07","title":"Acceptable to the people involved","titleCN":"各方都能接受","definition":"acceptable to the people who have to agree to it","definitionCN":"对必须同意它的各方来说都可以接受","example":"The terms were satisfactory to both sides.","exampleCN":"这些条款双方都能接受。","why":"Satisfaction can be a judgement made by a person, so the adjective also takes a human point of view rather than an abstract rule.","whyCN":"满意可以由人来判断，所以这个形容词也能挂在人的视角上，而不只对着抽象规则。"},{"no":"08","title":"Adequate for a technical purpose","titleCN":"对某项技术用途足够","definition":"adequate for the purpose stated in a method or a study","definitionCN":"对方法或研究所述的目的而言足够","example":"The sample size was satisfactory for the analysis.","exampleCN":"这个样本量对该项分析来说是足够的。","why":"Research writing sets its own threshold; the word then means that the data cleared that threshold, not that the result is good news.","whyCN":"研究写作会自设门槛；这个词于是表示数据越过了那道门槛，而不是结果一定好看。"}],"etymology":{"intro":{"en":"Satisfactory is an adjective built on the Latin verb satisfacere, to make enough, which itself joins satis, enough, with facere, to make. The adjective adds the Latin ending that English keeps as -ory.","cn":"satisfactory 是建筑在拉丁动词 satisfacere「使足够」之上的形容词，该动词由 satis「足够」与 facere「做」合成；形容词再加上英语保留下来的那个形容词词尾。"},"items":[{"era":"LATIN SATIS","en":"Satis means enough or sufficiently and supplies the first half of the whole family; its deeper Indo-European source is a reconstructed form rather than a recorded word.","cn":"satis 意为「足够、充分地」，提供整个词族的前半；它更深的印欧来源是重构形式，而非有记录的词。"},{"era":"LATIN FACERE","en":"Facere means to do or to make and gives the verb its sense of producing a result.","cn":"facere 意为「做、使」，赋予这个动词「做出结果」的含义。"},{"era":"LATIN SATISFACERE","en":"The compound satisfacere means literally to make enough and was used for paying a debt or meeting a charge.","cn":"复合动词 satisfacere 字面意为「做出足够」，用于偿债或应对指控。"},{"era":"LATE LATIN SATISFACTORIUS","en":"The adjective is generally considered to come from Late Latin satisfactorius, built on the same verb with the ending that marks 'serving to do'.","cn":"这个形容词一般认为是来自晚期拉丁语 satisfactorius，它由同一动词加表示「用以……」的词尾构成。"},{"era":"ENGLISH FORMATION","en":"English shows the adjective from the sixteenth century, formed either on the Latin model or directly by adding -ory to the verb stem.","cn":"英语在十六世纪出现这个形容词，或照着拉丁模式造出，或直接在动词词干后加那个形容词词尾。"},{"era":"MODERN ENGLISH","en":"Modern usage narrowed the word to 'good enough to meet a standard', which is why it praises without enthusiasm.","cn":"现代用法把它收窄为「好到足以达标」，所以它的称赞总带着克制。"}]},"similar":{"note":{"en":"The first group gathers forms that look almost identical and are routinely swapped by mistake; the second gathers words that also report sufficiency but measure it differently.","cn":"第一组是外形近乎相同、常被误用的形式；第二组是同样表示「够」、但衡量方式不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"satisfying","ipa":"/ˈsætɪsfaɪɪŋ/","tag":"same root, different job","definition":"The participle used as an adjective: it describes the thing that gives pleasure, not the thing that passes a test.","definitionCN":"分词作形容词：形容带来愉悦的事物，而不是通过检验的事物。"},{"word":"satisfied","ipa":"/ˈsætɪsfaɪd/","tag":"same root, different job","definition":"It describes the person who feels content, while satisfactory describes the thing that meets the standard.","definitionCN":"它形容感到满足的人，而 satisfactory 形容达到标准的物。"},{"word":"satisfactorily","ipa":"/ˌsætɪsˈfæktərəli/","tag":"adverb form","definition":"The adverb built on the same adjective; it tells how something was done, not what the thing was like.","definitionCN":"由同一形容词构成的副词；说明事情做得如何，而不是事物本身如何。"},{"word":"satisfice","ipa":"/ˈsætɪsfaɪs/","tag":"not related","definition":"A modern coinage blending satisfy and suffice, used in decision theory for choosing what is good enough; it is not a Latin derivative of this adjective.","definitionCN":"现代把 satisfy 与 suffice 拼合而成的新词，在决策理论中指选择「够好」的方案；它不是这个形容词的拉丁派生词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adequate","ipa":"/ˈædɪkwət/","tag":"just enough","definition":"Enough for the purpose and often slightly more critical than satisfactory: it measures against a need, not against a formal standard.","definitionCN":"对目的而言足够，常比 satisfactory 略带挑剔：它对着需要衡量，而非对着正式标准。"},{"word":"acceptable","ipa":"/əkˈseptəbl/","tag":"allowed, tolerated","definition":"Good enough to be allowed or tolerated; it speaks of permission and consent rather than of a test being passed.","definitionCN":"好到可以被允许或容忍；说的是许可与同意，而不是通过某项检验。"},{"word":"sufficient","ipa":"/səˈfɪʃənt/","tag":"quantity enough","definition":"Enough in amount for a stated need; it counts quantity, while satisfactory judges quality against a standard.","definitionCN":"数量上满足所述需要；它数的是量，而 satisfactory 按标准评的是质。"},{"word":"passable","ipa":"/ˈpɑːsəbl/","tag":"barely above the line","definition":"Just good enough to get by, with a stronger hint of mediocrity than satisfactory carries.","definitionCN":"刚够凑合，比 satisfactory 更明显地带一点平庸的暗示。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The ending -ory means serving to do something, so the word says serving to make enough.","cn":"那个形容词词尾表示「用以做某事」，所以这个词等于「用以做到够」。"},{"en":"It belongs to the same family as satisfy, satisfaction and satisfactorily, all built on the Latin verb for making enough.","cn":"它与 satisfy、satisfaction、satisfactorily 同族，全部建在表示「做出足够」的拉丁动词上。"},{"en":"Fixed phrases show what is being judged: a satisfactory result, a satisfactory explanation, satisfactory progress.","cn":"固定搭配显示被评判的对象：合格的结果、令人信服的解释、令人满意的进展。"},{"en":"The pair satisfactory and satisfying is a real trap: one passes a standard, the other gives pleasure.","cn":"satisfactory 与 satisfying 是一对真实的陷阱：一个是通过标准，一个是带来愉悦。"},{"en":"Adding un- reverses the judgement: unsatisfactory is the word used when something fails the line.","cn":"加上否定前缀就把判断反过来：达不到那条线时用 unsatisfactory。"}],"abstract":[{"en":"Picture a form with a row of empty boxes, and a pen putting one tick in the last box.","cn":"想象一张表格上排着一列空格，一支笔在最后一格里打了一个勾。"},{"en":"Picture a ruler laid across a piece of wood, with the mark exactly level, not a millimetre above it.","cn":"想象一把尺子横在木料上，刻度正好齐平，一毫米也不多。"},{"en":"Picture a bowl filled to the brim but with no spoonful added after that.","cn":"想象一只碗被添到碗沿，之后再没有多加一勺。"}]},"examples":[{"en":"The teacher described the pupil's progress as satisfactory.","cn":"老师认为这个学生的进步令人满意。"},{"en":"We need a satisfactory explanation before we can proceed.","cn":"在继续之前，我们需要一个令人满意的解释。"},{"en":"Her grades were satisfactory but not outstanding.","cn":"她的成绩合格，但并不突出。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「satis（够）+ fact（做）+ ory（的）」——做到够的标准，就是合格的；谐音可记「塞替斯fai克托里」。","word":"satisfactory"},"root":"拉丁 satis「足够」加 facere「做、使」构成动词 satisfacere，再加拉丁语中意为「用以……」的形容词词尾，形成晚期拉丁语形容词；一般认为这是该词的直接来源。同族有 satisfy、satisfaction、satisfactorily。","sensesIntro":{"en":"Eight senses radiate from a single line: the mark that separates enough from not enough. The line can be a standard, a pleasure, a plain pass, a doubt answered, a grade band, a legal threshold, the consent of two parties, or a research method's requirement.","cn":"八个义项都从同一条线发散：把「够」与「不够」分开的那道刻度。这条线可以是标准、是愉悦、是平淡的及格、是被回答的疑问、是成绩档、是法律门槛、是双方的同意，也可以是研究方法的要求。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mark that a thing has reached exactly, with nothing added above it.","cn":"核心意象：事物恰好到达的那道刻度，刻度之上再没有任何多余。"},"chain":["FILLED TO THE MARK","THE BAR IS MET","PLEASURE WITHOUT PRAISE","DOUBT ANSWERED","A NAMED PASSING BAND","SUFFICIENT FOR THE PURPOSE"],"branches":[{"senses":"01 · 03","en":"ON THE LINE: passing the standard and being merely adequate are the same threshold seen from two sides.","cn":"恰好在线：通过标准与仅仅够格，是同一条门槛的两个侧面。"},{"senses":"02","en":"PLEASURE WITHOUT PRAISE: the thing leaves someone content, yet the word never claims excellence.","cn":"不带赞美的愉悦：事物让人满足，但这个词从不宣称优秀。"},{"senses":"04 · 06","en":"DOUBT AND LAW: an explanation or a document must be strong enough to close a question.","cn":"疑问与法律：一份解释或一份文件必须足够有力，才能把问题合上。"},{"senses":"05","en":"A BAND ON A REPORT: schools turn the threshold into a named grade that means pass and stop.","cn":"成绩单上的一档：学校把门槛变成一个有名目的等级，意为及格即止。"},{"senses":"07 · 08","en":"JUDGED BY PEOPLE OR BY METHOD: acceptable to both sides, or adequate for a stated technical purpose.","cn":"由人或由方法判定：或为双方接受，或对所述技术目的足够。"}]},"affixes":{"intro":{"en":"Satisfactory is a verb stem plus a Latin adjective ending, and each piece can be named and used again in other words.","cn":"satisfactory 是动词词干加一个拉丁形容词词尾，每一块都能叫出名字，也能再用到别的词里。"},"latinIntro":{"en":"The Latin behind it supplies the word for enough, the verb for making, and an adjective form meaning serving to; English keeps the last piece as -ory.","cn":"它背后的拉丁语提供了表示「足够」的词、表示「做」的动词，以及意为「用以……」的形容词形式；英语把最后一块保留为形容词词尾。"},"items":[{"word":"satis","structure":"satis (Latin, indeclinable, 'enough')","meaning":"enough; sufficiently","meaningCN":"足够；充分地","example":"The first element states the amount required.","exampleCN":"第一个成分点明了所需的量。"},{"word":"facere","structure":"facere (Latin verb, 'to make, do')","meaning":"to make; to do","meaningCN":"做；使","example":"The verb supplies the act of producing a result.","exampleCN":"这个动词提供「做出结果」的动作。"},{"word":"-ory","structure":"-ory (adjective ending from Latin -orius)","meaning":"serving to; tending to","meaningCN":"用以……的；倾向于……的","example":"The ending turns an action into a description.","exampleCN":"这个词尾把动作变成一种描述。"},{"word":"satisfy","structure":"satis + -fy","meaning":"to make enough","meaningCN":"使足够；满足","example":"The verb is the base of the whole family.","exampleCN":"这个动词是整族词的底座。"},{"word":"satisfactory","structure":"satisfy + -ory","meaning":"serving to meet the standard","meaningCN":"用以达到标准的","example":"The adjective reports that the mark was reached.","exampleCN":"这个形容词说明刻度已经被达到。"},{"word":"satisfaction","structure":"satisfy + -tion","meaning":"the state of being filled","meaningCN":"被填满的状态","example":"The noun names the state, not the thing.","exampleCN":"这个名词指状态，而不是事物。"},{"word":"satisfactorily","structure":"satisfactory + -ly","meaning":"in a way that meets the standard","meaningCN":"以达标的方式","example":"The machine performed satisfactorily.","exampleCN":"机器运行得合乎要求。"},{"word":"unsatisfactory","structure":"un- + satisfactory","meaning":"not meeting the standard","meaningCN":"未达到标准的","example":"The report was rejected as unsatisfactory.","exampleCN":"那份报告因不合格被退回。"},{"word":"satisfactoriness","structure":"satisfactory + -ness","meaning":"the quality of being adequate","meaningCN":"合格的性质","example":"The noun names the quality itself.","exampleCN":"这个名词指性质本身。"}],"latinEntries":[{"word":"satisfacere","structure":"satisfacere, satisfeci, satisfactum (verb)","meaning":"to make enough, satisfy, pay","meaningCN":"使足够；使满意；偿付"},{"word":"satisfactorius","structure":"satisfactorius, -a, -um (Late Latin adjective)","meaning":"serving to satisfy","meaningCN":"用以使满足的"},{"word":"satisfactio","structure":"satisfactio, satisfactionis (f., third declension)","meaning":"satisfaction, payment, atonement","meaningCN":"满足；偿付；赎罪"}],"derivatives":[{"word":"satisfactorily","pos":"adv.","zh":"合格地（形容词加副词后缀，转为方式）"},{"word":"satisfactoriness","pos":"n.","zh":"合格性（形容词加名词后缀，转为性质）"},{"word":"unsatisfactory","pos":"adj.","zh":"不合格的（否定前缀否定本词，指没到线）"},{"word":"unsatisfactorily","pos":"adv.","zh":"不合格地（否定前缀加副词后缀，指以不达标的方式）"}]}},{"word":"dissatisfaction","ipa_uk":"/ˌdɪsætɪsˈfækʃn/","ipa_us":"/ˌdɪsætɪsˈfækʃn/","definition_zh":"不满；不满足；令人不满之处；失望；怨言","definition_en":"the state or feeling of being not satisfied, or a specific cause of such displeasure","core_image":"评分表上同一个格子被红笔圈了三次，纸角被指甲按出一道折痕","scene":"会议室里，项目经理把问卷结果投到屏幕上，评分最低的那一栏被红笔圈了三遍。The survey showed growing dissatisfaction with the new booking system.","sceneCN":"这里 dissatisfaction 指「对某事物不断累积的不满」（第 1 个义项：一种普遍的不悦状态）；句意为调查显示人们对新预约系统越来越不满。","pos":[{"tag":"n.","zh":"不满；不满足；（可数）具体的不满事项、怨言"}],"collocations":[{"phrase":"dissatisfaction with","zh":"对……的不满"},{"phrase":"growing dissatisfaction","zh":"日益增长的不满"},{"phrase":"express dissatisfaction","zh":"表达不满"},{"phrase":"customer dissatisfaction","zh":"顾客不满"},{"phrase":"job dissatisfaction","zh":"对工作的不满"},{"phrase":"a source of dissatisfaction","zh":"不满的根源"}],"forms":[{"label":"复数（具体的不满事项）","form":"dissatisfactions"},{"label":"形容词（人感到不满的）","form":"dissatisfied"},{"label":"动词（使不满）","form":"dissatisfy"},{"label":"现在分词（令人不满的）","form":"dissatisfying"}],"derivatives":[{"word":"dissatisfied","pos":"adj.","zh":"不满的（由表示反转的前缀加 satisfied，指「本该被填满却落空的人」）"},{"word":"dissatisfy","pos":"vt.","zh":"使不满（由表示反转的前缀加 satisfy，把「使足够」翻成「使不够」）"},{"word":"dissatisfying","pos":"adj.","zh":"令人不满的（由 dissatisfy 加表示效果的形容词后缀，动作转为效果）"},{"word":"unsatisfied","pos":"adj.","zh":"未获满足的（由否定前缀加 satisfied，指缺口仍在，不等于「不满意」）"}],"senses":[{"no":"01","title":"A general state of displeasure","titleCN":"普遍的不满状态","definition":"the continuing feeling that something is not good enough","definitionCN":"持续感到某事不够好的状态","example":"Dissatisfaction with the service was clear from the reviews.","exampleCN":"从评论里可以清楚看出大家对服务的不满。","why":"The word negates satisfaction, so it names the state left when the expected filling never happens.","whyCN":"这个词否定的是「满足」，所以它命名的是期待中的填满没有发生之后留下的状态。"},{"no":"02","title":"A specific grievance","titleCN":"具体的一项怨言","definition":"a particular complaint or point of displeasure that can be listed","definitionCN":"可以逐条列出的某项抱怨或不满之处","example":"The report lists several dissatisfactions raised by staff.","exampleCN":"报告列出了员工提出的几项不满。","why":"A general mood can be broken into countable items, so the noun also takes a plural and names each separate complaint.","whyCN":"笼统的情绪可以拆成可数的事项，所以这个名词也有复数，指一项一项具体的抱怨。"},{"no":"03","title":"The gap between promise and delivery","titleCN":"承诺与现实之间的落差","definition":"the shortfall felt when what was promised is not what arrives","definitionCN":"承诺的东西没有兑现时感到的落差","example":"Dissatisfaction grows when promises outrun delivery.","exampleCN":"当承诺跑在交付前面时，不满就会增长。","why":"Satisfaction measures a filled space; dissatisfaction measures the same space and finds it short.","whyCN":"满足衡量的是一个被填满的空间；不满衡量的是同一个空间，却发现它短了一截。"},{"no":"04","title":"Consumer displeasure","titleCN":"消费者的不满","definition":"the displeasure of buyers with a product or service","definitionCN":"买家对产品或服务的不悦","example":"Customer dissatisfaction drove the company to redesign the app.","exampleCN":"顾客的不满促使公司重新设计应用。","why":"Commerce makes the shortfall measurable through ratings and complaints, so the word became a standard business label.","whyCN":"商业用评分和投诉把落差量化，于是这个词成了标准的商业标签。"},{"no":"05","title":"Workplace discontent","titleCN":"职场中的不满","definition":"the unhappiness of employees with their jobs or conditions","definitionCN":"员工对工作或工作条件的不快","example":"Job dissatisfaction was highest among night-shift workers.","exampleCN":"夜班员工的工作不满意度最高。","why":"When the unmet need is pay, hours or respect, the general state attaches to a workplace and becomes a named measure.","whyCN":"当未被满足的是报酬、工时或尊重时，这种普遍状态就附着在工作场所，变成一个有名目的测量对象。"},{"no":"06","title":"Public or political discontent","titleCN":"公众或政治上的不满","definition":"widespread displeasure among the public with a policy or institution","definitionCN":"公众对某项政策或机构的广泛不满","example":"Public dissatisfaction with the delays dominated the news.","exampleCN":"公众对延误的不满占据了新闻头条。","why":"The same feeling, shared by many people at once, becomes a social fact that politicians must answer for.","whyCN":"同一种感受被许多人同时共享，就变成政治家必须回应的社会事实。"},{"no":"07","title":"Disappointment with oneself","titleCN":"对自己的失望","definition":"the feeling of falling short of one's own standard","definitionCN":"觉得自己没达到自身标准的感觉","example":"His dissatisfaction with his own work pushed him to rewrite the chapter.","exampleCN":"他对自己作品的不满促使他重写了那一章。","why":"The judge and the judged can be the same person; the gap is then between what was done and what was hoped for.","whyCN":"评判者与被评判者可以是同一个人；此时的落差在已做之事与曾期望之事之间。"},{"no":"08","title":"Discontent as a motive force","titleCN":"作为推动力的不满","definition":"restless displeasure that drives a person or group to seek change","definitionCN":"推动个人或群体寻求改变的不安不满","example":"A healthy dissatisfaction with the status quo is where reform begins.","exampleCN":"对现状一种健康的不满，正是改革的起点。","why":"A gap that stays open long enough stops being passive and starts pushing, which is why the word can name a motor for change.","whyCN":"一个缺口若长期敞着，就不再只是被动感受，而开始推动人行动——所以这个词也能指改变的发动机。"}],"etymology":{"intro":{"en":"Dissatisfaction is satisfaction with a reversing prefix in front of it. Satisfaction comes from Latin satisfactio, a noun built on satisfacere, to make enough, and the Latin prefix dis- turns the filled state into its opposite.","cn":"dissatisfaction 是在 satisfaction 前面加一个表示反转的前缀。satisfaction 来自拉丁名词 satisfactio，它建在动词 satisfacere「使足够」之上；那个表示反转的拉丁前缀把这个被填满的状态翻成了反面。"},"items":[{"era":"LATIN SATIS","en":"Satis means enough and supplies the first element of the whole family; its deeper Indo-European source is a reconstructed form rather than a recorded word.","cn":"satis 意为「足够」，提供整个词族的第一个成分；它更深的印欧来源是重构形式，而非有记录的词。"},{"era":"LATIN FACERE","en":"Facere means to do or to make, and the compound verb satisfacere literally says to make enough.","cn":"facere 意为「做、使」，复合动词 satisfacere 字面就是「做出足够」。"},{"era":"LATIN SATISFACTIO","en":"The noun satisfactio names the resulting state, and in legal and religious Latin it also means payment or atonement.","cn":"名词 satisfactio 指由此产生的状态，在法律与宗教拉丁语里还表示偿付或赎罪。"},{"era":"LATIN DIS-","en":"The Latin prefix dis- first meant apart or in different directions; placed before a noun of satisfaction it adds reversal rather than simple separation.","cn":"那个表示反转的拉丁前缀最初表示「分开、朝不同方向」；放在表示满足的名词前，它加的是反转，而不只是分离。"},{"era":"EARLY MODERN ENGLISH","en":"The English noun appears in the seventeenth century as a plain negation of satisfaction, first in letters and commentary on people and services.","cn":"这个英语名词在十七世纪出现，是对 satisfaction 的直接否定，最早见于书信与对人对事的评论。"},{"era":"MODERN ENGLISH","en":"Modern usage keeps the uncountable mood and adds a countable sense for each listed complaint.","cn":"现代用法保留不可数的情绪义，又添出可数义，指一条条列出的抱怨。"}]},"similar":{"note":{"en":"The first group separates the negative words that share this stem but point at different things; the second group gathers words for displeasure that carry a different flavour.","cn":"第一组用来分辨共用同一词干、却指向不同对象的否定词；第二组是同样表示不悦、但味道不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dissatisfied","ipa":"/ˌdɪsəˈtɪsfaɪd/","tag":"same family, person","definition":"The adjective for a person who is displeased because expectations were not met; it is about the feeling, not the missing amount.","definitionCN":"形容因期待落空而不满的人；说的是感受，不是缺了多少。"},{"word":"unsatisfied","ipa":"/ˌʌnˈsætɪsfaɪd/","tag":"same family, unmet need","definition":"The adjective for a need that has not been filled, whether or not anyone feels angry about it.","definitionCN":"形容尚未被填满的需要，无论当事人是否因此生气。"},{"word":"unsatisfactory","ipa":"/ˌʌnsætɪsˈfæktəri/","tag":"different prefix","definition":"Built with un- rather than dis-, and used for things that fail a standard, not for the feelings of people.","definitionCN":"用否定前缀而不是表示反转的前缀构成，形容达不到标准的事物，不形容人的感受。"}]},{"heading":"NEAR MEANING","entries":[{"word":"discontent","ipa":"/ˌdɪskənˈtent/","tag":"quiet and broad","definition":"A softer, often more collective word for not being content; it suggests a mood in a group rather than a measurable shortfall.","definitionCN":"更柔和、常更集体化的说法；暗示群体中的一种情绪，而非可量化的落差。"},{"word":"displeasure","ipa":"/dɪsˈpleʒə/","tag":"formal disapproval","definition":"Formal and often directed at a person in authority; it is disapproval shown outward, not the inner state of wanting more.","definitionCN":"正式用语，常指向掌权者；是向外表现出的不赞同，而不是内心想要更多的状态。"},{"word":"frustration","ipa":"/frʌˈstreɪʃn/","tag":"blocked action","definition":"The tension that comes from being blocked while trying to reach a goal; dissatisfaction can be quiet, frustration is active.","definitionCN":"想达成目标却被挡住时产生的紧张；不满可以是安静的，而这种受阻的紧张则是活动的。"},{"word":"disappointment","ipa":"/ˌdɪsəˈpɔɪntmənt/","tag":"hope defeated","definition":"The feeling when a hope is defeated at a single point; dissatisfaction is the longer, steadier version of the same gap.","definitionCN":"希望在某一刻落空时的感受；不满是同一个缺口更长、更稳定的版本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The prefix dis- reverses the noun that follows, so dissatisfaction is literally not-satisfaction.","cn":"那个表示反转的前缀把后面的名词反过来，所以 dissatisfaction 字面就是「不满足」。"},{"en":"The base noun satisfaction is built from enough plus make plus a noun ending, so the whole word can be read piece by piece.","cn":"底下的名词 satisfaction 由「足够 + 做 + 名词词尾」构成，整个词可以逐块读出来。"},{"en":"Fixed phrases name the target: dissatisfaction with the service, dissatisfaction with pay, growing dissatisfaction.","cn":"固定搭配点明对象：对服务不满、对报酬不满、日益增长的不满。"},{"en":"Learn the pair: dissatisfied describes a person who is displeased, unsatisfied describes a need still not filled.","cn":"记住这一对：dissatisfied 形容感到不悦的人，unsatisfied 形容仍未填满的需要。"},{"en":"The family runs dissatisfaction, dissatisfied, dissatisfy, dissatisfying, all sharing one Latin base.","cn":"同族词有 dissatisfaction、dissatisfied、dissatisfy、dissatisfying，共用一个拉丁底座。"}],"abstract":[{"en":"Picture a table of food that is neither bad nor right, and a guest quietly putting down the chopsticks.","cn":"想象一桌菜既不算难吃也不对胃口，客人轻轻放下了筷子。"},{"en":"Picture one box on a score sheet circled in red again and again until the paper tears.","cn":"想象评分表上的同一个格子被红笔反复圈画，直到纸面被划破。"},{"en":"Picture a button that will not pass through its hole, though both button and hole are still there.","cn":"想象一枚扣子怎么也扣不进扣眼，扣子和扣眼都还在，只是合不上。"}]},"examples":[{"en":"Dissatisfaction with the new timetable spread through the whole school.","cn":"对新课表的不满传遍了整所学校。"},{"en":"The manager asked the team to list their dissatisfactions one by one.","cn":"经理让团队把不满意的地方逐条列出来。"},{"en":"Low pay was the main source of dissatisfaction among the workers.","cn":"低薪是工人不满的主要根源。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dis（不）+ satisfaction（满足）」——把满足反过来，就是不满；谐音可记「滴斯萨替斯fak身」。","word":"dissatisfaction"},"root":"由表示反转的否定前缀加 satisfaction 构成；satisfaction 来自拉丁名词 satisfactio，源头是 satis「足够」加 facere「做、使」的动词 satisfacere。该前缀在拉丁语中本义为「分开」，加在名词前转为反转。同族有 dissatisfied、dissatisfy。","sensesIntro":{"en":"Eight senses come from one reversal: a space that should have been filled stays short. The shortfall can be a mood, a listed complaint, a promise unmet, a product disliked, a job resented, a public grievance, one's own failed standard, or a push toward change.","cn":"八个义项来自同一次反转：本该被填满的空间短了一截。这截落差可以是情绪、一条条怨言、未兑现的承诺、被嫌弃的产品、被怨恨的工作、公众的怨气、自己没达到的标准，也可以是推动改变的力量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a container meant to be filled that stops below the line.","cn":"核心意象：本该被填满的容器，却停在刻度线之下。"},"chain":["THE FILLING FAILS","A GAP REMAINS","THE GAP BECOMES A MOOD","THE MOOD FINDS WORDS","THE WORDS BECOME A MEASURE","THE MEASURE BECOMES A PUSH"],"branches":[{"senses":"01 · 03","en":"THE OPEN GAP: the general mood and the promise-delivery shortfall are the same missing amount, one felt and one explained.","cn":"敞着的缺口：笼统情绪与承诺落差，是同一笔缺失的量，一个被感受，一个被说清。"},{"senses":"02","en":"THE GAP COUNTED: once complaints are listed, the uncountable mood turns into countable items.","cn":"被计数的缺口：抱怨一旦列成条目，不可数的情绪就变成可数的事项。"},{"senses":"04 · 05","en":"THE GAP IN THE MARKET AND AT WORK: buyers and employees each measure the same shortfall against what was promised.","cn":"市场与职场里的缺口：买家与员工都在拿同一截落差去对照当初的承诺。"},{"senses":"06","en":"THE GAP SHARED: when many people hold it at once, private displeasure becomes a public fact.","cn":"被共享的缺口：许多人同时握着它时，私人的不悦就成了公共事实。"},{"senses":"07 · 08","en":"THE GAP TURNED INWARD AND FORWARD: it can sit between one's work and one's standard, and then become the force that starts reform.","cn":"缺口转向内与前：它可以横在自己的作品与标准之间，再变成启动改革的力量。"}]},"affixes":{"intro":{"en":"This word is a prefix, a root pair and a noun ending stacked in a fixed order, and every layer can be read on its own.","cn":"这个词是一个前缀、一对词根和一个名词词尾按固定顺序叠起来的，每一层都能单独读出。"},"latinIntro":{"en":"The Latin side supplies the prefix of reversal, the word for enough, the verb for making, and the noun of state; together they account for the whole English word.","cn":"拉丁语这边提供了表示反转的前缀、表示足够的词、表示做的动词，以及表示状态的名词；四者合起来正好解释整个英语词。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart, in different directions')","meaning":"apart; reversal in this word","meaningCN":"分开；在本词中表示反转","example":"Before a noun of satisfaction the prefix turns the state negative.","exampleCN":"放在表示满足的名词前，这个前缀把状态翻成否定。"},{"word":"satis","structure":"satis (Latin, indeclinable, 'enough')","meaning":"enough; sufficiently","meaningCN":"足够；充分地","example":"The root supplies the idea of a required amount.","exampleCN":"这个词根提供「所需之量」的意思。"},{"word":"facere","structure":"facere (Latin verb, 'to make, do')","meaning":"to make; to do","meaningCN":"做；使","example":"The verb supplies the act of making the amount.","exampleCN":"这个动词提供「把量做出来」的动作。"},{"word":"-tion","structure":"-tion (noun ending from Latin -tio)","meaning":"the state or result of an action","meaningCN":"动作的状态或结果","example":"The ending turns the verb into a name for a state.","exampleCN":"这个词尾把动词变成状态的名字。"},{"word":"satisfy","structure":"satis + -fy","meaning":"to make enough","meaningCN":"使足够；满足","example":"The verb is the base of the family.","exampleCN":"这个动词是整族词的底座。"},{"word":"satisfaction","structure":"satisfy + -tion","meaning":"the state of being filled","meaningCN":"被填满的状态","example":"The noun is the base of the negative form.","exampleCN":"这个名词是否定形式的底座。"},{"word":"dissatisfaction","structure":"dis- + satisfaction","meaning":"the state of not being filled","meaningCN":"未被填满的状态","example":"The prefix reverses the noun it attaches to.","exampleCN":"这个前缀把它所接的名词反过来。"},{"word":"dissatisfied","structure":"dis- + satisfied","meaning":"a person left displeased","meaningCN":"被弄得不满的人","example":"The adjective moves the state into a person.","exampleCN":"这个形容词把状态移到了人身上。"},{"word":"dissatisfy","structure":"dis- + satisfy","meaning":"to fail to make enough","meaningCN":"使不够；使不满","example":"The verb names the act of leaving someone short.","exampleCN":"这个动词指让某人落空的动作。"}],"latinEntries":[{"word":"satisfactio","structure":"satisfactio, satisfactionis (f., third declension)","meaning":"satisfaction, payment, atonement","meaningCN":"满足；偿付；赎罪"},{"word":"satisfacere","structure":"satisfacere, satisfeci, satisfactum (verb)","meaning":"to make enough, satisfy, pay","meaningCN":"使足够；使满意；偿付"},{"word":"dis-","structure":"dis- (Latin prefix, 'apart, asunder')","meaning":"apart; away from","meaningCN":"分开；离开"}],"derivatives":[{"word":"dissatisfied","pos":"adj.","zh":"不满的（表示反转的前缀加 satisfied，指落空的人）"},{"word":"dissatisfy","pos":"vt.","zh":"使不满（表示反转的前缀加 satisfy，指使不够）"},{"word":"dissatisfying","pos":"adj.","zh":"令人不满的（dissatisfy 加表示效果的形容词后缀，转为效果）"},{"word":"unsatisfied","pos":"adj.","zh":"未获满足的（否定前缀否定 satisfied，指缺口仍在）"}]}},{"word":"desire","ipa_uk":"/dɪˈzaɪə/","ipa_us":"/dɪˈzaɪər/","definition_zh":"渴望；欲望；性欲；渴望的对象；（正式）请求；想要","definition_en":"a strong feeling of wanting something, or the act of wanting it","core_image":"一个人把整张脸贴近橱窗玻璃，目光只钉在里面那件东西上","scene":"橱窗里的那架旧钢琴已经被别人订走，女孩还是每天放学绕路来看一眼。She felt a strong desire to play it just once.","sceneCN":"这里 desire 指「强烈的想要」（第 1 个义项：想要得到某物的愿望）；句意为她强烈地想要亲手弹一次那架琴。","pos":[{"tag":"n.","zh":"渴望；欲望；性欲；所渴望的对象；（正式）请求"},{"tag":"vt.","zh":"渴望；想要；（正式）请求"}],"collocations":[{"phrase":"a strong desire","zh":"强烈的渴望"},{"phrase":"desire for something","zh":"对某物的渴望"},{"phrase":"desire to do something","zh":"做某事的愿望"},{"phrase":"sexual desire","zh":"性欲"},{"phrase":"at someone's desire","zh":"应某人的要求"},{"phrase":"the object of desire","zh":"欲望的对象"},{"phrase":"express a desire","zh":"表达一种愿望"}],"forms":[{"label":"名词复数","form":"desires"},{"label":"三单（现在时）","form":"desires"},{"label":"过去式","form":"desired"},{"label":"过去分词","form":"desired"},{"label":"现在分词","form":"desiring"}],"derivatives":[{"word":"desirous","pos":"adj.","zh":"渴望的（由 desire 加表示「充满……」的形容词后缀，转为「充满渴望」的正式说法）"},{"word":"desirable","pos":"adj.","zh":"值得拥有的（由 desire 加表示「可被……」的形容词后缀，从「可被渴望」转为「令人向往」）"},{"word":"desirability","pos":"n.","zh":"可欲性；吸引力（由 desirable 加名词后缀，把形容词转为可衡量的性质）"},{"word":"undesired","pos":"adj.","zh":"不想要的（由否定前缀加 desired，指「没有被渴望的」）"}],"senses":[{"no":"01","title":"A strong wish for something","titleCN":"对某物的强烈愿望","definition":"a strong feeling that one wants to have or to reach something","definitionCN":"强烈地想要拥有或达到某物的感受","example":"She had no desire to leave the city she grew up in.","exampleCN":"她完全不想离开自己长大的城市。","why":"The Latin verb names a reaching out toward something absent; the noun keeps that pull without saying what the thing is.","whyCN":"这个拉丁动词指的是朝缺席之物伸手；名词保留了这股拉力，却不必说明那是什么东西。"},{"no":"02","title":"Bodily appetite or sexual desire","titleCN":"身体欲望或性欲","definition":"a physical wanting, especially sexual attraction","definitionCN":"身体上的想要，尤指性的吸引","example":"The novel is more about desire than about love.","exampleCN":"这部小说写欲望多于写爱情。","why":"The same pull can start in the body rather than in the mind, and English uses the word plainly for that force.","whyCN":"同一股拉力可以从身体而不是从头脑开始，英语直接用这个词来指这股力量。"},{"no":"03","title":"The thing desired","titleCN":"所渴望的对象","definition":"the person or thing that is the object of wanting","definitionCN":"成为渴望对象的人或物","example":"The painting became an object of desire for collectors.","exampleCN":"这幅画成了收藏家们渴望得到的对象。","why":"The feeling and its target are so closely tied that the noun can stand for the target itself, as in the phrase object of desire.","whyCN":"感受与目标贴得太紧，于是一个名词也能直接指目标本身，如「欲望的对象」这个说法。"},{"no":"04","title":"A formal request","titleCN":"正式的请求","definition":"a polite expression of what someone wants done","definitionCN":"礼貌地表示希望某事被做到","example":"At the manager's desire, the meeting was moved to Monday.","exampleCN":"应经理的要求，会议改到了星期一。","why":"In formal registers a wish can be stated as a request, so the noun also names what someone asks of another.","whyCN":"在正式语境里，愿望可以被陈述为请求，所以这个名词也指某人向他人提出的要求。"},{"no":"05","title":"To want something strongly","titleCN":"强烈地想要","definition":"to want something very much","definitionCN":"非常想要某物","example":"He desired a quiet life far from the city.","exampleCN":"他渴望远离城市过安静的生活。","why":"The noun became a verb by taking the same content as its object: to desire something is to carry that pull toward it.","whyCN":"名词把同样的内容当作宾语就变成了动词：渴望某物，就是把那股拉力朝向它。"},{"no":"06","title":"To request formally","titleCN":"正式请求","definition":"to ask for something in a polite, formal way","definitionCN":"以礼貌正式的方式要求某事","example":"The committee desires further information before it decides.","exampleCN":"委员会希望在作出决定前获得更多信息。","why":"The verb keeps the old polite register, so it appears in letters and minutes rather than in casual talk.","whyCN":"这个动词保留了旧的礼貌语域，所以多见于书信与会议记录，而不是随意的谈话。"},{"no":"07","title":"To wish someone to act","titleCN":"希望某人去做","definition":"to wish or ask another person to do something","definitionCN":"希望或要求另一个人做某事","example":"The king desired his son to marry before winter.","exampleCN":"国王希望儿子在冬天之前成婚。","why":"The same wanting can be aimed at another person's action, which gives the verb a construction with a person plus an infinitive.","whyCN":"同样的「想要」可以指向别人的行动，于是这个动词有了「某人加不定式」的结构。"},{"no":"08","title":"Desire as a mental state in philosophy","titleCN":"哲学中的欲望状态","definition":"in philosophy and psychology, a mental state that moves a person to act","definitionCN":"在哲学与心理学中，推动人行动的心理状态","example":"In philosophy, desire is treated as a state that motivates action.","exampleCN":"在哲学里，欲望被当作一种推动行动的状态。","why":"Once the pull is studied as such, it becomes a technical category: a state with a direction, an object and a force behind behaviour.","whyCN":"当这股拉力被单独研究时，它就成了一个技术范畴：有方向、有对象、并在行为背后提供力量的状态。"}],"etymology":{"intro":{"en":"Desire comes through Old French desirer from Latin desiderare, to long for or to miss. The traditional explanation of the Latin verb joins de- with sidus, star, but that account is not settled.","cn":"desire 经古法语 desirer 来自拉丁动词 desiderare，意为「渴望、思念」。传统解释把该拉丁动词拆成「向下、离开」的前缀加 sidus「星」，但这一说法并未定论。"},"items":[{"era":"LATIN DESIDERARE","en":"Desiderare means to long for something absent, and it is the direct source of the French and English verb.","cn":"desiderare 意为「渴望缺席之物」，是法语与英语动词的直接来源。"},{"era":"PREFIX DE-","en":"The first element is the Latin prefix de-, literally down from or away; in this verb it is generally considered to add force rather than a literal direction.","cn":"第一个成分是拉丁前缀，字面为「从……向下、离开」；在这个动词里，一般认为它加的是力度，而不是字面方向。"},{"era":"LATIN SIDUS, SOURCE UNCERTAIN","en":"The second element is usually connected with sidus, star or constellation; source uncertain, because other explanations of the verb have also been proposed.","cn":"第二个成分通常与 sidus「星、星座」联系起来；来源不确定，因为对这个动词还提出过别的解释。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the traditional reading, to await what the stars will bring, is generally considered a plausible guess rather than a demonstrated origin.","cn":"来源不确定：传统解释把该词读作「等待星辰带来什么」，一般认为这只是一种合理的猜测，而非已被证明的源流。"},{"era":"OLD FRENCH","en":"Old French desirer carried the verb into everyday use for longing, for appetite and for a polite request.","cn":"古法语 desirer 把这个动词带入日常用法，可指思念、欲望，也可指礼貌的请求。"},{"era":"MODERN ENGLISH","en":"English uses the word as both noun and verb, from strong longing to a formal request in letters and minutes.","cn":"英语把这个词同时用作名词和动词，从强烈的思念一直到书信与会议记录中的正式请求。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close to desire but come from other roots; the second holds near neighbours that name different shades of wanting.","cn":"第一组是与 desire 形近或音近、却来自别的词根的词；第二组是表示不同「想要」侧面的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"desirable","ipa":"/dɪˈzaɪərəbl/","tag":"same family","definition":"The adjective built on desire with -able: it describes a thing worth wanting rather than the want itself.","definitionCN":"由 desire 加表示「可被……」的形容词后缀构成的形容词：形容值得想要的事物，而不是想要本身。"},{"word":"desirous","ipa":"/dɪˈzaɪərəs/","tag":"same family, formal","definition":"The formal adjective for a person who wants something, usually followed by of.","definitionCN":"形容人怀有渴望的正式形容词，通常后接表示对象的介词。"},{"word":"desert","ipa":"/ˈdezət/","tag":"not related","definition":"From Latin deserere, to abandon; the dry land and the act of leaving both come from that verb, with no link to desire.","definitionCN":"来自拉丁 deserere「抛弃」；荒漠与离弃都出自那个动词，与 desire 没有词源关系。"},{"word":"dessert","ipa":"/dɪˈsɜːt/","tag":"not related","definition":"From French desservir, to clear the table; the sweet course is named for what comes after the table is cleared.","definitionCN":"来自法语 desservir「清理餐桌」；甜点指的就是撤桌之后上的那道。"}]},{"heading":"NEAR MEANING","entries":[{"word":"longing","ipa":"/ˈlɒŋɪŋ/","tag":"ache for the absent","definition":"A sad, prolonged wanting for something or someone far away; it adds distance and ache that desire alone does not.","definitionCN":"对远方之人之物长久而带怅惘的想要；比 desire 多了距离感与隐痛。"},{"word":"craving","ipa":"/ˈkreɪvɪŋ/","tag":"bodily and urgent","definition":"An urgent bodily wanting, often for food or a substance; it is physical where desire can be mental.","definitionCN":"急迫的身体性想要，常指食物或某种物质；它偏身体，而 desire 可以是心理的。"},{"word":"wish","ipa":"/wɪʃ/","tag":"lighter, often unreal","definition":"A lighter want, often for something unlikely or impossible; it is closer to a hope than to a drive.","definitionCN":"较轻的想要，常指不太可能或不可能之事；更接近希望，而不是驱力。"},{"word":"yearning","ipa":"/ˈjɜːnɪŋ/","tag":"emotional and soft","definition":"A tender, often melancholy wanting, warmer and softer than the general noun desire.","definitionCN":"温柔而常带忧郁的想要，比一般意义上的 desire 更暖、更软。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The traditional reading of the Latin verb joins de- with sidus, star, so the word has long been felt to mean a waiting on the stars.","cn":"对这个拉丁动词的传统解读是「向下、离开」的前缀加 sidus「星」，所以这个词长期被体会为「等待星辰」。"},{"en":"The family is easy to follow: desire, desirous, desirable, desirability, undesired.","cn":"同族词一目了然：desire、desirous、desirable、desirability、undesired。"},{"en":"Fixed phrases show the target: desire for peace, desire to learn, the object of desire, at someone's desire.","cn":"固定搭配点明对象：对和平的渴望、求知的愿望、欲望的对象、应某人的要求。"},{"en":"The adjective desirable is the everyday relative; the adjective desirous is the formal one.","cn":"形容词 desirable 是日常同族词，desirous 则是正式语体的同族词。"},{"en":"Latin desideratum survives in English for something wished for and still lacking.","cn":"拉丁语 desideratum 还留在英语里，指仍然缺少、却被想要的东西。"}],"abstract":[{"en":"Picture a face pressed close to a shop window, eyes fixed on one object inside.","cn":"想象一张脸贴近商店橱窗，眼睛只钉在里面的一件东西上。"},{"en":"Picture a hand reaching across a table toward a cup it cannot quite touch.","cn":"想象一只手越过桌面伸向一只差一点才够到的杯子。"},{"en":"Picture a door left ajar, with someone standing outside in the cold, not leaving.","cn":"想象一扇门虚掩着，有人站在外面的冷风里，却不肯走开。"}]},"examples":[{"en":"Her desire to study abroad grew stronger every year.","cn":"她出国留学的愿望一年比一年强烈。"},{"en":"The old man desired nothing more than a quiet room.","cn":"老人最想要的只是一间安静的房间。"},{"en":"The letter expressed a desire for closer cooperation.","cn":"那封信表达了加强合作的意愿。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「底在儿」——心底一直垫着一样东西，伸出手却总差一点，就是渴望。","word":"desire"},"root":"拉丁 desiderare「渴望、思念」，经古法语 desirer 入英语。传统解释把它拆作「向下、离开」的拉丁前缀加 sidus「星」，意即「等待星辰带来」；这一说法来源不确定，一般认为是合理解释而非定论。同族有 desirous、desirable、desirability。","sensesIntro":{"en":"Eight senses follow one pull toward something not yet held. The pull can stay a general wish, start in the body, name its object, turn into a polite request, become a verb, appear in letters, aim at another person's action, or be studied as a mental state.","cn":"八个义项沿着同一股「朝尚未到手之物」的拉力展开：它可以是笼统的愿望、从身体开始、点出对象、转为礼貌请求、变成动词、出现在书信里、指向别人的行动，或被当作心理状态来研究。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pull toward something that is not yet in the hand.","cn":"核心意象：朝一件尚未到手之物伸去的拉力。"},"chain":["A PULL IS FELT","THE ABSENCE IS NOTICED","THE OBJECT IS NAMED","THE WISH IS SPOKEN","THE BODY JOINS IN","THE STATE IS STUDIED"],"branches":[{"senses":"01 · 03","en":"THE PULL AND ITS TARGET: the wanting and the thing wanted are two ends of one line, which is why the noun can name either.","cn":"拉力与目标：想要与所想要之物是同一条线的两端，所以这个名词可以指任何一端。"},{"senses":"02","en":"THE PULL STARTING IN THE BODY: appetite and sexual attraction are the same force with a physical origin.","cn":"从身体开始的拉力：食欲与性吸引是同一股力量，只是起点在身体。"},{"senses":"04 · 06","en":"THE PULL SPOKEN POLITELY: a wish put into words for another person becomes a formal request.","cn":"被礼貌说出的拉力：愿望一旦向别人说出口，就成了正式请求。"},{"senses":"05 · 07","en":"THE PULL AS AN ACTION: the verb wants a thing, or wants a person to do something.","cn":"作为动作的拉力：动词既可以要一件东西，也可以要一个人去做某事。"},{"senses":"08","en":"THE PULL STUDIED: once treated as a category, it becomes a mental state with direction, object and force.","cn":"被研究的拉力：一旦被当作范畴，它就成了有方向、有对象、有力量的心理状态。"}]},"affixes":{"intro":{"en":"Desire is a short verb whose traditional split is two Latin pieces, and the words built on it are mostly English suffixes added to that stem.","cn":"desire 是一个短动词，传统拆法是两个拉丁成分，而建在它之上的词多半是在这个词干后加英语词尾。"},"latinIntro":{"en":"Latin supplies the verb of longing, the noun for a star, and the noun for the thing wished for; the prefix in the traditional reading adds force rather than literal direction.","cn":"拉丁语这边提供了表示渴望的动词、表示星辰的名词，以及表示所渴望之物的名词；传统解读里的前缀加的是力度，而不是字面方向。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'down from, away')","meaning":"down from; away; in this word, force","meaningCN":"向下；离开；在本词中表力度","example":"The prefix is read as strengthening the verb rather than pointing anywhere.","exampleCN":"这个前缀在这里被理解为加强动词，而不是指向某个方向。"},{"word":"sidus","structure":"sidus, sideris (Latin noun, 'star, constellation')","meaning":"star; constellation","meaningCN":"星；星座","example":"The star element belongs to the traditional explanation of the verb.","exampleCN":"「星」这个成分属于对该动词的传统解释。"},{"word":"desiderare","structure":"desiderare (Latin verb, 'to long for, miss')","meaning":"to long for; to miss","meaningCN":"渴望；思念","example":"The Latin verb is the source of the whole family.","exampleCN":"这个拉丁动词是整族词的源头。"},{"word":"desire","structure":"desire (English noun and verb)","meaning":"a strong want; to want strongly","meaningCN":"强烈的想要；渴望","example":"The word keeps the pull without naming its object.","exampleCN":"这个词保留了拉力，却不点明对象。"},{"word":"desirous","structure":"desire + -ous","meaning":"full of wanting","meaningCN":"充满渴望的","example":"The adjective is formal and usually followed by of.","exampleCN":"这个形容词偏正式，通常后接表示对象的介词。"},{"word":"desirable","structure":"desire + -able","meaning":"worthy of being wanted","meaningCN":"值得被想要的","example":"The ending turns the want into a quality of the thing.","exampleCN":"这个词尾把「想要」转成事物的一种性质。"},{"word":"desirability","structure":"desirable + -ity","meaning":"the quality of being worth wanting","meaningCN":"值得想要的性质","example":"The noun measures how much something is wanted.","exampleCN":"这个名词衡量某物被想要的程度。"},{"word":"desired","structure":"desire + -ed","meaning":"wanted by someone","meaningCN":"被人想要的","example":"The participle describes the object, not the person.","exampleCN":"这个分词形容对象，而不是人。"},{"word":"desideratum","structure":"desideratum (Latin, 'something wished for')","meaning":"something needed and wished for","meaningCN":"所缺少而想要的东西","example":"The Latin noun survives in formal English.","exampleCN":"这个拉丁名词仍留在正式英语里。"}],"latinEntries":[{"word":"desiderare","structure":"desiderare, desideravi, desideratum (verb)","meaning":"to long for, wish for, miss","meaningCN":"渴望；想要；思念"},{"word":"sidus","structure":"sidus, sideris (n., third declension)","meaning":"star, constellation","meaningCN":"星；星座"},{"word":"desiderium","structure":"desiderium, desideri (n., second declension)","meaning":"longing, desire, regret","meaningCN":"渴望；欲望；怅惘"}],"derivatives":[{"word":"desirous","pos":"adj.","zh":"渴望的（desire 加表示「充满……」的形容词后缀，转为充满渴望的正式说法）"},{"word":"desirable","pos":"adj.","zh":"值得拥有的（desire 加表示「可被……」的形容词后缀，转为可被想要的性质）"},{"word":"desirability","pos":"n.","zh":"可欲性（desirable 加抽象名词后缀，转为可衡量的程度）"},{"word":"undesired","pos":"adj.","zh":"不想要的（否定前缀否定 desired，指未被渴望）"}]}},{"word":"desirable","ipa_uk":"/dɪˈzaɪərəbl/","ipa_us":"/dɪˈzaɪərəbl/","definition_zh":"值得拥有的；令人向往的；有吸引力的；可取的；合适的；优先的","definition_en":"worth wanting or having, often because it is attractive, useful or advisable","core_image":"橱窗里那件东西没有标价，路过的人却都停下来多看两眼","scene":"招聘启事把第二外语写在「优先」一栏，而不是「必需」一栏。The ad treats a second language as a desirable extra rather than a requirement.","sceneCN":"这里 desirable 指「有则更好的优先条件」（第 8 个义项：招聘广告里的优先项）；句意为广告把第二外语当作加分项，而不是硬性要求。","pos":[{"tag":"adj.","zh":"值得拥有的；令人向往的；有吸引力的；可取的；合适的"}],"collocations":[{"phrase":"highly desirable","zh":"非常令人向往的"},{"phrase":"a desirable outcome","zh":"理想的结果"},{"phrase":"desirable location","zh":"理想的地段"},{"phrase":"it is desirable to do something","zh":"做某事是可取的"},{"phrase":"desirable qualities","zh":"可取的品质"},{"phrase":"socially desirable","zh":"社会所赞许的"},{"phrase":"listed as desirable","zh":"被列为优先条件"}],"forms":[{"label":"比较级","form":"more desirable"},{"label":"最高级","form":"most desirable"},{"label":"副词","form":"desirably"},{"label":"名词（可欲性）","form":"desirability"},{"label":"否定形容词","form":"undesirable"}],"derivatives":[{"word":"desirability","pos":"n.","zh":"可欲性；吸引力（由 desirable 加名词后缀，把性质变成可衡量的程度）"},{"word":"desirably","pos":"adv.","zh":"可取地；合适地（由 desirable 加副词后缀，转为「以值得要的方式」）"},{"word":"undesirable","pos":"adj.","zh":"不受欢迎的（由否定前缀加 desirable，把「值得要」翻成「不该要」）"},{"word":"undesirability","pos":"n.","zh":"不受欢迎的性质（由 undesirable 加名词后缀，再转为名词）"}],"senses":[{"no":"01","title":"Worth having","titleCN":"值得拥有","definition":"worth wanting or owning because it is good or useful","definitionCN":"因为好或有用而值得想要、值得拥有","example":"They found a desirable apartment near the station.","exampleCN":"他们找到了一套靠近车站的理想公寓。","why":"The suffix -able means capable of being, so the word first says capable of being desired, then settles into worth wanting.","whyCN":"那个形容词后缀表示「可被……的」，所以这个词先说「可被渴望」，再稳定为「值得想要」。"},{"no":"02","title":"Physically attractive","titleCN":"外形上有吸引力","definition":"attractive to look at, especially in a romantic or social way","definitionCN":"看上去有吸引力，尤指在情感或社交层面","example":"The advertisement presents the model as a desirable partner.","exampleCN":"这则广告把这个模特呈现为令人向往的伴侣。","why":"The same worth-wanting can be carried by a body or a face, where the wanting is visual and social rather than practical.","whyCN":"同样的「值得想要」也可以由身体或面容承载，此时这份想要是视觉与社交的，而非实用的。"},{"no":"03","title":"Advisable to do","titleCN":"做某事是可取的","definition":"good or wise as a course of action","definitionCN":"作为一种做法是好的、明智的","example":"It is desirable to book your ticket well in advance.","exampleCN":"提前很久订票是可取的做法。","why":"When the thing wanted is an action rather than an object, the word shifts from attraction to advice.","whyCN":"当被想要的东西是行动而不是物件时，这个词就从「有吸引力」转向「值得建议」。"},{"no":"04","title":"An acceptable outcome","titleCN":"可接受的结果","definition":"a result that would be considered good if it came about","definitionCN":"一旦出现就会被认为不错的结果","example":"The committee reached a desirable compromise.","exampleCN":"委员会达成了一个理想的妥协。","why":"Outcomes can be ranked by how much they are wanted, so the adjective marks the end of a scale rather than a physical object.","whyCN":"结果可以按「有多想要」排序，所以这个形容词标的是梯子的顶端，而不是某件实物。"},{"no":"05","title":"Sought after in a market","titleCN":"市场上抢手","definition":"in demand among buyers, often because it is scarce","definitionCN":"在买家当中需求旺盛，常因稀缺","example":"Housing near the school is highly desirable and expensive.","exampleCN":"学校附近的房子非常抢手，也很贵。","why":"When many people want the same limited thing, being worth wanting turns into a market price.","whyCN":"当许多人想要同一件有限的东西时，「值得想要」就变成了市场价格。"},{"no":"06","title":"A quality that suits a purpose","titleCN":"适合某种用途的品质","definition":"a quality that fits a particular role or use well","definitionCN":"很适合某种角色或用途的品质","example":"Patience is a desirable quality in a nurse.","exampleCN":"耐心是护士身上一种可取的品质。","why":"Here the judgement is made against a role: the quality is wanted because the job needs it, not because it dazzles.","whyCN":"这里的判断是对着某个角色作出的：这种品质被想要，是因为工作需它，而不是因为它耀眼。"},{"no":"07","title":"Worthy of desire in philosophy","titleCN":"哲学上值得欲求的","definition":"in philosophy, describing what is properly an object of desire","definitionCN":"在哲学中，形容真正应当成为欲望对象的东西","example":"Philosophers ask whether the desirable is always the good.","exampleCN":"哲学家追问：值得欲求的是否总是善的。","why":"The adjective can be turned into a noun-like category, naming what ought to be wanted rather than what happens to be wanted.","whyCN":"这个形容词可以变成一个类名词的范畴，指「应当被想要」的东西，而不是「碰巧被想要」的东西。"},{"no":"08","title":"A preferred qualification","titleCN":"优先条件","definition":"in job notices, a qualification that is welcome but not required","definitionCN":"在招聘启事中，受欢迎但并非必需的条件","example":"Experience abroad is listed as desirable rather than essential.","exampleCN":"海外经历被列为优先条件，而不是必要条件。","why":"Employers rank requirements, and this word marks the tier that improves a candidate without disqualifying anyone who lacks it.","whyCN":"雇主会把条件分级，这个词标出的那一档能给候选人加分，却不会淘汰缺少它的人。"}],"etymology":{"intro":{"en":"Desirable is desire plus the ending -able, from Latin -abilis, capable of being. The Latin adjective desiderabilis already had the same shape, so the English word may have been formed at home or borrowed ready-made.","cn":"desirable 是 desire 加表示「可被……」的词尾，后者来自拉丁语中同义的形容词词尾。拉丁形容词 desiderabilis 早已是同样的形状，因此这个英语词可能是在本土造出，也可能是现成借入。"},"items":[{"era":"LATIN DESIDERARE","en":"The base verb desiderare means to long for or to miss, and it stands behind the whole family.","cn":"底下的动词 desiderare 意为「渴望、思念」，支撑着整个词族。"},{"era":"LATIN DESIDERABILIS","en":"Latin already had desiderabilis, meaning to be desired; it is generally considered the model or the direct source of the English adjective.","cn":"拉丁语早就有 desiderabilis，意为「值得被渴望」；一般认为它是这个英语形容词的模板或直接来源。"},{"era":"LATIN -ABILIS","en":"The ending -abilis means capable of being, and English keeps it as -able in a very large family of adjectives.","cn":"那个拉丁词尾意为「可被……的」，英语把它保留为同样的形容词词尾，用在非常庞大的形容词词族里。"},{"era":"OLD FRENCH","en":"Old French passed on the verb desirer, and an adjective of the same meaning is recorded in later French usage.","cn":"古法语传下了动词 desirer，同义的形容词也见于后来的法语用法。"},{"era":"ENGLISH FORMATION","en":"English shows the adjective around 1600, formed on desire with -able or taken from the Latin adjective; the two routes are hard to separate.","cn":"英语在 1600 年前后出现这个形容词，或由 desire 加那个形容词词尾造出，或直接取自拉丁形容词；两条路径很难分开。"},{"era":"MODERN ENGLISH","en":"Modern usage widened it from worth wanting to attractive, advisable, and finally to a preferred job qualification.","cn":"现代用法把它从「值得想要」扩展到「有吸引力」「可取」，最后又扩展到招聘中的优先条件。"}]},"similar":{"note":{"en":"The first group holds forms that sit very close in shape but do different jobs; the second holds words that also praise something as worth having, each from a different angle.","cn":"第一组是外形贴得很近、功能却不同的形式；第二组是同样称赞某物值得拥有、但角度不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"desire","ipa":"/dɪˈzaɪə/","tag":"same family, the want itself","definition":"The noun and verb for the feeling of wanting; it names the pull, while desirable names the quality of the thing that pulls.","definitionCN":"表示「想要」这一感受的名词与动词；它命名拉力，而 desirable 命名被拉之物的性质。"},{"word":"desirous","ipa":"/dɪˈzaɪərəs/","tag":"same family, a person","definition":"A formal adjective for a person full of wanting, usually with of; it describes the wanter, not the wanted thing.","definitionCN":"形容人满怀渴望的正式形容词，通常带表示对象的介词；它形容想要的人，而不是被想要之物。"},{"word":"desert","ipa":"/ˈdezət/","tag":"not related","definition":"From Latin deserere, to abandon; the landscape has nothing to do with wanting, despite the similar spelling.","definitionCN":"来自拉丁 deserere「抛弃」；尽管拼写相近，这片地貌与「想要」毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attractive","ipa":"/əˈtræktɪv/","tag":"pulling the eye","definition":"Pleasing to look at or appealing in a general way; it works mainly through appearance, while desirable can also work through usefulness.","definitionCN":"好看或大体上有吸引力；主要靠外表起作用，而 desirable 也可以靠实用性起作用。"},{"word":"advisable","ipa":"/əˈvaɪsəbl/","tag":"good to do","definition":"Wise or sensible as a course of action; it only describes actions, never objects or people.","definitionCN":"作为一种做法明智可取；它只形容行动，不形容物品或人。"},{"word":"preferable","ipa":"/ˈprefərəbl/","tag":"better of two","definition":"Better than the other option in a comparison; it always implies a rival, which desirable does not.","definitionCN":"在比较中比另一个选项更好；它总含有一个对手，而 desirable 不必。"},{"word":"coveted","ipa":"/ˈkʌvətɪd/","tag":"wanted by many","definition":"Eagerly wanted by many people, often with a hint of envy; it stresses competition rather than inherent worth.","definitionCN":"被许多人急切想要，常带一点嫉妒；强调争夺，而非事物本身的价值。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The ending -able means capable of being, so desirable says capable of being desired, hence worth wanting.","cn":"那个形容词词尾表示「可被……的」，所以 desirable 就是「可被渴望的」，也就是值得想要。"},{"en":"The base is desire, and the family runs desire, desirous, desirable, desirability, undesirable.","cn":"底座是 desire，同族有 desire、desirous、desirable、desirability、undesirable。"},{"en":"Fixed phrases place it in real contexts: highly desirable, a desirable outcome, desirable qualities, listed as desirable.","cn":"固定搭配把它放进真实语境：非常抢手、理想的结果、可取的品质、被列为优先条件。"},{"en":"Latin already had desiderabilis with exactly this shape, so the English word is not an odd invention.","cn":"拉丁语早有形状完全相同的 desiderabilis，所以这个英语词并非生造。"},{"en":"In job advertisements the word marks the preferred tier, above essential and below nothing.","cn":"在招聘广告里，这个词标出「优先」那一档，在「必需」之下，却也不是可有可无。"}],"abstract":[{"en":"Picture an object in a window with no price tag, and passers-by slowing down without knowing why.","cn":"想象橱窗里一件没有标价的东西，路人不知道为什么就放慢了脚步。"},{"en":"Picture a hand hovering over two nearly equal options, and settling on one.","cn":"想象一只手在两个几乎相同的选项上方悬着，最后落在其中一个上。"},{"en":"Picture a row of houses where every buyer stops at the same front gate.","cn":"想象一排房子前，每个买家都在同一扇院门前停下。"}]},"examples":[{"en":"A quiet street is desirable for families with small children.","cn":"对有小孩的家庭来说，安静的街道很理想。"},{"en":"It is desirable that all applicants submit two references.","cn":"所有申请人都提交两份推荐信是可取的做法。"},{"en":"The company offered a desirable salary to attract experienced staff.","cn":"公司开出诱人的薪水以吸引有经验的员工。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「desire（想要）+ able（能）——能被想要的」，就是值得拥有的；谐音可记「底扎尔勒伯」。","word":"desirable"},"root":"由 desire 加拉丁形容词词尾（意为「可被……」）构成；拉丁语本身已有 desiderabilis「值得被渴望」，一般认为它是直接来源或模板。源头仍是 desiderare「渴望」，其传统解释把拉丁动词拆作「向下、离开」的前缀加 sidus「星」，这一说法来源不确定。同族有 desirability、undesirable。","sensesIntro":{"en":"Eight senses branch from one act of valuation: a thing or a course of action is marked as worth wanting. That mark can fall on an object, a body, an action, an outcome, a scarce market good, a fitting quality, a philosophical category, or a line in a job notice.","cn":"八个义项从同一次估价分叉：某件东西或某种做法被标为「值得想要」。这个标记可以落在物品、身体、行动、结果、稀缺的市场商品、合用的品质、哲学范畴，或招聘启事的一行字上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mark of worth placed on something, visible to anyone who looks.","cn":"核心意象：盖在某件东西上的「值得」印记，谁看见都能认出。"},"chain":["MARKED AS WORTH WANTING","THE EYE IS CAUGHT","THE QUALITY FITS THE ROLE","THE ACTION IS ADVISED","THE MARKET SETS A PRICE","THE NOTICE LISTS A PREFERENCE"],"branches":[{"senses":"01 · 02","en":"TWO FACES OF ATTRACTION: worth owning and physical appeal are the same mark, one practical and one visual.","cn":"吸引力的两副面孔：值得拥有与外形吸引是同一个印记，一个偏实用，一个偏视觉。"},{"senses":"03 · 04","en":"THE JUDGEMENT SIDE: an action can be advisable and an outcome acceptable, because both are chosen before they exist.","cn":"判断的一面：行动可以「可取」，结果可以「理想」，因为两者都在发生之前就被选中。"},{"senses":"05 · 06","en":"THE QUALITY IN THE WORLD: scarcity raises a price, and a role decides which qualities are wanted.","cn":"世界中的品质：稀缺抬高价格，而角色决定哪些品质被需要。"},{"senses":"07","en":"THE CATEGORY ITSELF: philosophy turns the mark into a question about what ought to be desired.","cn":"范畴本身：哲学把这个印记变成一个关于「什么应当被欲求」的问题。"},{"senses":"08","en":"THE MARK ON A FORM: in a job notice the same word becomes a tier between essential and optional.","cn":"表格上的印记：在招聘启事里，同一个词变成「必需」与「可有」之间的一档。"}]},"affixes":{"intro":{"en":"Desirable is one stem plus one very common ending, and both pieces can be traced to Latin words that English still uses.","cn":"desirable 是一个词干加一个极常见的词尾，两块都能追到英语至今仍在用的拉丁词。"},"latinIntro":{"en":"Latin provides the verb of longing, the adjective built from it, and the ending meaning capable of being; the ending is the piece that makes the word a judgement rather than a feeling.","cn":"拉丁语提供了表示渴望的动词、由它构成的形容词，以及意为「可被……」的词尾；正是这个词尾让这个词成为判断，而不是感受。"},"items":[{"word":"desire","structure":"desire (English noun and verb)","meaning":"a strong want; to want strongly","meaningCN":"强烈的想要；渴望","example":"The base supplies the pull that the adjective evaluates.","exampleCN":"词干提供了被形容词评价的那股拉力。"},{"word":"-able","structure":"-able (adjective ending from Latin -abilis)","meaning":"capable of being","meaningCN":"可被……的","example":"The ending turns a verb into a description of what can be done to a thing.","exampleCN":"这个词尾把动词变成「某物可被怎样」的描述。"},{"word":"desirable","structure":"desire + -able","meaning":"capable of being desired, hence worth wanting","meaningCN":"可被渴望的，因而值得想要","example":"The adjective judges the object, not the person.","exampleCN":"这个形容词评判对象，而不是人。"},{"word":"desirability","structure":"desirable + -ity","meaning":"the quality of being worth wanting","meaningCN":"值得想要的性质","example":"The noun turns the judgement into a measurable quality.","exampleCN":"这个名词把判断变成可衡量的性质。"},{"word":"desirably","structure":"desirable + -ly","meaning":"in a way that is worth wanting","meaningCN":"以值得想要的方式","example":"The adverb describes how something is arranged.","exampleCN":"这个副词描述某事被安排得如何。"},{"word":"undesirable","structure":"un- + desirable","meaning":"not worth wanting; unwelcome","meaningCN":"不值得要的；不受欢迎的","example":"The prefix reverses the judgement in one step.","exampleCN":"这个前缀一步就把判断反过来。"},{"word":"desirous","structure":"desire + -ous","meaning":"full of wanting","meaningCN":"满怀渴望的","example":"This adjective describes the person rather than the object.","exampleCN":"这个形容词形容人，而不是对象。"},{"word":"desiderare","structure":"desiderare (Latin verb, 'to long for, miss')","meaning":"to long for; to miss","meaningCN":"渴望；思念","example":"The Latin verb stands behind every word in the family.","exampleCN":"这个拉丁动词站在整族词背后。"},{"word":"desiderabilis","structure":"desiderabilis, -e (Latin adjective)","meaning":"to be desired; desirable","meaningCN":"值得被渴望的","example":"The Latin adjective already had the shape of the English one.","exampleCN":"这个拉丁形容词早已具有英语词的那个形状。"}],"latinEntries":[{"word":"desiderabilis","structure":"desiderabilis, desiderabile (adjective)","meaning":"to be desired, desirable","meaningCN":"值得被渴望的；可欲的"},{"word":"desiderare","structure":"desiderare, desideravi, desideratum (verb)","meaning":"to long for, wish for, miss","meaningCN":"渴望；想要；思念"},{"word":"desiderium","structure":"desiderium, desideri (n., second declension)","meaning":"longing, desire, regret","meaningCN":"渴望；欲望；怅惘"}],"derivatives":[{"word":"desirability","pos":"n.","zh":"可欲性（desirable 加抽象名词后缀，转为可衡量的性质）"},{"word":"desirably","pos":"adv.","zh":"可取地（desirable 加副词后缀，转为方式）"},{"word":"undesirable","pos":"adj.","zh":"不受欢迎的（否定前缀否定本词，指不值得要）"},{"word":"undesirability","pos":"n.","zh":"不受欢迎的性质（undesirable 加抽象名词后缀，转为名词）"}]}},{"word":"willingness","ipa_uk":"/ˈwɪlɪŋnəs/","ipa_us":"/ˈwɪlɪŋnəs/","definition_zh":"乐意；自愿；意愿；积极性","definition_en":"the state of being ready and glad to do something without being forced","core_image":"会议室里别人都在看表，一个人先举起手，说这活我来","scene":"项目收尾会上，负责人问谁愿意周末来整理资料，几个人低头看手机，只有她把杯子放下，说算我一个。Her willingness to give up a weekend made the room go quiet for a second.","sceneCN":"这里 willingness 指「不带勉强地乐意去做」（第 1 个义项：主动愿意行动的状态）；句意为她愿意牺牲一个周末，这让屋里安静了一瞬。","pos":[{"tag":"n.","zh":"乐意；自愿；意愿；积极性（不可数）"}],"collocations":[{"phrase":"willingness to do something","zh":"愿意做某事"},{"phrase":"willingness to pay","zh":"支付意愿"},{"phrase":"willingness to accept","zh":"接受意愿；补偿意愿"},{"phrase":"show willingness","zh":"表现出意愿"},{"phrase":"a lack of willingness","zh":"缺乏意愿"},{"phrase":"willingness to learn","zh":"学习意愿"},{"phrase":"willingness to cooperate","zh":"合作意愿"}],"forms":[{"label":"不可数名词（通常无复数）","form":"willingness"},{"label":"形容词（基础）","form":"willing"},{"label":"副词","form":"willingly"},{"label":"否定形容词","form":"unwilling"},{"label":"否定名词","form":"unwillingness"}],"derivatives":[{"word":"willingly","pos":"adv.","zh":"乐意地（由 willing 加副词后缀，把意愿转成动作方式）"},{"word":"unwilling","pos":"adj.","zh":"不愿意的（由否定前缀加 willing，把意愿整个翻转为拒绝）"},{"word":"unwillingly","pos":"adv.","zh":"不情愿地（由否定前缀加 willing 再加副词后缀，动作方式带上抵触）"},{"word":"unwillingness","pos":"n.","zh":"不情愿（由否定前缀加 willing 再加名词后缀，由乐意翻转成拒绝的状态）"}],"senses":[{"no":"01","title":"Readiness to act","titleCN":"乐意行动的意愿","definition":"the state of being ready and glad to do something","definitionCN":"愿意并且乐意去做某事的状态","example":"Her willingness to help made the whole project easier.","exampleCN":"她愿意帮忙，让整个项目轻松了不少。","why":"Willingness begins as a hand already raised: the person does not need to be pushed, because the decision is made before the request ends.","whyCN":"willingness 的起点是一只已经举起的手：这个人不需要别人推，因为在请求说完之前，决定已经做好了。"},{"no":"02","title":"Consent freely given","titleCN":"自愿给出的同意","definition":"free agreement to something, given without pressure or trickery","definitionCN":"在没有压力或欺骗的情况下自由地同意某事","example":"The form records each volunteer's willingness to join the study.","exampleCN":"这张表格记录每位志愿者加入研究的意愿。","why":"A signature is the visible edge of an invisible yes; the noun turns private readiness into public permission.","whyCN":"签名是一个看不见的「好」露出的边缘；这个名词把私人的乐意变成公开的许可。"},{"no":"03","title":"Eagerness and drive","titleCN":"热情与干劲","definition":"a positive, energetic attitude toward a task","definitionCN":"对任务抱着积极而有活力的态度","example":"New staff often bring a willingness that long-serving employees have lost.","exampleCN":"新员工常带着一股老员工已经失去的干劲。","why":"When readiness is charged with energy, it stops being mere permission and becomes a force that pushes work forward.","whyCN":"当乐意被注满能量，它就不再只是许可，而变成推动工作往前走的力量。"},{"no":"04","title":"Willingness to pay","titleCN":"支付意愿","definition":"the highest price a buyer would be willing to pay for a good or service","definitionCN":"经济学中，买方愿意为某商品或服务支付的最高价格","example":"Economists measured willingness to pay before setting the ticket price.","exampleCN":"经济学家在定票价之前先测量了支付意愿。","why":"The abstract noun becomes a number: readiness is converted into the top price a person would still say yes to.","whyCN":"这个抽象名词变成了一个数字：乐意被换算成一个人仍然会说「好」的最高价。"},{"no":"05","title":"Willingness to accept","titleCN":"接受意愿","definition":"in economics, the lowest compensation a person would accept for giving something up","definitionCN":"经济学中，一个人放弃某物所愿意接受的最低补偿","example":"The survey compared willingness to accept with willingness to pay for the same park.","exampleCN":"这项调查把同一座公园的接受意愿与支付意愿作了比较。","why":"The mirror image of the previous sense: here the yes is about parting with something, so the number is a minimum rather than a maximum.","whyCN":"这是上一个义项的镜像：这里的「好」是关于失去某物，所以数字是最低而不是最高。"},{"no":"06","title":"Willingness to communicate","titleCN":"交际意愿","definition":"in language teaching, a learner's readiness to speak or interact in the target language","definitionCN":"语言教学中，学习者在目标语言中开口或互动的意愿","example":"A supportive classroom can raise a shy learner's willingness to communicate.","exampleCN":"有支持的课堂能提高害羞学习者的交际意愿。","why":"Readiness is now aimed at speaking itself; it is not about a task but about entering a conversation that may expose the learner.","whyCN":"这里的乐意指向「开口」本身；它不是针对某项任务，而是针对进入一场可能让学习者暴露自己的对话。"},{"no":"07","title":"Willingness to concede","titleCN":"让步意愿","definition":"in negotiation, readiness to give ground or accept less than one first asked for","definitionCN":"谈判中，愿意让出阵地或接受少于最初要求的条件","example":"The union showed little willingness to concede on working hours.","exampleCN":"工会在工时问题上几乎没有表现出让步意愿。","why":"The same yes is now costly: readiness to move means readiness to lose a little, which is why negotiators watch it so closely.","whyCN":"同一个「好」现在有了代价：愿意挪动就是愿意少拿一点，所以谈判者才盯得这么紧。"},{"no":"08","title":"Willingness to help others","titleCN":"助人意愿","definition":"in social behaviour, readiness to give time or effort to another person without reward","definitionCN":"社会行为中，愿意把时间或精力给他人而不求回报","example":"Neighbours showed real willingness to help after the flood.","exampleCN":"洪水过后，邻居们表现出实实在在的助人意愿。","why":"Here readiness points outward at another person's need, and the reward is often nothing more than the act itself.","whyCN":"这里的乐意朝外指向另一个人的需要，回报往往就是行动本身。"}],"etymology":{"intro":{"en":"Willingness is a native English formation: the adjective willing plus the old noun ending -ness. No Latin borrowing is involved in this family.","cn":"willingness 是本土英语构成：形容词 willing 加古老的名词词尾。这一词族没有拉丁语借入成分。"},"items":[{"era":"OLD ENGLISH","en":"The base is Old English willan 'to wish, desire', whose present participle willende is the ancestor of willing. The noun willa 'mind, desire' belongs to the same family.","cn":"基础是古英语 willan「希望、意愿」，它的现在分词 willende 就是 willing 的祖先；名词 willa「心意、愿望」属于同一词族。"},{"era":"PROTO-GERMANIC","en":"The verb is reconstructed as *willjan 'to will, wish', with the related noun *wiljo 'will, desire'. Both forms are reconstructions, not recorded words.","cn":"这个动词被重构为原始日耳曼语 *willjan「愿意、希望」，相关名词是 *wiljo「意愿、愿望」。两者都是重构形式，不是有记录的词。"},{"era":"OLD ENGLISH SUFFIX","en":"The ending -nes formed abstract nouns from adjectives, as in godnes 'goodness'; in later spelling it became -ness, the same ending heard in willingness today.","cn":"古英语的词尾把形容词变成抽象名词，如 godnes「善」；后来拼写固定为今天的形状，也就是 willingness 里的那个名词词尾。"},{"era":"MIDDLE ENGLISH","en":"Willing and -ness were joined to name the state rather than the person: not a willing man, but the willingness inside him. The word is recorded from the fourteenth century.","cn":"willing 与那个名词词尾合起来，指状态而不是人：不是「一个乐意的人」，而是他心里的「乐意」。这个词从十四世纪起有记录。"},{"era":"MODERN ENGLISH","en":"The noun spread into psychology, economics and language teaching, where it names measurable readiness: willingness to pay, to accept, to communicate.","cn":"这个名词后来进入心理学、经济学与语言教学，用来指可测量的乐意程度：支付意愿、接受意愿、交际意愿。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close and are often mixed up with willingness; the second holds neighbours that also describe a yes, but from a different angle.","cn":"第一组是与 willingness 形近或音近、常被混淆的词；第二组是同为「答应」却从不同角度描述的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"willing","ipa":"/ˈwɪlɪŋ/","tag":"same family","definition":"The adjective that supplies the stem: willing describes the person, while willingness names the state.","definitionCN":"提供词干的形容词：willing 描写人，willingness 指状态。"},{"word":"unwilling","ipa":"/ʌnˈwɪlɪŋ/","tag":"same family, negated","definition":"The same adjective with the negative prefix un-, so the family meaning is reversed rather than changed.","definitionCN":"同一个形容词加上否定前缀，词族意义只是反转，并未换掉。"},{"word":"wiliness","ipa":"/ˈwaɪlinəs/","tag":"not related","definition":"Craftiness, from wily and wile 'a trick'. It looks like willingness but has a different vowel and a different root.","definitionCN":"狡猾，来自 wily 与 wile「诡计」。它看起来像 willingness，但元音不同，词根也不同，两者并无亲缘关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"readiness","ipa":"/ˈredinəs/","tag":"prepared, not necessarily glad","definition":"The state of being prepared or available; it stresses preparation, while willingness stresses the inner yes.","definitionCN":"准备好的状态；强调准备就绪，而 willingness 强调内心的同意。"},{"word":"eagerness","ipa":"/ˈiːɡənəs/","tag":"hotter desire","definition":"Keen and impatient desire to do something; it is warmer and more urgent than willingness.","definitionCN":"急切而按捺不住地想做事；比 willingness 更热、更急。"},{"word":"consent","ipa":"/kənˈsent/","tag":"formal permission","definition":"Formal permission, especially in law or medicine; willingness can be the feeling behind it.","definitionCN":"正式许可，尤其用于法律或医疗；willingness 可以是许可背后的那份心意。"},{"word":"inclination","ipa":"/ˌɪŋklɪˈneɪʃən/","tag":"mild leaning","definition":"A mild preference or leaning toward something, with less commitment than willingness.","definitionCN":"轻微的偏好或倾向，承诺程度低于 willingness。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词语素、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"will (to wish) + -ing + -ness: the noun literally names 'the state of wishing'.","cn":"will（希望）加现在分词词尾再加名词词尾：这个名词字面上就是「希望的状态」。"},{"en":"The family runs willing, willingly, willingness, unwilling, unwillingness.","cn":"同族词包括 willing、willingly、willingness、unwilling、unwillingness。"},{"en":"Fixed phrases show what the readiness is aimed at: willingness to pay, willingness to accept, willingness to communicate.","cn":"固定搭配标出乐意指向什么：支付意愿、接受意愿、交际意愿。"},{"en":"The opposite is built with un-: unwillingness is the same noun with the yes turned into a no.","cn":"反义词靠否定前缀构成：unwillingness 就是同一个名词，把「好」翻成了「不」。"},{"en":"Economics turns the noun into a number: the top price you would still pay.","cn":"经济学把这个名词变成数字：你仍然愿意付的最高价。"}],"abstract":[{"en":"Picture a hand already raised before the question is finished.","cn":"想象一只在问题说完之前就已经举起的手。"},{"en":"Picture a door opened from the inside, not pushed from the outside.","cn":"想象一扇从里面打开的门，而不是被外面推开的门。"},{"en":"Picture a yes that costs something, which is exactly why it is trusted.","cn":"想象一个要付出代价的「好」，正因如此它才可信。"}]},"examples":[{"en":"His willingness to listen made her tell the whole story.","cn":"他愿意倾听，让她把整件事都说了出来。"},{"en":"The company surveyed customers' willingness to pay for faster delivery.","cn":"公司调查了顾客为更快配送付费的意愿。"},{"en":"Willingness alone is not enough; the team also needs time and tools.","cn":"光有意愿还不够，团队还需要时间和工具。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「威廉尼斯」—— 威廉先举手说这活我来，这股主动劲儿就是乐意 → willingness 乐意；意愿","word":"willingness"},"root":"本土日耳曼语线：古英语 willan「希望、意愿」的现在分词 willing，加表示状态的名词词尾；这一词族在英语中没有从拉丁语借入的同族词。","sensesIntro":{"en":"Eight senses grow from one inner yes: a hand raised before the request ends. That yes can become public consent, gain energy, turn into a measurable price, aim at speaking, accept a loss, or reach out to someone else.","cn":"八个义项都从同一个内心的「好」长出来：在请求说完之前举起手。这个「好」可以变成公开同意、带上干劲、换算成可测的价格、指向开口、接受损失，或伸向别人。"},"semanticMap":{"core":{"en":"CORE IMAGE: an inner yes that needs no push.","cn":"核心意象：一个不需要别人推的内心「好」。"},"chain":["WILLING MIND","OPEN DOOR","RAISED HAND","FREE CONSENT","COSTLY YES","MEASURED YES"],"branches":[{"senses":"01","en":"THE CORE: readiness appears as a hand already raised, before anyone finishes asking.","cn":"核心：乐意表现为一只已经举起的手，在别人还没问完时就出现了。"},{"senses":"02 · 03","en":"TWO FACES OF THE YES: it can be quiet legal consent or energetic cooperation.","cn":"「好」的两副面孔：可以是安静的法律同意，也可以是带劲的配合。"},{"senses":"04 · 05","en":"THE YES AS A NUMBER: economics turns readiness into a maximum price or a minimum compensation.","cn":"把「好」变成数字：经济学把乐意换算成最高出价或最低补偿。"},{"senses":"06 · 07","en":"THE YES UNDER PRESSURE: speaking in another language and giving ground in a deal both expose the person.","cn":"压力下的「好」：用另一种语言开口，以及在交易中让步，都会让人暴露。"},{"senses":"08","en":"THE YES TURNED OUTWARD: readiness spends itself on another person's need.","cn":"朝外的「好」：乐意把自身花在别人的需要上。"}]},"affixes":{"intro":{"en":"Willingness is built from a Germanic verb root plus two very common endings, and the whole family can be read morpheme by morpheme.","cn":"willingness 由日耳曼语动词词根加两个极常见的词尾构成，整个词族可以按语素逐个读出。"},"latinIntro":{"en":"The root is the native Germanic will; English has no Latin-borrowed relative of this family, so the Latin section is intentionally empty.","cn":"这个词根是本土日耳曼语的 will；英语中没有从拉丁语借入的这一词族成员，因此拉丁同族词部分有意留空。"},"items":[{"word":"will","structure":"Old English willan 'to wish, desire' (verb root)","meaning":"to wish; to desire; the power of choosing","meaningCN":"希望；意愿；选择的能力","example":"The whole family rests on the old verb will.","exampleCN":"整个词族都建立在古老的动词 will 上。"},{"word":"-ing","structure":"-ing (present-participle and adjective ending)","meaning":"the ending that turns the verb into 'the one who wills'","meaningCN":"把动词变成「正在愿意的人」的词尾","example":"Willing is the participle of will before it became an adjective.","exampleCN":"willing 在变成形容词之前，本是 will 的分词。"},{"word":"-ness","structure":"-ness (Old English -nes, noun of state)","meaning":"the ending that names a state or quality","meaningCN":"指状态或性质的词尾","example":"The ending turns a description into a noun.","exampleCN":"这个词尾把描写变成名词。"},{"word":"willingness","structure":"willing + -ness","meaning":"the state of being ready and glad","meaningCN":"乐意、愿意的状态","example":"Willingness opened the first meeting.","exampleCN":"乐意让第一次会议开了个好头。"},{"word":"unwilling","structure":"un- (not) + willing","meaning":"not ready or glad to do something","meaningCN":"不愿意的（否定前缀加 willing）","example":"He was unwilling to sign the form.","exampleCN":"他不愿意在表格上签字。"},{"word":"unwillingness","structure":"un- + willing + -ness","meaning":"the state of not being ready","meaningCN":"不愿意的状态","example":"Her unwillingness was polite but clear.","exampleCN":"她的不愿意很客气，但很清楚。"},{"word":"willingly","structure":"willing + -ly (adverb)","meaning":"in a ready and glad way","meaningCN":"乐意地","example":"They stayed late willingly.","exampleCN":"他们乐意地留到很晚。"},{"word":"goodwill","structure":"good + will","meaning":"friendly feeling that makes one ready to help","meaningCN":"善意；愿意帮忙的友好心意","example":"The gift was a sign of goodwill.","exampleCN":"这份礼物是善意的表示。"},{"word":"free will","structure":"free + will","meaning":"the power to choose without being forced","meaningCN":"自由意志；不受强迫的选择能力","example":"The argument turns on free will.","exampleCN":"这场争论的关键是自由意志。"}],"latinEntries":[],"derivatives":[{"word":"willingly","pos":"adv.","zh":"乐意地（willing 加副词后缀，把意愿转成动作方式）"},{"word":"unwilling","pos":"adj.","zh":"不愿意的（否定前缀加 willing，把乐意翻转成拒绝）"},{"word":"unwillingly","pos":"adv.","zh":"不情愿地（否定前缀加 willing 再加副词后缀，动作带上抵触）"},{"word":"unwillingness","pos":"n.","zh":"不情愿（否定前缀加 willing 再加名词后缀，指拒绝的状态）"}]}},{"word":"willing","ipa_uk":"/ˈwɪlɪŋ/","ipa_us":"/ˈwɪlɪŋ/","definition_zh":"愿意的；乐意的；自愿的；甘愿的；听话的；愿意倾听的","definition_en":"ready or glad to do something, often without being asked or forced","core_image":"一个本来可以拒绝的人，把已经放下的工具又拿起来，说好，我来","scene":"搬家前夜，朋友临时说缺一个人手，他本已请了假，却还是把外套挂回门边，问几点到。He was willing to give up his day off and asked what time to arrive.","sceneCN":"这里 willing 指「本来可以拒绝却乐意答应」（第 1 个义项：愿意做某事）；句意为尽管请了假，他还是愿意放弃休息，并问几点到。","pos":[{"tag":"adj.","zh":"愿意的；乐意的；自愿的；甘愿的；顺从的"}],"collocations":[{"phrase":"be willing to do","zh":"愿意做某事"},{"phrase":"a willing helper","zh":"热心的帮手"},{"phrase":"willing consent","zh":"自愿同意"},{"phrase":"a willing ear","zh":"愿意倾听的人"},{"phrase":"willing hands","zh":"乐意帮忙的人手"},{"phrase":"God willing","zh":"如果天意允许；但愿"}],"forms":[{"label":"比较级","form":"more willing"},{"label":"最高级","form":"most willing"},{"label":"副词","form":"willingly"},{"label":"名词（乐意）","form":"willingness"},{"label":"否定形容词","form":"unwilling"},{"label":"否定副词","form":"unwillingly"}],"derivatives":[{"word":"willingly","pos":"adv.","zh":"乐意地（由 willing 加副词后缀，把乐意转成动作方式）"},{"word":"willingness","pos":"n.","zh":"乐意；意愿（由 willing 加名词后缀，从人的态度转为抽象状态）"},{"word":"unwilling","pos":"adj.","zh":"不愿意的（由否定前缀加 willing，把乐意整个反转）"},{"word":"unwillingness","pos":"n.","zh":"不情愿（由否定前缀加 willing 再加名词后缀，指拒绝的心理状态）"}],"senses":[{"no":"01","title":"Ready to do something","titleCN":"愿意做某事","definition":"prepared and glad to do something if asked or needed","definitionCN":"如果被请求或需要，愿意并且乐意去做","example":"She is always willing to answer questions after class.","exampleCN":"她课后总是愿意回答问题。","why":"The adjective starts from an open door: nothing blocks the action, so the person can say yes at once.","whyCN":"这个形容词从一扇开着的门开始：没有什么挡住行动，所以人立刻就能说「好」。"},{"no":"02","title":"Giving consent without pressure","titleCN":"自愿同意","definition":"agreeing freely, with no force or trickery","definitionCN":"自由地同意，没有强迫或欺骗","example":"Participants gave willing consent before the interviews began.","exampleCN":"访谈开始前，参与者自愿表示了同意。","why":"Willingness here is legal and ethical: the yes must come from the person's own decision, not from a push.","whyCN":"这里的乐意带有法律与伦理意味：这个「好」必须出自行本人的决定，而不是被推出来的。"},{"no":"03","title":"Eager and cooperative","titleCN":"热心配合的","definition":"showing eagerness to join in and help","definitionCN":"表现出想加入和帮忙的热切","example":"The new intern was a willing helper at every event.","exampleCN":"新来的实习生在每场活动上都是个热心的帮手。","why":"Readiness with energy becomes cooperation; the person does not wait to be told but steps toward the work.","whyCN":"乐意加上能量就成了配合：这个人不等别人开口，而是自己朝工作迈过去。"},{"no":"04","title":"Done or given freely","titleCN":"甘愿付出的","definition":"offered or accepted without complaint, even at a real cost","definitionCN":"即使有实际代价，也毫无怨言地给出或接受","example":"Their willing sacrifice kept the shelter open all winter.","exampleCN":"他们甘愿付出，让收容所整个冬天都开着。","why":"When the cost is real, the yes is no longer cheap; the word then points at generosity rather than mere permission.","whyCN":"当代价真实存在，这个「好」就不再廉价；词义随之指向慷慨，而不只是许可。"},{"no":"05","title":"Easily managed","titleCN":"听话的；顺手的","definition":"compliant and easy to direct, sometimes with less independence than is healthy","definitionCN":"顺从、容易指挥，有时独立性不足","example":"The manager wanted a willing instrument rather than a thinking partner.","exampleCN":"这位经理想要一件顺手的工具，而不是一个会思考的伙伴。","why":"Something that never resists can be used like a tool; the word slides from readiness into pliability, and the tone can turn critical.","whyCN":"从不抵抗的东西可以像工具一样被使用；词义从乐意滑向易摆布，语气也可能转为批评。"},{"no":"06","title":"God willing","titleCN":"但愿；如果天意允许","definition":"used in the fixed phrase God willing to mean 'if nothing prevents it'","definitionCN":"用于表示「但愿如此」的固定说法，表示「如果没有阻碍的话」","example":"God willing, we will meet again next spring.","exampleCN":"但愿明年春天我们还能再见。","why":"The phrase leaves the final decision to a higher power: human readiness is real, but it is not the last word.","whyCN":"这个短语把最终决定交给更高的力量：人的乐意是真的，但不是最后一句话。"},{"no":"07","title":"Willing suspension of disbelief","titleCN":"自愿暂时相信","definition":"in literary theory, the reader's choice to accept a story's impossible events","definitionCN":"文学理论中，读者选择接受故事里不可能发生的事","example":"The opening scene earns the audience's willing suspension of disbelief.","exampleCN":"开场那一场戏赢得了观众自愿的暂时相信。","why":"The reader knows the story is not real and still agrees to be moved; readiness is aimed at belief itself.","whyCN":"读者知道故事不真实，却仍然同意被打动；这里的乐意指向的是「相信」本身。"},{"no":"08","title":"A willing ear","titleCN":"愿意倾听的人","definition":"in the fixed phrase a willing ear, a person who listens readily","definitionCN":"指在固定说法中乐意听人说话的人","example":"After the long trip, he found a willing ear in the station café.","exampleCN":"长途旅行之后，他在车站咖啡馆里找到一个愿意听他说的人。","why":"The ear stands for the whole person: readiness is concentrated in one body part that is offered to someone else's story.","whyCN":"耳朵代指整个人：乐意集中在一个身体部位上，被递给别人的故事。"}],"etymology":{"intro":{"en":"Willing is the present-participle adjective of the native Germanic verb will, recorded in English from the early fourteenth century. No Latin borrowing is involved in this family.","cn":"willing 是本土日耳曼语动词 will 的现在分词形容词，从十四世纪初起在英语中有记录。这一词族没有拉丁语借入成分。"},"items":[{"era":"OLD ENGLISH","en":"Old English willan meant 'to wish, desire; be willing'. Its present participle willende is the direct ancestor of the modern form willing.","cn":"古英语 willan 意为「希望、意愿；愿意」，它的现在分词 willende 就是现代形式 willing 的直接祖先。"},{"era":"PROTO-GERMANIC","en":"The verb is reconstructed as *willjan 'to will, wish', with the noun *wiljo 'will, desire'. These are reconstructed forms, not attested words.","cn":"这个动词被重构为原始日耳曼语 *willjan「愿意、希望」，名词是 *wiljo「意愿、愿望」。这些都是重构形式，不是有记录的词。"},{"era":"MIDDLE ENGLISH","en":"By the early fourteenth century willing was used as an adjective meaning 'eager to do, favorably disposed', and the adverb willingly appears soon after.","cn":"到十四世纪初，willing 已作形容词使用，意为「急于去做、有好感」，副词 willingly 也很快出现。"},{"era":"EARLY MODERN ENGLISH","en":"By the sixteenth century the word also stressed promptness and readiness in action, and fixed phrases such as God willing spread in everyday speech.","cn":"到十六世纪，这个词还强调行动上的爽快与随时待命，「但愿如此」之类的固定说法在日常口语中传播开来。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the adjective for everyday readiness, and the phrase willing suspension of disbelief became a standard term in literary criticism after Coleridge.","cn":"现代英语保留这个形容词表示日常的乐意；「自愿暂时相信」这一说法在柯勒律治之后成为文学批评的标准术语。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: deeper Indo-European connections are debated. A reconstructed root *wel- 'to wish' is often proposed, but it is a reconstruction, not a recorded word, and its exact reach is disputed; this entry treats the English family as Germanic and builds no Latin branch from it.","cn":"来源不确定：更深的印欧语联系有争议。常有人提出重构词根 *wel-「希望」，但它只是重构形式，不是有记录的词，覆盖范围也有争论；本词条把英语这一族按日耳曼语线处理，不据此建立拉丁语分支。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close and are often confused with willing; the second holds near neighbours that also describe a yes, but with a different strength or source.","cn":"第一组是与 willing 形近或音近、容易混淆的词；第二组是同为「答应」但力度或来源不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"will","ipa":"/wɪl/","tag":"same family","definition":"The verb and noun at the root of willing: to wish or desire, and the power of choice.","definitionCN":"willing 的词根动词与名词：希望、意愿，以及选择的能力。"},{"word":"wilful","ipa":"/ˈwɪlfəl/","tag":"same root, different sense","definition":"Built from will plus -ful, but it means stubborn or done on purpose, not ready to agree.","definitionCN":"由 will 加表示「充满……」的形容词后缀构成，但意思是固执或故意的，而不是乐意同意。"},{"word":"wiliness","ipa":"/ˈwaɪlinəs/","tag":"not related","definition":"Craftiness, from wile 'a trick'. It shares letters with willing but not a root.","definitionCN":"狡猾，来自 wile「诡计」。它与 willing 共享字母，却没有共同词根，二者并非同源。"},{"word":"unwilling","ipa":"/ʌnˈwɪlɪŋ/","tag":"same family, negated","definition":"The negative form of the same adjective; the prefix reverses the yes without changing the family.","definitionCN":"同一个形容词的否定形式；前缀把「好」反转，却没有换掉词族。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ready","ipa":"/ˈredi/","tag":"prepared","definition":"Prepared and able; it can describe tools as well as people, while willing describes people and their attitude.","definitionCN":"准备好的、能够的；既可形容人也可形容工具，而 willing 只描写人的态度。"},{"word":"eager","ipa":"/ˈiːɡə/","tag":"hotter","definition":"Full of keen desire and impatient to begin; stronger and less calm than willing.","definitionCN":"满怀热望、急着开始；比 willing 更强、更不平静。"},{"word":"compliant","ipa":"/kəmˈplaɪənt/","tag":"obeys rules","definition":"Obeying a rule or order; it stresses behaviour under authority, not inner readiness.","definitionCN":"服从规则或命令；强调在权威下的行为，而不是内心的乐意。"},{"word":"voluntary","ipa":"/vəˈlʌntəri/","tag":"free choice, formal","definition":"Done by free choice rather than force, often in legal or official contexts; it names the status of an act, not a feeling.","definitionCN":"出于自由选择而非强迫，常用于法律或正式语境；它说的是行为的性质，而非感受。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词语素、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"will (to wish) + -ing: willing is literally 'wishing, wanting', which is why it means ready rather than forced.","cn":"will（希望）加现在分词词尾：willing 字面上就是「正在希望、想要」，所以它表示乐意而非被逼。"},{"en":"The family runs will, willing, willingly, willingness, unwilling, unwillingness.","cn":"同族词包括 will、willing、willingly、willingness、unwilling、unwillingness。"},{"en":"Fixed phrases show the target of the readiness: be willing to do, willing consent, a willing ear, God willing.","cn":"固定搭配标出乐意指向哪里：愿意做、自愿同意、愿意倾听、但愿如此。"},{"en":"The negative is un- plus willing, not a separate root: unwilling simply closes the open door.","cn":"否定形式是否定前缀加 willing，不是另一个词根：unwilling 只是把那扇开着的门关上。"},{"en":"Willing suspension of disbelief is a fixed phrase from literary criticism, not a separate sense of the root.","cn":"「自愿暂时相信」是文学批评里的固定说法，并不是词根另长出的意思。"}],"abstract":[{"en":"Picture an open door with no lock on the inside.","cn":"想象一扇从里面没有锁的门。"},{"en":"Picture a hand already reaching for the tool before the name is called.","cn":"想象一只手在名字被叫到之前就已经伸向工具。"},{"en":"Picture a yes that costs a day off, which makes it worth more.","cn":"想象一个要牺牲一天休假的「好」，正因如此它更值钱。"}]},"examples":[{"en":"She was willing to move to another city for the job.","cn":"为了这份工作，她愿意搬到另一座城市。"},{"en":"A willing listener can do more good than quick advice.","cn":"一个愿意倾听的人，比急着给建议的人更有用。"},{"en":"They signed the agreement with willing consent.","cn":"他们自愿同意并签了这份协议。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「威尔灵」—— 威尔抬手说我来，做事带着一股愿意的灵气 → willing 愿意的；乐意的","word":"willing"},"root":"本土日耳曼语线：古英语 willan「希望、意愿」的现在分词 willende 演变为 willing；与名词 will 同源，英语这一族没有从拉丁语借入的同族词，更深的印欧词根属重构形式且有争议。","sensesIntro":{"en":"Eight senses fan out from one open door: a person who does not need to be pushed. The yes can be legal consent, energetic help, a costly gift, pliable obedience, a fixed phrase about providence, a reader's choice to believe, or an ear offered to a story.","cn":"八个义项从同一扇开着的门展开：一个不需要别人推的人。这个「好」可以是法律同意、热心帮忙、有代价的付出、顺从好使、关于天意的固定短语、读者选择相信，或一只递给故事的耳朵。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open door that no one has to push.","cn":"核心意象：一扇不需要别人推的门。"},"chain":["INNER WISH","OPEN DOOR","SAY YES","STEP FORWARD","ACCEPT COST","OFFER EAR"],"branches":[{"senses":"01","en":"THE CORE: readiness is an unlocked door, and the action can begin at once.","cn":"核心：乐意是一扇没上锁的门，行动可以立刻开始。"},{"senses":"02 · 04","en":"THE YES AND ITS PRICE: free consent and costly sacrifice are the same yes seen with and without a bill.","cn":"「好」与它的代价：自由同意和有代价的付出，是同一个「好」在有账单和没账单时的样子。"},{"senses":"03 · 08","en":"THE YES IN COMPANY: it steps forward as a helper, or concentrates into an ear offered to someone.","cn":"人群中的「好」：它作为帮手向前迈步，或收拢成一只递向别人的耳朵。"},{"senses":"05","en":"THE YES WITHOUT A SPINE: readiness that never resists can become mere pliability.","cn":"没有脊梁的「好」：从不抵抗的乐意，可能变成单纯的易摆布。"},{"senses":"06 · 07","en":"THE YES IN FORMULAS: providence and fiction both use the word inside fixed phrases.","cn":"固定说法里的「好」：天意与虚构都把这个词收进了固定短语。"}]},"affixes":{"intro":{"en":"Willing is a Germanic verb stem plus a participle ending, and the family grows by adding common prefixes and suffixes.","cn":"willing 是日耳曼语动词词干加分词词尾，整个词族靠常见前缀和后缀继续生长。"},"latinIntro":{"en":"The stem is the native Germanic will; English has no Latin-borrowed relative of this family, so the Latin section is intentionally empty.","cn":"词干是本土日耳曼语的 will；英语中没有从拉丁语借入的这一词族成员，因此拉丁同族词部分有意留空。"},"items":[{"word":"will","structure":"Old English willan 'to wish, desire' (verb and noun root)","meaning":"to wish; the power of choosing","meaningCN":"希望；选择的能力","example":"Will is the root behind the whole family.","exampleCN":"will 是整个词族背后的词根。"},{"word":"-ing","structure":"-ing (present-participle and adjective ending)","meaning":"the ending that makes 'the one who wills'","meaningCN":"把动词变成「正在愿意的人」的词尾","example":"The ending turns the verb into a description.","exampleCN":"这个词尾把动词变成一种描写。"},{"word":"willing","structure":"will + -ing","meaning":"ready and glad to act","meaningCN":"愿意并且乐意行动的","example":"She gave a willing answer.","exampleCN":"她乐意地作了回答。"},{"word":"willingly","structure":"willing + -ly (adverb)","meaning":"in a ready way","meaningCN":"乐意地","example":"He agreed willingly.","exampleCN":"他乐意地同意了。"},{"word":"willingness","structure":"willing + -ness (noun of state)","meaning":"the state of being ready","meaningCN":"乐意、愿意的状态","example":"Her willingness was obvious.","exampleCN":"她的乐意显而易见。"},{"word":"unwilling","structure":"un- (not) + willing","meaning":"not ready to act","meaningCN":"不愿意的","example":"The witness was unwilling to speak.","exampleCN":"那名证人不愿意开口。"},{"word":"unwillingness","structure":"un- + willing + -ness","meaning":"the state of refusing","meaningCN":"不情愿的状态","example":"His unwillingness ended the discussion.","exampleCN":"他的不情愿让讨论停了下来。"},{"word":"goodwill","structure":"good + will (compound)","meaning":"friendly readiness to help","meaningCN":"善意；乐于相助的友好","example":"The visit was a gesture of goodwill.","exampleCN":"这次访问是善意的表示。"},{"word":"free will","structure":"free + will (compound)","meaning":"choice without force","meaningCN":"不受强迫的自由选择","example":"The debate concerns free will.","exampleCN":"这场争论关乎自由意志。"}],"latinEntries":[],"derivatives":[{"word":"willingly","pos":"adv.","zh":"乐意地（willing 加副词后缀，把乐意转成动作方式）"},{"word":"willingness","pos":"n.","zh":"乐意；意愿（willing 加名词后缀，从态度转为抽象状态）"},{"word":"unwilling","pos":"adj.","zh":"不愿意的（否定前缀加 willing，把乐意反转）"},{"word":"unwillingness","pos":"n.","zh":"不情愿（否定前缀加 willing 再加名词后缀，指拒绝的状态）"}]}},{"word":"reluctant","ipa_uk":"/rɪˈlʌktənt/","ipa_us":"/rɪˈlʌktənt/","definition_zh":"不情愿的；勉强的；迟疑的；不甘心的","definition_en":"not wanting to do something and showing hesitation before doing it","core_image":"一个人被拉到门口，脚在地上蹭了半步，才慢慢跨出去","scene":"整理旧物时，母亲让他把大学时的信件丢掉，他捏着纸角看了很久，最后只抽出一封放回抽屉。He was reluctant to throw away letters that had survived three moves.","sceneCN":"这里 reluctant 指「舍不得、不愿放手」（第 4 个义项：不愿舍弃某物）；句意为他不愿丢掉那些跟着搬了三次家的信。","pos":[{"tag":"adj.","zh":"不情愿的；勉强的；迟疑的；不甘心的"}],"collocations":[{"phrase":"be reluctant to do","zh":"不愿做某事"},{"phrase":"a reluctant smile","zh":"勉强的一笑"},{"phrase":"reluctant agreement","zh":"勉强的同意"},{"phrase":"reluctant hero","zh":"不情愿的英雄"},{"phrase":"reluctant witness","zh":"不情愿的证人"},{"phrase":"reluctant acceptance","zh":"勉强接受"}],"forms":[{"label":"比较级","form":"more reluctant"},{"label":"最高级","form":"most reluctant"},{"label":"副词","form":"reluctantly"},{"label":"名词（不情愿）","form":"reluctance"},{"label":"名词（罕用变体）","form":"reluctancy"}],"derivatives":[{"word":"reluctantly","pos":"adv.","zh":"不情愿地（由 reluctant 加副词后缀，把迟疑转成动作方式）"},{"word":"reluctance","pos":"n.","zh":"不情愿；勉强（由 reluctant 加名词后缀，从人的态度转为抽象状态）"},{"word":"reluctancy","pos":"n.","zh":"不情愿（由 reluctant 加罕用名词后缀，与常见名词后缀同源的旧式变体）"},{"word":"reluctivity","pos":"n.","zh":"磁阻率（由 reluctance「磁阻」加表性质的名词后缀，转入物理学量）"}],"senses":[{"no":"01","title":"Not wanting to do something","titleCN":"不愿做某事","definition":"feeling unwilling to do something and needing to be urged","definitionCN":"不愿做某事，需要别人催促","example":"She was reluctant to speak first at the meeting.","exampleCN":"她不愿在会上第一个发言。","why":"The Latin verb means 'to wrestle back against'; reluctance is the inner arm pulling in the opposite direction.","whyCN":"拉丁动词的意思是「反着摔跤」；reluctant 就是内心那只朝反方向拉的手臂。"},{"no":"02","title":"Hesitant in manner","titleCN":"举止上的迟疑","definition":"showing hesitation in a smile, step or gesture","definitionCN":"在笑容、脚步或动作上露出迟疑","example":"He gave a reluctant smile and stayed by the door.","exampleCN":"他勉强笑了笑，仍站在门边。","why":"The body often says no before the mouth does; a delayed smile is the struggle made visible.","whyCN":"身体常常比嘴更早说「不」；一个迟到的笑容，就是那场挣扎露了出来。"},{"no":"03","title":"Slow to admit or agree","titleCN":"迟迟不肯承认或同意","definition":"finding it hard to accept a fact or approve a plan","definitionCN":"难以接受某个事实或赞同一个计划","example":"Managers were reluctant to admit that the launch had failed.","exampleCN":"管理者们不愿承认这次发布已经失败。","why":"To admit is to give up a defended position, so the same backward pull appears in argument rather than in movement.","whyCN":"承认就是放弃一个守住的位置，所以同一股向后的拉力从行动跑到了争论里。"},{"no":"04","title":"Unwilling to part with something","titleCN":"舍不得放手","definition":"unwilling to give away, spend or lose something one values","definitionCN":"不愿送出、花掉或失去自己看重的某物","example":"He was reluctant to throw away letters that had survived three moves.","exampleCN":"他不愿丢掉那些跟着搬了三次家的信。","why":"The struggle now happens at the hand: the object is already held, and letting go feels like a small defeat.","whyCN":"挣扎现在发生在手上：东西已经被握住了，松手就像一场小小的失败。"},{"no":"05","title":"Reluctant hero","titleCN":"不情愿的英雄","definition":"in stories, a person pushed into greatness who never sought it","definitionCN":"故事里被推上重要位置、自己从不追求名声的人","example":"The novel turns a reluctant hero into the town's only hope.","exampleCN":"这部小说把一个不情愿的英雄变成了小镇唯一的希望。","why":"When duty pulls harder than desire, the result is a heroic act performed against one's own inclination.","whyCN":"当责任比愿望拉得更用力，结果就是一个违背自己心意的英雄行为。"},{"no":"06","title":"Reluctant witness","titleCN":"不情愿的证人","definition":"a person who must testify but would rather not be involved","definitionCN":"必须作证却宁可不要卷入的人","example":"The court had to compel a reluctant witness to appear.","exampleCN":"法庭不得不强制一名不情愿的证人出庭。","why":"Institutions can require the act, but they cannot manufacture the willingness; the word marks that gap.","whyCN":"机构可以要求人行动，却造不出乐意；这个词标记的正是这道缝隙。"},{"no":"07","title":"Reluctant acceptance","titleCN":"勉强的接受","definition":"approval given without enthusiasm because no better option exists","definitionCN":"因为没有更好的选择而缺乏热情地认可","example":"The plan won reluctant acceptance from both sides.","exampleCN":"这项计划勉强得到了双方的接受。","why":"Acceptance can be a closed fist opening just enough to let the object through.","whyCN":"接受可以是一只握紧的拳头只松开一点点，刚好让东西过去。"},{"no":"08","title":"Reluctant compliance","titleCN":"不情愿的服从","definition":"obeying an order while still disagreeing with it","definitionCN":"一边服从命令，一边仍然不认同","example":"Staff gave reluctant compliance with the new schedule.","exampleCN":"员工们不情愿地服从了新排班。","why":"Compliance is the outside of obedience; reluctance is the inside that has not been converted.","whyCN":"服从只能保证外在动作发生，不情愿则说明内里还没有被说服。"}],"etymology":{"intro":{"en":"Reluctant entered English in the seventeenth century from the Latin present participle reluctantem, from reluctari 'to struggle against'. The word carries a wrestling match inside it.","cn":"reluctant 在十七世纪从拉丁语现在分词 reluctantem 进入英语，来自 reluctari「抗争」。这个词里面装着一场摔跤。"},"items":[{"era":"LATIN LUCTARI","en":"Luctari meant 'to struggle, wrestle', and the related noun lucta meant 'a wrestling match'. The body image is two forces locked together.","cn":"luctari 意为「搏斗、摔跤」，相关名词 lucta 指「一场摔跤」。身体画面是两股力量锁在一起。"},{"era":"LATIN RELUCTARI","en":"Reluctari added re- 'against, back' to luctari: to wrestle back, to resist, to make opposition.","cn":"reluctari 在 luctari 前加上表示「反对、向后」的前缀：反着摔、抵抗、作出反对。"},{"era":"FRENCH RELUCTANT","en":"A French form is sometimes cited as the route into English, but the usual account takes the word straight from Latin reluctantem; both routes point to the same Latin source.","cn":"有时有人说法语形式是进入英语的中转，但更常见的说法是直接从拉丁语 reluctantem 借入；两条路线都指向同一个拉丁来源。"},{"era":"EARLY MODERN ENGLISH","en":"English records reluctant in the 1660s with the sense 'unwilling, struggling against duty or a command'. The spelling and ending came from the Latin participle.","cn":"英语在十七世纪六十年代记录到 reluctant，意为「不愿意、抗拒责任或命令」。拼写与词尾来自拉丁语分词。"},{"era":"MODERN ENGLISH","en":"Modern English widened the word from open resistance to everyday hesitation: reluctant to spend, reluctant to admit, reluctant to leave.","cn":"现代英语把这个词从公开抵抗扩展到日常迟疑：不愿花钱、不愿承认、不愿离开。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of luctari is not settled. A reconstructed form *lug-to- 'bent' is often proposed, and other accounts emphasise the wrestling image itself; neither can be demonstrated as the single source.","cn":"来源不确定：luctari 更深来源尚无定论。常有人提出重构形式 *lug-to-「弯曲的」，另一些解释则强调摔跤意象本身；两者都无法被证明是唯一来源。"}]},"similar":{"note":{"en":"The first group holds forms from the same Latin wrestling family; the second holds near neighbours that also say no, but with a different kind of resistance.","cn":"第一组是同一个拉丁「摔跤」词族的形式；第二组是同为拒绝、但抵抗方式不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reluctance","ipa":"/rɪˈlʌktəns/","tag":"same family","definition":"The noun made from reluctant; it names the state that the adjective describes.","definitionCN":"由 reluctant 构成的名词，指形容词所描述的那种状态。"},{"word":"reluctantly","ipa":"/rɪˈlʌktəntli/","tag":"same family","definition":"The adverb made from reluctant; it describes how an unwilling action is performed.","definitionCN":"由 reluctant 构成的副词，描写不情愿的动作是怎么做出来的。"},{"word":"reluct","ipa":"/rɪˈlʌkt/","tag":"same Latin root, obsolete","definition":"A fifteenth-century verb meaning 'to strive or rebel against'; it is the older English cousin of reluctant and now archaic.","definitionCN":"十五世纪的动词，意为「抗争、反叛」；它是 reluctant 更古老的英语亲族，现已废弃。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unwilling","ipa":"/ʌnˈwɪlɪŋ/","tag":"flat refusal","definition":"Simply not wanting to do something; it lacks the inner wrestling match that reluctant suggests.","definitionCN":"只是不想做；它没有 reluctant 暗含的那场内心摔跤。"},{"word":"hesitant","ipa":"/ˈhezɪtənt/","tag":"pause from doubt","definition":"Pausing because one is unsure; the cause is uncertainty rather than opposition.","definitionCN":"因为拿不准而停顿；原因是没把握，而不是反对。"},{"word":"disinclined","ipa":"/ˌdɪsɪŋˈklaɪnd/","tag":"mild and formal","definition":"Having a mild lack of preference for something; more formal and cooler than reluctant.","definitionCN":"对某事没有多少意愿；比 reluctant 更正式、更冷静。"},{"word":"loath","ipa":"/ləʊθ/","tag":"stronger aversion","definition":"Strongly unwilling or averse; the feeling is sharper than reluctant and often more absolute.","definitionCN":"强烈不愿或厌恶；感觉比 reluctant 更尖锐，也常常更绝对。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词语素、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- (against) + luctari (to wrestle): reluctant is literally 'wrestling back'.","cn":"表示「反对」的前缀加 luctari（摔跤）：reluctant 字面上就是「反着摔」。"},{"en":"Latin lucta 'a wrestling match' supplies the body picture: two forces locked and pulling opposite ways.","cn":"拉丁 lucta「一场摔跤」提供了身体画面：两股力量锁住，朝相反方向拉。"},{"en":"The family runs reluctant, reluctance, reluctantly, reluctancy, reluctivity.","cn":"同族词包括 reluctant、reluctance、reluctantly、reluctancy、reluctivity。"},{"en":"Fixed phrases show where the pull happens: reluctant to do, a reluctant smile, reluctant hero, reluctant witness.","cn":"固定搭配标出拉力发生在哪里：不愿做、勉强一笑、不情愿的英雄、不情愿的证人。"},{"en":"The word came in as a learned Latin borrowing in the seventeenth century, which is why it still sounds formal.","cn":"这个词是十七世纪作为书面拉丁借词进来的，所以至今仍显得正式。"}],"abstract":[{"en":"Picture feet dragging at a doorway while the hand is already on the handle.","cn":"想象手已经搭在门把上，脚却还在门口磨蹭。"},{"en":"Picture a smile that arrives half a second too late.","cn":"想象一个迟了半秒才到的笑容。"},{"en":"Picture two wrestlers locked still, neither able to move the other.","cn":"想象两个摔跤手锁在一起不动，谁也推不动谁。"}]},"examples":[{"en":"He was reluctant to leave the team he had built.","cn":"他不愿离开自己一手组建的团队。"},{"en":"The committee gave reluctant approval to the smaller budget.","cn":"委员会勉强批准了这份缩水的预算。"},{"en":"She answered the question with a reluctant nod.","cn":"她勉强点了点头，算作回答。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞拉克坦特」—— 瑞拉被拉去摔跤，脚一直往后蹬，满脸不情愿 → reluctant 不情愿的；勉强的","word":"reluctant"},"root":"拉丁 reluctari「抗争」，由表示「反对」的前缀加 luctari「搏斗」构成，lucta 指「摔跤」；十七世纪进入英语。luctari 更深来源不确定，重构形式与摔跤意象两种解释并存。","sensesIntro":{"en":"Eight senses grow from one wrestling image: a force pulling backward. The pull can show in the body, in an admission, in a hand that will not let go, in a public role, in a courtroom, in a treaty, or in a workplace.","cn":"八个义项都从同一个摔跤意象长出来：一股向后拉的力量。这股拉力可以显在身体上、显在承认里、显在不肯松开的手上，也可以落在公众角色、法庭、条约或工作场所。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wrestler pulling backward while being pushed forward.","cn":"核心意象：一个被往前推、却向后拉的摔跤手。"},"chain":["AGAINST","WRESTLE","PULL BACK","HESITATE","COMPLY UNEASILY","RESENT THE COST"],"branches":[{"senses":"01","en":"THE CORE: the will pulls backward against the request, so action needs an extra push.","cn":"核心：意愿朝请求的反方向拉，所以行动需要额外一推。"},{"senses":"02 · 03","en":"TWO PLACES THE PULL SHOWS: a delayed smile in the body, a delayed admission in argument.","cn":"拉力露出的两个地方：身体上迟到的笑，争论里迟到的承认。"},{"senses":"04","en":"THE HAND THAT WILL NOT OPEN: the struggle moves from duty to a valued object already held.","cn":"不肯张开的手：挣扎从责任挪到一件已经被握住、且被看重的物件上。"},{"senses":"05 · 06","en":"PUSHED INTO PUBLIC: a hero who never sought greatness and a witness who never sought the courtroom.","cn":"被推进公众：一个从不追求伟大的英雄，一个从不想进法庭的证人。"},{"senses":"07 · 08","en":"THE UNCONVERTED INSIDE: acceptance and compliance can both happen while the inner no remains.","cn":"未被转化的内里：接受与服从都可以发生，而内心的「不」仍然留着。"}]},"affixes":{"intro":{"en":"Reluctant can be read as three pieces: a prefix of opposition, a root for wrestling, and an adjective ending. The same pieces recur across the family.","cn":"reluctant 可以拆成三块：表示反对的前缀、表示摔跤的词根、形容词词尾。同样的部件在整个词族里反复出现。"},"latinIntro":{"en":"The Latin family is small and vivid: a verb for wrestling, a verb for wrestling back, and a noun for the match itself.","cn":"这一族的拉丁词不多，但画面很鲜明：一个表示摔跤的动词，一个表示反着摔的动词，还有一个表示摔跤本身的名称。"},"items":[{"word":"re-","structure":"re- (Latin prefix: back, against)","meaning":"back; against; in opposition","meaningCN":"向后；反对；对抗","example":"The prefix turns the wrestling around.","exampleCN":"这个前缀把摔跤的方向转了过来。"},{"word":"luct-","structure":"luctari (Latin verb: to wrestle, struggle)","meaning":"to wrestle; to struggle","meaningCN":"搏斗；摔跤","example":"The root supplies the physical struggle.","exampleCN":"这个词根提供身体上的搏斗。"},{"word":"-ant","structure":"-ant (Latin present-participle ending used as adjective)","meaning":"the one doing the action","meaningCN":"正在做这个动作的（人）","example":"The ending marks the person who is wrestling back.","exampleCN":"这个词尾标出那个正在反着摔的人。"},{"word":"reluctant","structure":"re- + luct- + -ant","meaning":"wrestling back; unwilling","meaningCN":"反着摔的；不情愿的","example":"The witness was reluctant.","exampleCN":"那名证人很不情愿。"},{"word":"reluctantly","structure":"reluctant + -ly (adverb)","meaning":"in an unwilling way","meaningCN":"不情愿地","example":"She agreed reluctantly.","exampleCN":"她不情愿地同意了。"},{"word":"reluctance","structure":"reluctant + -ance (noun of state)","meaning":"the state of pulling back","meaningCN":"向后拉的状态；不情愿","example":"His reluctance was easy to read.","exampleCN":"他的不情愿很容易看出来。"},{"word":"reluctivity","structure":"reluctance + -ivity (noun of a physical property)","meaning":"the magnetic property related to reluctance","meaningCN":"磁阻率（与磁阻相关的物理性质）","example":"The material's reluctivity was measured in the lab.","exampleCN":"这种材料的磁阻率在实验室里被测量过。"},{"word":"reluct","structure":"reluct (obsolete English verb from Latin reluctari)","meaning":"to strive or rebel against","meaningCN":"抗争；反叛（已废弃的英语动词）","example":"The old verb survives only in dictionaries.","exampleCN":"这个古动词如今只活在词典里。"}],"latinEntries":[{"word":"luctari","structure":"luctari, luctatus sum (deponent verb, first conjugation)","meaning":"to wrestle, struggle","meaningCN":"摔跤；搏斗"},{"word":"lucta","structure":"lucta, luctae (f., first declension)","meaning":"a wrestling match; struggle","meaningCN":"一场摔跤；搏斗"},{"word":"reluctari","structure":"re- (against) + luctari (to wrestle)","meaning":"to struggle against, resist","meaningCN":"抗争；抵抗"}],"derivatives":[{"word":"reluctantly","pos":"adv.","zh":"不情愿地（reluctant 加副词后缀，把迟疑转成动作方式）"},{"word":"reluctance","pos":"n.","zh":"不情愿；勉强（reluctant 加名词后缀，从态度转为抽象状态）"},{"word":"reluctancy","pos":"n.","zh":"不情愿（reluctant 加旧式名词后缀，与常见名词后缀同源的罕用变体）"},{"word":"reluctivity","pos":"n.","zh":"磁阻率（reluctance「磁阻」加表性质的名词后缀，转入物理学量）"}]}},{"word":"reluctance","ipa_uk":"/rɪˈlʌktəns/","ipa_us":"/rɪˈlʌktəns/","definition_zh":"不情愿；勉强；迟疑；磁阻","definition_en":"unwillingness to do something, shown as hesitation or resistance","core_image":"一扇门被推开一条缝，又被里面的人轻轻推回去半寸","scene":"谈判桌两边都摊开了文件，问到她是否接受这个日期时，她先看了一眼同事，又把笔放回桌上。Her reluctance to commit to a date slowed the whole meeting.","sceneCN":"这里 reluctance 指「不愿作出承诺的迟疑」（第 8 个义项：外交场合不愿表态或让步）；句意为她不愿敲定日期，拖慢了整场会议。","pos":[{"tag":"n.","zh":"不情愿；勉强；迟疑；磁阻（不可数）"}],"collocations":[{"phrase":"with reluctance","zh":"勉强地；不情愿地"},{"phrase":"reluctance to do","zh":"不愿做某事"},{"phrase":"show reluctance","zh":"表现出不情愿"},{"phrase":"magnetic reluctance","zh":"磁阻"},{"phrase":"reluctance motor","zh":"磁阻电机"},{"phrase":"overcome reluctance","zh":"克服不情愿"}],"forms":[{"label":"不可数名词（通常无复数）","form":"reluctance"},{"label":"形容词","form":"reluctant"},{"label":"副词","form":"reluctantly"},{"label":"物理学派生名词","form":"reluctivity"}],"derivatives":[{"word":"reluctantly","pos":"adv.","zh":"不情愿地（由 reluctant 加副词后缀，把迟疑转成动作方式）"},{"word":"reluctancy","pos":"n.","zh":"不情愿（由 reluctant 加旧式名词后缀，与常见名词后缀同源的罕用变体）"},{"word":"reluctivity","pos":"n.","zh":"磁阻率（由 reluctance「磁阻」加表性质的名词后缀，转入物理学量）"},{"word":"reluctance motor","pos":"n.","zh":"磁阻电机（由「磁阻」与「电动机」复合而成，指利用磁阻变化产生转矩的电机）"}],"senses":[{"no":"01","title":"Unwillingness to act","titleCN":"不愿行动","definition":"the state of not wanting to do something and hesitating before it","definitionCN":"不想做某事、行动前犹豫的状态","example":"Her reluctance was clear from the way she kept checking the time.","exampleCN":"她不停看时间的样子，清楚显出了不情愿。","why":"The Latin verb is a wrestling back; the noun names that backward pull before any action begins.","whyCN":"拉丁动词是「反着摔」；这个名词指的就是行动开始之前的那股向后拉力。"},{"no":"02","title":"With reluctance","titleCN":"勉强地","definition":"used in the phrase with reluctance to show that an act is done grudgingly","definitionCN":"用于表示「勉强地」的固定说法，说明动作是勉强做出来的","example":"He signed the form with reluctance and said nothing.","exampleCN":"他勉强签了表，一句话也没说。","why":"The phrase puts the inner no beside the outer act, so the reader sees both at once.","whyCN":"这个短语把内心的「不」放在外在动作旁边，让读者同时看见两者。"},{"no":"03","title":"Reluctance to admit or reveal","titleCN":"不愿承认或透露","definition":"hesitation to state a fact, especially one that costs face or safety","definitionCN":"不愿说出某个事实，尤其当它会伤面子或带来风险时","example":"The witness's reluctance to name names frustrated the inquiry.","exampleCN":"证人不愿说出名字，让调查很受挫。","why":"Speech is a form of handing something over; refusing to speak keeps the fact inside the hand.","whyCN":"说话是把东西交出去的一种方式；拒绝开口，就是把事实继续握在手里。"},{"no":"04","title":"Reluctance to spend or part with","titleCN":"不愿花钱或放手","definition":"unwillingness to give up money, possessions or resources","definitionCN":"不愿交出金钱、财物或资源","example":"The company showed a familiar reluctance to invest in training.","exampleCN":"公司在培训投入上表现出一种熟悉的不情愿。","why":"The wrestling match moves to the wallet: the hand holds the coin, and release feels like loss.","whyCN":"摔跤挪到了钱包上：手握着硬币，松开就像损失。"},{"no":"05","title":"Magnetic reluctance","titleCN":"磁阻","definition":"in physics, the resistance of a magnetic circuit to magnetic flux","definitionCN":"物理学中，磁路对磁通量的阻力","example":"Iron has much lower magnetic reluctance than air.","exampleCN":"铁的磁阻比空气低得多。","why":"Physics borrows the everyday image of resistance and gives it a precise measurable form.","whyCN":"物理学借走了日常的「阻力」意象，把它变成一个可精确测量的量。"},{"no":"06","title":"Reluctance motor","titleCN":"磁阻电机","definition":"in electrical engineering, a motor that produces torque by exploiting changing magnetic reluctance","definitionCN":"电气工程中，利用磁阻变化产生转矩的电动机","example":"The workshop replaced its old drive with a reluctance motor.","exampleCN":"车间用一台磁阻电机替换了旧驱动装置。","why":"A technical term turns the physics quantity into a machine: the resistance itself is made to do work.","whyCN":"一个技术术语把物理量变成了机器：阻力本身被用来做功。"},{"no":"07","title":"Resistance to change","titleCN":"对变革的抵触","definition":"in organizations, the unwillingness of a group to accept a new practice","definitionCN":"组织里，群体不愿接受新做法的状态","example":"Management underestimated the staff's reluctance to change.","exampleCN":"管理层低估了员工对变革的抵触。","why":"A group can hold a habit the way a hand holds an object; change asks the group to let go.","whyCN":"一个群体可以像手握物件那样握着习惯；变革就是要求群体松手。"},{"no":"08","title":"Diplomatic reluctance","titleCN":"外交上的不愿表态","definition":"in diplomacy, unwillingness to commit, promise or give ground","definitionCN":"外交场合中，不愿承诺、表态或让步","example":"Her reluctance to commit to a date slowed the whole meeting.","exampleCN":"她不愿敲定日期，拖慢了整场会议。","why":"A state, like a person, can keep its hand closed until the terms improve; reluctance is that pause in public.","whyCN":"一个国家也像一个人，可以在条件变好之前一直握着手不松开；不情愿就是公开场合里的那阵停顿。"}],"etymology":{"intro":{"en":"Reluctance appeared in English in the 1640s, first as 'the act of struggling against', later as 'unwillingness'. It grew from the Latin wrestling verb reluctari, either through the old English verb reluct or directly from the Latin noun endings.","cn":"reluctance 在十七世纪四十年代出现在英语里，最初指「抗争的动作」，后来指「不情愿」。它从拉丁语摔跤动词 reluctari 生长出来，可能经由古老的英语动词 reluct，也可能直接借拉丁名词词尾。"},"items":[{"era":"LATIN RELUCTARI","en":"Reluctari meant 'to struggle against, resist, make opposition', built from re- 'against' and luctari 'to wrestle'.","cn":"reluctari 意为「抗争、抵抗、作出反对」，由表示「反对」的前缀与 luctari「摔跤」构成。"},{"era":"LATIN -ANTIA","en":"The Latin ending -antia formed abstract nouns of state, and its French descendant -ance is the ending English borrowed for nouns such as reluctance.","cn":"那个拉丁词尾构成表示状态的抽象名词，它的法语后裔就是英语借来构成 reluctance 这类名词的词尾。"},{"era":"ENGLISH RELUCT","en":"A fifteenth-century English verb reluct 'to strive or rebel against' is recorded, and the noun reluctance is usually explained as its abstract form with -ance.","cn":"英语里记录过一个十五世纪动词 reluct「抗争、反叛」，名词 reluctance 通常被解释为它加名词词尾构成的抽象形式。"},{"era":"SEVENTEENTH-CENTURY ENGLISH","en":"By the 1640s reluctance named the act of struggling; by the 1660s it had shifted to the inner unwillingness that we usually mean today.","cn":"到十七世纪四十年代，reluctance 指抗争的动作；到六十年代，它转向我们今天通常指的内心的不情愿。"},{"era":"MODERN ENGLISH","en":"Modern technical English added magnetic reluctance and the reluctance motor, turning the old idea of resistance into a measurable physical quantity and a machine.","cn":"现代技术英语又加上磁阻与磁阻电机，把古老的「阻力」观念变成可测量的物理量和一台机器。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: whether a Latin noun reluctantia was ever in common use is uncertain; the safe account is the English formation with -ance. The deeper origin of luctari is also unsettled, with reconstructed forms and the wrestling image competing.","cn":"来源不确定：拉丁名词 reluctantia 是否曾通行，无法确定；稳妥的说法是英语用名词词尾构成。luctari 更深来源同样没有定论，重构形式与摔跤意象两种解释并存。"}]},"similar":{"note":{"en":"The first group holds forms from the same Latin wrestling family; the second holds near neighbours that also describe a no, but with a different source or strength.","cn":"第一组是同一个拉丁「摔跤」词族的形式；第二组是同为拒绝、但来源或力度不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reluctant","ipa":"/rɪˈlʌktənt/","tag":"same family","definition":"The adjective that describes the person; reluctance names the state behind it.","definitionCN":"描写人的形容词；reluctance 指它背后的状态。"},{"word":"reluctantly","ipa":"/rɪˈlʌktəntli/","tag":"same family","definition":"The adverb that describes how the unwilling action is carried out.","definitionCN":"描写不情愿的动作如何执行的副词。"},{"word":"reluct","ipa":"/rɪˈlʌkt/","tag":"same Latin root, obsolete","definition":"The old English verb 'to strive against', now archaic; it is the cousin from which the noun is often derived.","definitionCN":"古英语动词「抗争」，现已废弃；名词常被认为由它派生而来。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unwillingness","ipa":"/ʌnˈwɪlɪŋnəs/","tag":"plain refusal","definition":"A flat lack of willingness, without the wrestling image of a force pulling back.","definitionCN":"平直地缺乏意愿，没有那股向后拉的摔跤意象。"},{"word":"hesitation","ipa":"/ˌhezɪˈteɪʃən/","tag":"pause from doubt","definition":"A pause caused by uncertainty; reluctance is a pause caused by opposition.","definitionCN":"因没把握而停顿；reluctance 是因反对而停顿。"},{"word":"resistance","ipa":"/rɪˈzɪstəns/","tag":"active opposition","definition":"Active pushing back, often organized and public; it is stronger and more external than reluctance.","definitionCN":"主动顶回去，常是有组织、公开的；比 reluctance 更强、更外在。"},{"word":"aversion","ipa":"/əˈvɜːʃən/","tag":"strong dislike","definition":"A strong dislike that makes one turn away; the feeling is sharper than mere reluctance.","definitionCN":"强烈的厌恶，使人转身避开；比单纯的不情愿更尖锐。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词语素、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- (against) + luctari (to wrestle) + -ance (state): the noun is 'the state of wrestling back'.","cn":"表示「反对」的前缀加 luctari（摔跤）再加表示状态的名词词尾：这个名词就是「反着摔的状态」。"},{"en":"Latin lucta 'a wrestling match' keeps the body picture: two forces locked, neither giving way.","cn":"拉丁 lucta「一场摔跤」保留了身体画面：两股力量锁住，谁也不让。"},{"en":"The family runs reluctant, reluctance, reluctantly, reluctancy, reluctivity.","cn":"同族词包括 reluctant、reluctance、reluctantly、reluctancy、reluctivity。"},{"en":"Fixed phrases show the pull: with reluctance, reluctance to do, show reluctance, overcome reluctance.","cn":"固定搭配标出那股拉力：勉强地、不愿做、表现出不情愿、克服不情愿。"},{"en":"Physics reuses the word as magnetic reluctance, the resistance of a magnetic circuit.","cn":"物理学把这个词再用一次，造出「磁阻」这一术语，指磁路对磁通的阻力。"}],"abstract":[{"en":"Picture a door pushed open a crack and then eased back half an inch from inside.","cn":"想象一扇门被推开一条缝，又被里面的人轻轻推回半寸。"},{"en":"Picture a hand that will not open while the coin is still inside it.","cn":"想象一只不肯张开的手，硬币还在里面。"},{"en":"Picture a signature that takes three tries before the pen touches paper.","cn":"想象一个签名，笔尖碰纸之前试了三次。"}]},"examples":[{"en":"She agreed to the plan with obvious reluctance.","cn":"她显然很勉强地同意了这个计划。"},{"en":"The reluctance of investors to commit capital delayed the project.","cn":"投资者不愿投入资金，拖慢了项目。"},{"en":"Engineers measured the magnetic reluctance of the new core.","cn":"工程师测量了新磁芯的磁阻。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞拉克坦斯」—— 被拉去摔跤的人一步三回头，浑身写着不情愿 → reluctance 不情愿；勉强","word":"reluctance"},"root":"拉丁 reluctari「抗争」的名词化：表示「反对」的前缀加 luctari「搏斗」，lucta 指「摔跤」；英语中或经由古动词 reluct 加名词后缀，或直接借拉丁词尾构成。拉丁名词 reluctantia 是否通行不确定，luctari 更深来源亦无定论。","sensesIntro":{"en":"Eight senses follow the same backward pull: first the inner no, then the grudging act, then the refusal to reveal, spend, or move. The same image later becomes magnetic resistance, a motor, an organization's inertia, and a state's silence at the table.","cn":"八个义项沿着同一股向后的拉力展开：先是内心的「不」，再是勉强的动作，然后是不肯透露、不肯花钱、不肯挪动。同一个意象后来变成磁阻、一台电机、一个组织的惰性，以及一个国家在谈判桌前的沉默。"},"semanticMap":{"core":{"en":"CORE IMAGE: a force that keeps pulling the hand back.","cn":"核心意象：一股始终把手往回拉的力量。"},"chain":["AGAINST","WRESTLE","PULL BACK","WITHHOLD","MAGNETIC RESISTANCE","INSTITUTIONAL RESISTANCE"],"branches":[{"senses":"01","en":"THE CORE: the inner no appears before any action, as a general state of hesitation.","cn":"核心：内心的「不」先于任何行动出现，表现为整体的迟疑状态。"},{"senses":"02","en":"THE NO BESIDE THE ACT: with reluctance lets the reader see the unwilling act and the unwilling feeling together.","cn":"「不」与动作并置：表示「勉强地」的固定说法让读者同时看见勉强的动作和不情愿的感受。"},{"senses":"03 · 04","en":"TWO THINGS KEPT: facts stay unspoken and money stays unspent; both are forms of withholding.","cn":"两样被握住的东西：事实不说出口，钱不花出去；两者都是「扣住不放」。"},{"senses":"05 · 06","en":"THE IMAGE MADE TECHNICAL: magnetic reluctance measures resistance in a circuit, and the reluctance motor makes it do work.","cn":"意象技术化：磁阻测量磁路中的阻力，磁阻电机则让这份阻力做功。"},{"senses":"07 · 08","en":"THE NO WRIT LARGE: a group resists a new practice, and a state refuses to commit at the table.","cn":"放大后的「不」：一个群体抵触新做法，一个国家在谈判桌前拒绝承诺。"}]},"affixes":{"intro":{"en":"Reluctance is a Latin-derived noun built from a prefix of opposition, a wrestling root and a noun ending of state; the family stays readable piece by piece.","cn":"reluctance 是拉丁来源的名词，由表示反对的前缀、表示摔跤的词根和表示状态的名词词尾构成；整个词族仍可逐块读出。"},"latinIntro":{"en":"The Latin side is small: a verb for wrestling, a verb for wrestling back, and a noun for the match. The abstract noun ending came through French into English.","cn":"拉丁这一侧不大：一个摔跤动词、一个反着摔的动词、一个表示摔跤本身的名称。抽象名词词尾则经法语进入英语。"},"items":[{"word":"re-","structure":"re- (Latin prefix: back, against)","meaning":"back; against","meaningCN":"向后；反对","example":"The prefix reverses the direction of the struggle.","exampleCN":"这个前缀把搏斗的方向反过来。"},{"word":"luct-","structure":"luctari (Latin verb: to wrestle)","meaning":"to wrestle; to struggle","meaningCN":"摔跤；搏斗","example":"The root keeps the body in the word.","exampleCN":"这个词根把身体留在了词里。"},{"word":"-ance","structure":"-ance (from Latin -antia, noun of state)","meaning":"the ending that names a state or quality","meaningCN":"指状态或性质的名词词尾","example":"The ending turns the struggle into a state.","exampleCN":"这个词尾把搏斗变成一种状态。"},{"word":"reluctance","structure":"re- + luct- + -ance","meaning":"the state of pulling back","meaningCN":"向后拉的状态；不情愿","example":"Her reluctance filled the room.","exampleCN":"她的不情愿弥漫了整个房间。"},{"word":"reluctant","structure":"re- + luct- + -ant (adjective)","meaning":"unwilling; wrestling back","meaningCN":"不情愿的；反着摔的","example":"The reluctant witness spoke last.","exampleCN":"那名不情愿的证人最后才开口。"},{"word":"reluctantly","structure":"reluctant + -ly (adverb)","meaning":"in an unwilling way","meaningCN":"不情愿地","example":"She signed reluctantly.","exampleCN":"她不情愿地签了字。"},{"word":"reluctivity","structure":"reluctance + -ivity (property noun)","meaning":"magnetic reluctivity","meaningCN":"磁阻率","example":"Reluctivity describes the material.","exampleCN":"磁阻率描述了这种材料的性质。"},{"word":"reluctance motor","structure":"reluctance + motor (compound)","meaning":"a motor driven by changing magnetic reluctance","meaningCN":"靠磁阻变化驱动的电机","example":"The plant installed a reluctance motor.","exampleCN":"工厂安装了一台磁阻电机。"},{"word":"reluct","structure":"reluct (obsolete English verb)","meaning":"to strive against","meaningCN":"抗争（已废弃的英语动词）","example":"Reluct survives only in historical dictionaries.","exampleCN":"reluct 如今只留在历史词典里。"}],"latinEntries":[{"word":"luctari","structure":"luctari, luctatus sum (deponent verb, first conjugation)","meaning":"to wrestle, struggle","meaningCN":"摔跤；搏斗"},{"word":"lucta","structure":"lucta, luctae (f., first declension)","meaning":"a wrestling match","meaningCN":"一场摔跤"},{"word":"reluctari","structure":"re- (against) + luctari (to wrestle)","meaning":"to struggle against, resist","meaningCN":"抗争；抵抗"}],"derivatives":[{"word":"reluctantly","pos":"adv.","zh":"不情愿地（reluctant 加副词后缀，把迟疑转成动作方式）"},{"word":"reluctancy","pos":"n.","zh":"不情愿（reluctant 加旧式名词后缀，与常见名词后缀同源的罕用变体）"},{"word":"reluctivity","pos":"n.","zh":"磁阻率（reluctance「磁阻」加表性质的名词后缀，转入物理学量）"},{"word":"reluctance motor","pos":"n.","zh":"磁阻电机（由「磁阻」与「电动机」复合而成，指利用磁阻变化产生转矩的电机）"}]}},{"word":"imitation","ipa_uk":"/ˌɪmɪˈteɪʃən/","ipa_us":"/ˌɪmɪˈteɪʃən/","definition_zh":"模仿；仿制品；赝品；仿冒","definition_en":"the act of copying someone or something, or a copy made in this way","core_image":"一个人对着一面旧铜镜，把镜中人的动作一笔一笔描下来","scene":"博物馆商店里，一只古代陶俑被做成巴掌大的钥匙扣，价签上写明依照原件比例缩小复制。The label described the key ring as an imitation of the original figurine.","sceneCN":"这里 imitation 指「照原件做出的复制品」（第 3 个义项：物品的复制品）；句意为价签把这个钥匙扣称作原件小雕像的仿制品。","pos":[{"tag":"n.","zh":"模仿；仿制品；赝品；仿冒（可数或不可数）"}],"collocations":[{"phrase":"in imitation of","zh":"仿照；模仿"},{"phrase":"an imitation of","zh":"对……的模仿"},{"phrase":"a cheap imitation","zh":"廉价的仿制品"},{"phrase":"imitation leather","zh":"人造革"},{"phrase":"imitation goods","zh":"仿冒商品"},{"phrase":"imitation learning","zh":"模仿学习"}],"forms":[{"label":"复数","form":"imitations"},{"label":"动词","form":"imitate"},{"label":"形容词","form":"imitative"},{"label":"名词（模仿者）","form":"imitator"},{"label":"副词","form":"imitatively"}],"derivatives":[{"word":"imitative","pos":"adj.","zh":"模仿的；仿效的（由模仿词干加形容词后缀，表示具有模仿性质）"},{"word":"imitator","pos":"n.","zh":"模仿者（由模仿词干加表示人的后缀，语义从行为落到人身上）"},{"word":"imitatively","pos":"adv.","zh":"以模仿的方式（由 imitative 加副词后缀，把仿效性质转成动作方式）"},{"word":"imitativeness","pos":"n.","zh":"模仿性（由 imitative 加名词后缀，指仿效的倾向或性质）"}],"senses":[{"no":"01","title":"The act of copying behaviour","titleCN":"模仿行为","definition":"the act of doing what another person or thing does","definitionCN":"照着别人或别物去做的行为","example":"Children learn much of their speech by imitation.","exampleCN":"儿童很大一部分语言是通过模仿学会的。","why":"Imitation starts with the eye: a model is taken in, and the hand or voice repeats it.","whyCN":"模仿从眼睛开始：先接收一个样板，再由手或声音把它重复出来。"},{"no":"02","title":"Mimicry of a person","titleCN":"对人的模仿","definition":"a performance that copies someone's voice, manner or appearance","definitionCN":"复制某人嗓音、举止或外表的表演","example":"His imitation of the teacher made the whole class laugh.","exampleCN":"他对老师的模仿让全班都笑了。","why":"Here the copy is aimed at a person's style rather than at a thing, and the aim is often amusement.","whyCN":"这里的复制对象是一个人的风格而不是物件，目的常常是好笑。"},{"no":"03","title":"A copy of an object","titleCN":"物品的复制品","definition":"a thing made to look like another thing, often at a smaller scale","definitionCN":"做成与另一件东西相像的物品，常常按比例缩小","example":"The shop sells imitations of the museum's ancient figurines.","exampleCN":"这家店出售博物馆古代小雕像的复制品。","why":"The copy now exists as a separate object beside the original, with its own price and its own label.","whyCN":"复制品现在作为独立物件存在于原件旁边，有自己的价格和自己的标签。"},{"no":"04","title":"Counterfeit goods","titleCN":"仿冒品；赝品","definition":"a cheap copy made to be mistaken for an expensive original","definitionCN":"廉价复制、用来冒充昂贵原件的赝品","example":"Customs officers found boxes of imitation handbags.","exampleCN":"海关人员查获了几箱仿冒手提包。","why":"The copy now hides its own origin; it does not stand beside the original but tries to take its place.","whyCN":"复制品这时藏起了自己的出身；它不是站在原件旁边，而是想取代原件。"},{"no":"05","title":"Imitation as learning","titleCN":"作为学习机制的模仿","definition":"in psychology, copying as a way of acquiring a skill or behaviour","definitionCN":"心理学中，通过复制来习得技能或行为的方式","example":"The study measured imitation in infants watching an adult use a tool.","exampleCN":"这项研究测量了婴儿观看成人使用工具时的模仿行为。","why":"Repetition is how a body learns: the learner copies first and understands later.","whyCN":"重复是身体学习的方式：学习者先复制，之后再理解。"},{"no":"06","title":"Artistic mimesis","titleCN":"艺术上的摹仿","definition":"in art theory, the representation of nature or life by imitation","definitionCN":"艺术理论中，通过模仿来再现自然或生活","example":"The debate over imitation in art goes back to the ancient Greeks.","exampleCN":"关于艺术摹仿的争论可以追溯到古希腊。","why":"Art holds a mirror to the world; the copy is not a fake but a way of representing what is real.","whyCN":"艺术给世界举了一面镜子；这里的复制不是造假，而是再现真实的一种方式。"},{"no":"07","title":"Social imitation","titleCN":"社会性模仿","definition":"the copying of others' behaviour, fashion or habits across a group","definitionCN":"一个群体里对他人行为、时尚或习惯的复制","example":"Fashion spreads through social imitation more than through advertising.","exampleCN":"时尚更多靠社会性模仿传播，而不是靠广告。","why":"People copy in order to belong; the model is chosen because it looks like the group one wants to join.","whyCN":"人们模仿是为了归属；选择这个样板，是因为它像自己想加入的那个群体。"},{"no":"08","title":"In imitation of; the proverb","titleCN":"仿照；谚语中的模仿","definition":"used in the phrase in imitation of and in the saying that imitation is the sincerest form of flattery","definitionCN":"用于表示「仿照」的固定说法，也见于谚语「模仿是最真诚的恭维」","example":"The hall was built in imitation of a Roman bath.","exampleCN":"这座大厅是仿照罗马浴场建造的。","why":"The phrase turns copying into a method, and the proverb turns it into praise: to copy someone well is to say they are worth copying.","whyCN":"这个短语把复制变成一种方法，谚语则把它变成赞美：把一个人模仿得好，等于说这个人值得被模仿。"}],"etymology":{"intro":{"en":"Imitation came into English around 1400 from Old French imitacion, from Latin imitationem, the noun of action from imitari 'to copy, portray'. The word first named the act and only later the object.","cn":"imitation 在十五世纪初从古法语 imitacion 进入英语，源自拉丁语 imitationem，是 imitari「模仿、描摹」的动名词。这个词先指行为，后来才指物品。"},"items":[{"era":"LATIN IMITARI","en":"Imitari meant 'to copy, portray, imitate'. Its past-participle stem imitat- supplies the base of the English noun and its relatives.","cn":"imitari 意为「模仿、描摹、仿效」。它的过去分词词干提供了英语名词及其同族词的词基。"},{"era":"LATIN IMITATIO","en":"The action noun imitatio (genitive imitationis) meant 'a copying, imitation'. English took the accusative form imitationem through French.","cn":"动作名词 imitatio（属格 imitationis）意为「复制、模仿」。英语经法语借入的是它的宾格形式 imitationem。"},{"era":"OLD FRENCH IMITACION","en":"Old French imitacion carried the Latin noun into medieval French, and from there into English around 1400.","cn":"古法语 imitacion 把这个拉丁名词带进中世纪法语，又大约在十五世纪初进入英语。"},{"era":"MIDDLE ENGLISH","en":"The first English sense was 'emulation; act of copying'; the meaning 'an artificial likeness' is recorded only from around 1600.","cn":"英语最早的义项是「争胜、复制的动作」；而「人造的相似物」这一意思直到约十六世纪末才有记录。"},{"era":"MODERN ENGLISH","en":"Modern English uses the noun for copies, counterfeits, artistic mimesis and social copying; the adjective imitation is recorded from the nineteenth century, as in imitation leather.","cn":"现代英语用这个名词指复制品、赝品、艺术摹仿和社会性模仿；形容词用法从十九世纪起有记录，如「人造革」这一说法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of imitari is not settled. Some accounts connect it with imago 'image, likeness', while others reconstruct a PIE root *aim- 'to copy'; both are proposals, and neither can be demonstrated as the single source.","cn":"来源不确定：imitari 更深来源尚无定论。一些解释把它与 imago「图像、相似物」联系起来，另一些则重构原始印欧语词根 *aim-「复制」；两者都是假说，都无法被证明是唯一来源。"}]},"similar":{"note":{"en":"The first group holds words that look or sound close and are often mixed up with imitation; the second holds near neighbours that also name a copy, but with a different purpose.","cn":"第一组是与 imitation 形近或音近、常被混淆的词；第二组是同为「复制品」但目的不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"imitate","ipa":"/ɪˈmɪteɪt/","tag":"same family, verb","definition":"The verb at the base of the family: to copy someone or something.","definitionCN":"这一词族的动词基础：复制某人或某物。"},{"word":"imitative","ipa":"/ɪˈmɪtətɪv/","tag":"same family, adjective","definition":"The adjective meaning 'copying or tending to copy'; it describes the tendency, not the act.","definitionCN":"意为「模仿的、倾向于模仿的」形容词；它描写倾向，而不是行为本身。"},{"word":"limitation","ipa":"/ˌlɪmɪˈteɪʃən/","tag":"not related","definition":"A restriction, from Latin limes 'boundary'. It rhymes with imitation but comes from a different root.","definitionCN":"限制，来自拉丁 limes「边界」。它与 imitation 押韵，但词根完全不同，两者并非同源。"},{"word":"intimation","ipa":"/ˌɪntɪˈmeɪʃən/","tag":"not related","definition":"A hint or indirect suggestion, from intimate 'to make known'. The shared ending is misleading.","definitionCN":"暗示、间接提示，来自 intimate「使知道」。共同的词尾具有误导性，两者没有亲缘关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"copy","ipa":"/ˈkɒpi/","tag":"neutral duplicate","definition":"A general duplicate of an original; it carries no hint of deception or artistic theory.","definitionCN":"原件的普通复制品；它不带欺骗或艺术理论的意味。"},{"word":"replica","ipa":"/ˈreplɪkə/","tag":"exact and often authorized","definition":"An exact copy, often made at the same scale and with official approval; it is more precise than imitation.","definitionCN":"精确复制品，常按原尺寸并获正式许可；比 imitation 更精确。"},{"word":"counterfeit","ipa":"/ˈkaʊntəfɪt/","tag":"made to deceive","definition":"A fake made to pass as genuine, especially money or goods; deception is built into the word.","definitionCN":"冒充真品的假货，尤指钱币或商品；欺骗性写进了这个词本身。"},{"word":"mimicry","ipa":"/ˈmɪmɪkri/","tag":"behavioural or biological","definition":"The copying of another's appearance or behaviour, often for advantage; in biology it can help an animal survive.","definitionCN":"复制他者的外表或行为，常为取得优势；在生物学中可帮助动物生存。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词语素、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"imit- (copy) + -ation (action noun): imitation is literally 'the act of copying'.","cn":"复制词干加动作名词词尾：imitation 字面上就是「复制的动作」。"},{"en":"Latin imitari 'to copy' and imitatio 'a copying' are the direct sources of the word.","cn":"拉丁 imitari「复制」与 imitatio「复制行为」是这个词的直接来源。"},{"en":"The family runs imitate, imitation, imitative, imitator, imitatively.","cn":"同族词包括 imitate、imitation、imitative、imitator、imitatively。"},{"en":"Fixed phrases show the purpose: in imitation of, imitation leather, imitation goods, imitation learning.","cn":"固定搭配标出目的：仿照、人造革、仿冒商品、模仿学习。"},{"en":"The saying that imitation is the sincerest form of flattery is a fixed proverb, not a separate root meaning.","cn":"「模仿是最真诚的恭维」是一句固定谚语，并不是词根另长出的意思。"}],"abstract":[{"en":"Picture a hand tracing the outline of a shadow on a wall.","cn":"想象一只手在墙上描出影子的轮廓。"},{"en":"Picture a copy that wants to be mistaken for the original.","cn":"想象一个希望被误认为原件的复制品。"},{"en":"Picture a child learning a knot by watching the same hands three times.","cn":"想象一个孩子看着同一双手打了三次结，才学会这个结。"}]},"examples":[{"en":"Young children learn language partly by imitation.","cn":"幼儿部分通过模仿学习语言。"},{"en":"The vase is a nineteenth-century imitation of a Greek original.","cn":"这只花瓶是十九世纪对一件希腊原件的仿制品。"},{"en":"His imitation of the manager's voice was painfully accurate.","cn":"他对经理嗓音的模仿准确得让人尴尬。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「伊米泰申」—— 伊米对着镜子学泰申的动作，越学越像 → imitation 模仿；仿制品","word":"imitation"},"root":"拉丁 imitari「模仿、复制」，经古法语 imitacion 于十五世纪初进入英语。imitari 更深来源不确定：与 imago「图像」的联系属假说，重构词根 *aim-「复制」也只是提议，均无法定论。","sensesIntro":{"en":"Eight senses follow one copying gesture: look, repeat, and make a double. The double can be a performance, a replica, a fake, a learned skill, a work of art, a social habit, or a phrase that turns copying into praise.","cn":"八个义项都沿同一个复制动作展开：看、重复、做出一个「另一个」。这个「另一个」可以是一场表演、一件复制品、一件假货、一项学来的技能、一件艺术品、一种社会习惯，或一句把复制变成赞美的固定说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: an eye takes a model, and the hand makes a second version.","cn":"核心意象：眼睛接收一个样板，手做出第二个版本。"},"chain":["LOOK","COPY","REPEAT","MAKE A DOUBLE","LEARN BY WATCHING","PASS AS REAL"],"branches":[{"senses":"01","en":"THE CORE: the act begins with a model outside the self and ends with a repeated action.","cn":"核心：动作从一个自我之外的样板开始，以一次重复的行动结束。"},{"senses":"02","en":"THE DOUBLE AS PERFORMANCE: the copy is aimed at a person's voice or manner and often played for laughter.","cn":"作为表演的「另一个」：复制对象是一个人的嗓音或举止，常常是为了逗笑。"},{"senses":"03 · 04","en":"TWO KINDS OF OBJECT: a replica stands openly beside the original, while a counterfeit tries to take its place.","cn":"两类物件：复制品公开地站在原件旁边，赝品则想取代原件。"},{"senses":"05 · 07","en":"COPYING AS GROWTH: imitation lets a body learn a skill and lets a group share a habit.","cn":"作为成长的复制：模仿让身体学会技能，也让群体共享习惯。"},{"senses":"06 · 08","en":"THE DOUBLE IN CULTURE AND LANGUAGE: mimesis holds a mirror to nature, while a fixed phrase turns copying into a method and a proverb turns it into praise.","cn":"文化与语言里的「另一个」：摹仿给自然举镜子，固定短语把复制变成方法，谚语则把它变成赞美。"}]},"affixes":{"intro":{"en":"Imitation is a Latin action noun: a copying stem plus a very common noun ending, and the family spreads through verb, adjective, person and adverb forms.","cn":"imitation 是拉丁动作名词：复制词干加一个极常见的名词词尾，词族再向动词、形容词、人物名词和副词扩展。"},"latinIntro":{"en":"The Latin family is compact: a verb for copying, its action noun, and its past participle. English built the rest from the imitat- stem.","cn":"拉丁这一族很紧凑：一个表示复制的动词、它的动作名词和过去分词。英语其余的形式都从这个过去分词词干长出来。"},"items":[{"word":"imit-","structure":"imitari (Latin verb: to copy, portray)","meaning":"to copy; to portray","meaningCN":"复制；描摹","example":"The stem carries the act of copying.","exampleCN":"这个词干承载着复制的动作。"},{"word":"-ation","structure":"-ation (from Latin -atio, action-noun ending)","meaning":"the act or result of doing something","meaningCN":"做某事的动作或结果","example":"The ending turns the verb into a noun of action.","exampleCN":"这个词尾把动词变成动作名词。"},{"word":"imitation","structure":"imit- + -ation","meaning":"the act of copying; a copy","meaningCN":"模仿的行为；复制品","example":"The museum sells imitations.","exampleCN":"博物馆出售复制品。"},{"word":"imitate","structure":"imitate (verb, from Latin imitari)","meaning":"to copy someone or something","meaningCN":"模仿；仿效","example":"Children imitate what they hear.","exampleCN":"孩子会模仿听到的东西。"},{"word":"imitative","structure":"imitat- + -ive (adjective)","meaning":"tending to copy","meaningCN":"倾向于模仿的","example":"The style is highly imitative.","exampleCN":"这种风格模仿性很强。"},{"word":"imitator","structure":"imitat- + -or (person noun)","meaning":"a person who copies","meaningCN":"模仿者","example":"He is a skilled imitator of voices.","exampleCN":"他是个擅长模仿嗓音的人。"},{"word":"imitatively","structure":"imitative + -ly (adverb)","meaning":"in a copying way","meaningCN":"以模仿的方式","example":"The child imitatively repeated the gesture.","exampleCN":"孩子模仿着重复了那个动作。"},{"word":"imitativeness","structure":"imitative + -ness (noun of quality)","meaning":"the quality of being imitative","meaningCN":"模仿性","example":"Researchers rated the imitativeness of each child.","exampleCN":"研究者评估了每个孩子的模仿性。"},{"word":"inimitable","structure":"in- (not) + imitable (able to be imitated)","meaning":"impossible to copy","meaningCN":"无法模仿的；独一无二的","example":"She has an inimitable way of telling a story.","exampleCN":"她讲故事的方式无人能仿。"}],"latinEntries":[{"word":"imitari","structure":"imitari, imitatus sum (deponent verb, first conjugation)","meaning":"to copy, portray, imitate","meaningCN":"复制；描摹；模仿"},{"word":"imitatio","structure":"imitatio, imitationis (f., third declension)","meaning":"a copying, imitation","meaningCN":"复制；模仿"},{"word":"imitatus","structure":"imitatus, -a, -um (past participle)","meaning":"copied, imitated","meaningCN":"被复制的；被模仿的"}],"derivatives":[{"word":"imitative","pos":"adj.","zh":"模仿的；仿效的（模仿词干加形容词后缀，表示具有模仿性质）"},{"word":"imitator","pos":"n.","zh":"模仿者（模仿词干加表示人的后缀，语义落到人身上）"},{"word":"imitatively","pos":"adv.","zh":"以模仿的方式（imitative 加副词后缀，把性质转成动作方式）"},{"word":"imitativeness","pos":"n.","zh":"模仿性（imitative 加名词后缀，指仿效的倾向）"}]}},{"word":"relationship","ipa_uk":"/rɪˈleɪʃənʃɪp/","ipa_us":"/rɪˈleɪʃənʃɪp/","definition_zh":"关系；关联；亲属关系；恋爱关系；比例关系；相关性","definition_en":"the way two or more people or things are connected, or a particular connection of this kind that is maintained over time","core_image":"两个人或两件事之间牵着一根看不见的线，每见一次面、每办一件事，线就被拉紧或放松一点","scene":"实验室里两名新生被分到同一张操作台，一个学期里他们互相顶班、替对方核对数据，连导师都看出这份默契已经超出了排班表。Over that semester the relationship between the two students deepened faster than either of them expected.","sceneCN":"这里 relationship 指「人与人长期相处形成的联结」（第 1 个义项）；句意为：在那个学期里，这两名学生之间的关系加深得比他们各自预料的都快。","pos":[{"tag":"n.","zh":"关系；关联；亲属关系；恋爱关系"}],"collocations":[{"phrase":"build a relationship","zh":"建立关系（强调逐步经营）"},{"phrase":"close relationship","zh":"密切的关系"},{"phrase":"relationship between A and B","zh":"甲与乙之间的关系"},{"phrase":"working relationship","zh":"工作关系；同事间的协作关系"},{"phrase":"long-term relationship","zh":"长期关系；长期伴侣关系"},{"phrase":"in a relationship","zh":"处于恋爱关系中"},{"phrase":"relationship counselling","zh":"伴侣关系咨询"}],"forms":[{"label":"复数","form":"relationships"},{"label":"同族形容词","form":"relational"},{"label":"同族副词","form":"relationally"}],"derivatives":[{"word":"relational","pos":"adj.","zh":"关系的；关系层面的（由 relation 加形容词后缀，把视角转向关系本身）"},{"word":"related","pos":"adj.","zh":"相关的；有亲属关系的（由 relate 加过去分词后缀，表示已被联系起来）"},{"word":"relatedness","pos":"n.","zh":"关联性；亲缘程度（由 related 加名词后缀，指被联系起来的状态）"},{"word":"interrelation","pos":"n.","zh":"相互关联（由表示「在……之间」的前缀加 relation，指两方彼此牵连）"},{"word":"relationally","pos":"adv.","zh":"在关系层面上（由 relational 加副词后缀，把讨论限定在关系维度）"}],"senses":[{"no":"01","title":"A bond kept alive between people","titleCN":"人与人之间维持着的联结","definition":"the way two people are connected through ongoing contact, trust or shared experience","definitionCN":"两个人通过持续接触、信任或共同经历而形成的联结","example":"A good relationship with your colleagues makes long days easier.","exampleCN":"和同事关系融洽，漫长的日子也会好过一些。","why":"Two people keep choosing to meet and talk; every exchange leaves a trace, so the connection exists as a history rather than as a single act.","whyCN":"两个人一次次选择见面、说话，每次交流都留下痕迹；所以这份联结是一段历史，而不是一次性的动作。"},{"no":"02","title":"A romantic partnership","titleCN":"恋爱关系；伴侣关系","definition":"a romantic or sexual partnership that two people maintain over time","definitionCN":"两个人长期维持的恋爱或性伴侣关系","example":"They have been in a relationship for three years.","exampleCN":"他们交往已经三年了。","why":"The general bond narrows to one kind: intimacy between partners, which society treats as a named state with its own rules and vocabulary.","whyCN":"普通的联结收窄为一种特定联结：伴侣之间的亲密；社会把它当作一个有名称、有规则、有专门说法的状态。"},{"no":"03","title":"A link between things","titleCN":"事物之间的关联","definition":"the connection or correspondence between two things, especially when one affects the other","definitionCN":"两件事物之间的联系或对应，尤指一方会影响另一方","example":"Researchers found a clear relationship between sleep length and memory.","exampleCN":"研究者发现睡眠时长与记忆力之间存在明显的关联。","why":"The same line that joins people also joins facts: one thing points to another, so a change in one shows up as a change in the other.","whyCN":"连接人的那根线也能连接事实：一件事指向另一件事，于是一方的变化会在另一方身上显现。"},{"no":"04","title":"Kinship by blood or marriage","titleCN":"血缘或婚姻上的亲属关系","definition":"the state of being related to someone by blood or by marriage","definitionCN":"因血缘或婚姻而与某人构成的亲属关系","example":"The chart maps every relationship in the family back to the eighteenth century.","exampleCN":"这张图表把这个家族每一条亲属关系都追溯到十八世纪。","why":"Kinship is a bond you do not choose; it is fixed by birth and marriage, so the word can name a position in a family rather than a feeling.","whyCN":"亲属关系不是自己挑选的，而由出生与婚姻固定下来；所以这个词可以指家族中的位置，而不是指感情。"},{"no":"05","title":"A fixed relation between quantities","titleCN":"数量之间的固定关系","definition":"a regular correspondence between quantities, such that a change in one follows a rule in the other","definitionCN":"数量之间有规律的对应，一方变化时另一方按规则变化","example":"The graph shows the relationship between temperature and pressure.","exampleCN":"这张图显示了温度与压强之间的关系。","why":"When the correspondence can be written as a rule, the bond becomes measurable: one quantity sets the value of the other, and the line turns into a formula.","whyCN":"当这种对应能写成规则时，联结就变得可测量：一个量决定另一个量的取值，那根线也就变成了一条公式。"},{"no":"06","title":"A continuing professional tie","titleCN":"持续的工作或业务关系","definition":"an ongoing professional connection between people, teams or organizations","definitionCN":"个人、团队或机构之间持续的职业联系","example":"The two firms signed a contract but relied on a strong working relationship.","exampleCN":"两家公司签了合同，但真正依靠的是一种牢固的工作关系。","why":"Work needs repeated dealings, so the word names the trust and habit that grow alongside the contract and outlive a single deal.","whyCN":"工作需要反复打交道，于是这个词指合同旁边长出来的信任与默契，它们能比一次交易活得更久。"},{"no":"07","title":"A measurable association in research","titleCN":"研究中可测量的相关性","definition":"in research, an association between variables that can be measured and tested","definitionCN":"研究中变量之间可以测量并检验的关联","example":"The study reports a significant relationship between income and health.","exampleCN":"该研究报告了收入与健康之间显著的相关性。","why":"A statistical relationship is the same bond reduced to numbers: the variables move together more often than chance alone would allow.","whyCN":"统计上的相关性就是把同一根联结压缩成数字：两个变量同时变动的频率，高过纯属偶然所能解释的程度。"},{"no":"08","title":"A personal stance toward an object or activity","titleCN":"对某物或某活动形成的个人态度","definition":"a person's emotional or attitudinal connection with something non-human, such as food, money or a place","definitionCN":"个人与非人事物（如食物、金钱、地方）之间带有情感或态度的联结","example":"She describes her relationship with money as something she inherited rather than chose.","exampleCN":"她把自己与金钱的关系说成是继承来的，而不是自己选择的。","why":"The bond no longer needs a second person: an activity or object can sit at the other end, and the connection becomes a personal stance built from repeated experience.","whyCN":"这根联结不再需要另一个人：一种活动或一件物品可以占据另一端，联结于是成为由反复经验养成的个人态度。"}],"etymology":{"intro":{"en":"Relationship is a transparent English compound of relation and the suffix -ship. The noun relation came from Latin through Old French, and the suffix is native Old English.","cn":"relationship 是英语里构造透明的复合词：relation 加上表示状态的名词后缀。名词 relation 经古法语来自拉丁语，后缀则是土生土长的古英语成分。"},"items":[{"era":"LATIN REFERRE","en":"Referre was built from re- 'back' and ferre 'to carry, bear', and meant 'to carry back, bring back', hence 'to report'. The noun of action was relatio.","cn":"referre 由表示「回」的前缀和 ferre「携带、承载」构成，意为「带回、拿回」，因此引申为「报告」。它的动作名词是 relatio。"},{"era":"LATIN RELATIO","en":"Relatio named a bringing back and a report or account. Later uses added the idea of reference or respect, from which the modern notion of a connection developed.","cn":"relatio 指「带回」以及「报告、叙述」。后来的用法加入「指向、关涉」的意思，现代「联系、关系」的观念就是从这里长出来的。"},{"era":"OLD FRENCH","en":"Old French took the Latin noun as relation, keeping the senses of report and account; English borrowed the word in the fourteenth century.","cn":"古法语借入这个拉丁名词作 relation，保留了「报告、叙述」的含义；英语在十四世纪把它借了进来。"},{"era":"MIDDLE ENGLISH","en":"In Middle English relation still meant an account of events more often than a connection. The sense of a link between things grew out of 'reference to' or 'respecting'.","cn":"在中古英语里，relation 更常指「对事件的叙述」而不是「联系」。「事物之间的联系」这一义项是从「指向、关于」发展出来的。"},{"era":"OLD ENGLISH -SHIP","en":"The suffix -ship goes back to Old English -scipe, 'state, condition, office'. It is generally considered to come from a Germanic base meaning 'to shape, create', reconstructed as *-skapiz.","cn":"那个名词后缀可追溯到古英语中意为「状态、身份、职位」的词尾。一般认为它来自一个意为「塑造、创造」的日耳曼语词干，重构形式为 *-skapiz。"},{"era":"MODERN ENGLISH","en":"Relation plus -ship produced relationship, generally dated to the seventeenth century, first as the state of being connected and later as a named social or romantic tie.","cn":"relation 加那个名词后缀构成 relationship，一般认为是十七世纪的产物；最初指「被联系的状态」，后来才指有名称的社会或恋爱关系。"}]},"similar":{"note":{"en":"The first group holds words built on the same Latin verb or on the same noun; the second holds words that also name a connection but differ in scope and warmth.","cn":"第一组是与本词同出一个拉丁动词或同一名词的词；第二组是同样表示联结、但范围和温度不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relation","ipa":"/rɪˈleɪʃən/","tag":"base noun","definition":"The noun without the suffix. It names the connection itself or a telling of events, not necessarily a continuing personal bond.","definitionCN":"去掉后缀的名词，指联系本身或对事件的叙述，未必是持续的个人联结。"},{"word":"relative","ipa":"/rɪˈleɪtɪv/","tag":"same family","definition":"Built on the same Latin verb, but it means a family member or a comparative judgement; it never means a relationship.","definitionCN":"同出那个拉丁动词，但指亲属或比较的判断，从不表示「关系」本身。"},{"word":"unrelated","ipa":"/ˌʌnrɪˈleɪtɪd/","tag":"negated form","definition":"un- plus related: it says there is no connection at all, so it cannot fill the place of relationship.","definitionCN":"否定前缀加 related：说明完全没有联系，因此不能替代 relationship。"},{"word":"relations","ipa":"/rɪˈleɪʃənz/","tag":"plural form","definition":"The plural of relation, common in diplomacy for dealings between groups; it is a different noun from relationship.","definitionCN":"relation 的复数，常用于外交指团体间的往来；它是另一个名词，不是 relationship。"}]},{"heading":"NEAR MEANING","entries":[{"word":"connection","ipa":"/kəˈnekʃən/","tag":"broadest link","definition":"The widest word for any link; relationship usually adds duration and mutual involvement.","definitionCN":"表示任何联系的最宽泛的词；relationship 通常多出「持续」和「彼此投入」的意思。"},{"word":"bond","ipa":"/bɒnd/","tag":"emotional tie","definition":"A strong feeling link, often warmer and closer than relationship; it stresses attachment rather than social arrangement.","definitionCN":"强烈的情感联结，往往比 relationship 更亲近温暖；强调依恋而非社会安排。"},{"word":"liaison","ipa":"/liˈeɪzən/","tag":"formal or discreet","definition":"A working or romantic link between people or groups, often kept discreet; narrower and more formal.","definitionCN":"个人或团体之间工作或恋爱上的联系，常带隐秘色彩；范围更窄、更正式。"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃən/","tag":"looser link","definition":"A link through shared activity or membership rather than personal intimacy; it can also mean a formal organization.","definitionCN":"因共同活动或成员身份而有的联系，而非私人亲密；还可指正式的组织。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"relation plus -ship: the suffix turns a connection into a continuing state that someone holds.","cn":"relation 加表示状态的名词后缀：这个后缀把一次联系变成一个持续被人持有的状态。"},{"en":"The same suffix appears in friendship, partnership, membership and ownership, all names of states rather than actions.","cn":"同一个后缀还出现在 friendship、partnership、membership、ownership 里，它们都指状态而不是动作。"},{"en":"Build a relationship is the normal verb phrase: the thing is constructed over time, not found ready-made.","cn":"build a relationship 是常见动词搭配：这种东西要靠时间搭建，不是现成捡到的。"},{"en":"In a relationship marks the romantic sense as a status, like a box that a person checks.","cn":"in a relationship 把恋爱义标成一种身份状态，像在表格里勾选一格。"},{"en":"Working relationship keeps the word in offices and studios, where the tie must survive deadlines.","cn":"「工作关系」这一搭配把这个词留在办公室和工作室里，那里的联结必须扛得住截止日期。"}],"abstract":[{"en":"Picture a rope between two people: every meeting tightens it, every silence lets it slacken.","cn":"想象两人之间有一根绳：每次见面把它拉紧一点，每次沉默让它松一点。"},{"en":"The other end need not be a person: a job, a place or money can hold the rope just as well.","cn":"另一端不必是人：一份工作、一个地方或金钱，同样能握住这根绳。"},{"en":"No rope is visible; only repeated behaviour shows where it runs.","cn":"绳子看不见，只有反复的行为才能显出它走向哪里。"}]},"examples":[{"en":"The relationship between the two countries improved after the trade talks.","cn":"贸易谈判之后，两国之间的关系有所改善。"},{"en":"She values her relationship with her students more than her title.","cn":"她看重与学生之间的关系，胜过看重自己的头衔。"},{"en":"A healthy relationship requires both people to listen.","cn":"健康的关系需要两个人都愿意倾听。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞雷申」听起来像「累神」：处关系最累神；后面跟「希普」，像同坐一条船（ship），同船共渡才见关系稳不稳。","word":"relationship"},"root":"源自拉丁 referre「带回、报告」，其名词 relatio「带回；报告」经古法语 relation 进入英语；再加古英语中表示状态、身份的名词后缀。ferre 的更早来源一般认为是重构形式，意为「携带」，属重构而非实证。","sensesIntro":{"en":"Eight senses grow from one line between two parties: the line can join people, narrow into romance, join facts, be fixed by birth, be measured as a rule, be kept for work, be counted as data, or be tied to an object.","cn":"八个义项都从两方之间的一根线展开：这根线可以连接人、收窄为恋爱、连接事实、由出生固定、被写成规则、为工作而维持、被统计成数据，也可以拴在一件物品上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line between two parties kept alive by repeated contact.","cn":"核心意象：两方之间一根靠反复接触维持的线。"},"chain":["TWO PARTIES","LINE FORMED","CONTACT REPEATED","TRUST ACCUMULATES","STATE NAMED","MEASURE APPLIED"],"branches":[{"senses":"01 · 02","en":"PEOPLE FIRST: a general human bond, then the narrowed bond that society labels romance.","cn":"先讲人：普通的人际联结，再收窄为社会贴上恋爱标签的那种联结。"},{"senses":"03","en":"THE LINE LEAVES PEOPLE: facts and events can be joined by the same kind of link.","cn":"线离开人：事实与事件也能被同一种联结接起来。"},{"senses":"04","en":"GIVEN, NOT CHOSEN: birth and marriage fix the line before any feeling arrives.","cn":"被给予而非被挑选：出生与婚姻先固定了这条线，感情随后才来。"},{"senses":"05 · 07","en":"MEASURED LINK: a rule between quantities, and the statistical version counted across many cases.","cn":"可测量的联结：数量之间的规则，以及在上千案例中被统计的相关性。"},{"senses":"06 · 08","en":"ATTACHED TO THINGS: the same line runs to a job or a firm, and inward to money or food.","cn":"拴到事物上：同一根线可以伸向工作或公司，也可以向内伸向金钱或食物。"}]},"affixes":{"intro":{"en":"Relationship is built from a Latin noun and a native suffix, and both parts still work productively in English.","cn":"relationship 由一个拉丁名词和一个本土后缀构成，两部分在现代英语里都仍然能产。"},"latinIntro":{"en":"The Latin verb for carrying gave English a whole family through its noun and its past participle: refer, relate, relation, relative, relativity and correlation.","cn":"拉丁语中表示「携带」的动词，通过它的名词和过去分词给英语送来了一整族词：refer、relate、relation、relative、relativity 与 correlation。"},"items":[{"word":"relation","structure":"relat- (from relatus, carried back) + -ion (noun suffix)","meaning":"a bringing back; a report; a connection","meaningCN":"带回；报告；联系","example":"The relation between the two events was never proved.","exampleCN":"两件事之间的联系从未得到证实。"},{"word":"relationship","structure":"relation + -ship (state, condition)","meaning":"the state of being connected; a continuing tie","meaningCN":"被联系的状态；持续的联结","example":"Their relationship survived the move to another city.","exampleCN":"他们的关系在搬去另一座城市后仍维持下来。"},{"word":"relate","structure":"re- (back) + -late (from relatus)","meaning":"to tell an account; to show a connection","meaningCN":"讲述；使产生联系","example":"She related the story without a single pause.","exampleCN":"她一口气讲完了那个故事。"},{"word":"relative","structure":"relat- + -ive (tending to, having the quality)","meaning":"connected by family; judged by comparison","meaningCN":"有亲属关系的；比较而言的","example":"The cost is low relative to the benefit.","exampleCN":"相对于收益，成本很低。"},{"word":"relativity","structure":"relative + -ity (abstract noun suffix)","meaning":"the quality of being judged in relation to something else","meaningCN":"相对性；相对论","example":"Relativity replaced absolute time with measured time.","exampleCN":"相对论用可测量的时间取代了绝对时间。"},{"word":"refer","structure":"re- (back) + ferre (carry)","meaning":"to carry back; to direct attention to","meaningCN":"把话带回；指向；提及","example":"The footnote refers to an earlier chapter.","exampleCN":"这条脚注指向前面的一章。"},{"word":"transfer","structure":"trans- (across) + ferre (carry)","meaning":"to carry from one place or person to another","meaningCN":"转移；搬运；转让","example":"The funds were transferred to a local account.","exampleCN":"资金被转到当地一个账户。"},{"word":"correlation","structure":"cor- (together) + relation (connection)","meaning":"a mutual connection between two sets of data","meaningCN":"两组数据之间相互对应的关联","example":"The correlation was strong but not causal.","exampleCN":"这种相关性很强，但不是因果关系。"},{"word":"partnership","structure":"partner + -ship (state, condition)","meaning":"the state of working together as partners","meaningCN":"合伙关系；伙伴状态","example":"The partnership lasted through two recessions.","exampleCN":"这段合伙关系熬过了两次经济衰退。"}],"latinEntries":[{"word":"referre","structure":"re- (back) + ferre (carry)","meaning":"to carry back, bring back, report","meaningCN":"带回、拿回、报告"},{"word":"relatio","structure":"relat- (carried back) + -io (action noun)","meaning":"a bringing back; a report; a reference","meaningCN":"带回；报告；关涉"},{"word":"relatus","structure":"past participle of referre","meaning":"carried back; reported","meaningCN":"被带回的；被报告的"}],"derivatives":[{"word":"relational","pos":"adj.","zh":"关系的（relation 加形容词后缀，落到关系这一维度）"},{"word":"related","pos":"adj.","zh":"相关的（relate 加过去分词后缀，表示已经被联系起来）"},{"word":"relatedness","pos":"n.","zh":"关联性（related 加名词后缀，指被联系的状态）"},{"word":"interrelation","pos":"n.","zh":"相互关联（表示「在……之间」的前缀加 relation，指双向牵连）"},{"word":"correlation","pos":"n.","zh":"在关系层面上（relational 加副词后缀，把讨论限定在关系维度）"}]}},{"word":"relation","ipa_uk":"/rɪˈleɪʃən/","ipa_us":"/rɪˈleɪʃən/","definition_zh":"关系；关联；亲属；亲属关系；（复数）往来；叙述；数学中的关系","definition_en":"a connection between things or people, an account of events, or in the plural the dealings between groups","core_image":"一根线从甲指到乙：两头可以是人、数字、事件或一句话，线的两端由规则或经历固定下来","scene":"一份年度报告把工资涨幅和同期生产率并排放在同一张图表上，编辑要求作者说明两者究竟怎样互相牵动。The report examines wage growth in relation to productivity gains over the same decade.","sceneCN":"这里 relation 出现在表示「相对于、就……而言」的固定说法中（第 8 个义项）；句意为：这份报告考察同一十年间工资增长相对于生产率提升的情况。","pos":[{"tag":"n.","zh":"关系；关联；亲属；亲属关系；往来；叙述；数学关系"}],"collocations":[{"phrase":"in relation to","zh":"关于；相对于；就……而言"},{"phrase":"relations between","zh":"……之间的关系或往来"},{"phrase":"diplomatic relations","zh":"外交关系"},{"phrase":"public relations","zh":"公共关系"},{"phrase":"bear no relation to","zh":"与……毫不相干"},{"phrase":"a distant relation","zh":"远亲"},{"phrase":"have relations with","zh":"与……有性关系（正式委婉说法）"}],"forms":[{"label":"复数","form":"relations"},{"label":"同族形容词","form":"relational"},{"label":"同族副词","form":"relationally"},{"label":"同族动词","form":"relate"}],"derivatives":[{"word":"relational","pos":"adj.","zh":"关系的（由 relation 加形容词后缀，转向关系这一维度）"},{"word":"relate","pos":"v.","zh":"讲述；使有联系（由表示「回」的前缀加拉丁语「携带」词干，把话或物带回原处）"},{"word":"relative","pos":"adj.","zh":"相对的；有亲属关系的（由关系词干加形容词后缀，表示「倾向于关联的」）"},{"word":"relativity","pos":"n.","zh":"相对性；相对论（由 relative 加抽象名词后缀，指只能相对衡量的性质）"},{"word":"correlation","pos":"n.","zh":"相关性（由表示「共同」的前缀加 relation，指两组数据共同变动）"}],"senses":[{"no":"01","title":"A connection between things","titleCN":"事物之间的联系","definition":"the way in which two things are connected or affect each other","definitionCN":"两件事物相互连接或相互影响的方式","example":"The study looks at the relation between diet and heart disease.","exampleCN":"这项研究考察饮食与心脏病之间的联系。","why":"The noun names the line itself, without saying who keeps it alive; it is the bare shape of one thing pointing at another.","whyCN":"这个名词只指那根线本身，不交代是谁在维持它；它就是「一物指向另一物」的最简形状。"},{"no":"02","title":"A relative, a person at the other end","titleCN":"亲属：站在线另一端的人","definition":"a person connected to you by blood or marriage; a relative","definitionCN":"因血缘或婚姻与你相连的人；亲戚","example":"He invited every distant relation he could find for the reunion.","exampleCN":"他请来了能联系上的每一位远亲参加聚会。","why":"The line between two people can be read from either end: instead of naming the tie, the word can name the person standing at the far end.","whyCN":"两人之间的线可以从任一端读：这个词不命名那根联结，而命名站在另一头的人。"},{"no":"03","title":"The state of kinship","titleCN":"亲属关系：由血缘或婚姻固定的状态","definition":"the state of being connected to someone by blood or marriage","definitionCN":"因血缘或婚姻而与某人相连的状态","example":"The lawyer checked the degree of relation before dividing the estate.","exampleCN":"律师在分割遗产之前先核对了亲属关系的亲疏程度。","why":"If a person can be called a relation, the abstract condition that puts them there also takes the name; the person and the state are two readings of one line.","whyCN":"既然站在那头的人可以叫 relation，把他放到那里的抽象状态也沿用这个词；人与状态只是同一根线的两种读法。"},{"no":"04","title":"An account or narrative","titleCN":"叙述；陈述（正式）","definition":"a formal account or narrative of events","definitionCN":"对事件所作的正式叙述或陈述","example":"The witness gave a careful relation of what happened that night.","exampleCN":"证人仔细陈述了那天夜里发生的事。","why":"The Latin noun first meant a report brought back. Since the modern link sense grew out of 'referring to', the older reporting sense survived in formal prose.","whyCN":"这个拉丁名词最初指「带回来的报告」。现代的联系义是从「关涉、指向」长出来的，较老的报告义便留在正式书面语里。"},{"no":"05","title":"Dealings between groups","titleCN":"（复数）团体之间的往来","definition":"in the plural, the way countries, groups or organizations deal with one another","definitionCN":"作复数时，指国家、团体或机构彼此打交道的方式","example":"The two countries restored diplomatic relations after ten years.","exampleCN":"两国在十年后恢复了外交关系。","why":"When many lines run between two groups, the plural names the whole set of dealings rather than a single tie between two people.","whyCN":"当两个团体之间跑着许多条线时，复数形式命名的是整套往来，而不是两个人之间的单一联结。"},{"no":"06","title":"Sexual intercourse, stated formally","titleCN":"性关系（正式委婉语）","definition":"a formal or euphemistic term for sexual intercourse, usually in the phrase have relations with","definitionCN":"对性交的正式委婉说法，通常用于「与……有性关系」这一固定表达","example":"The novel hints that they had relations before the marriage.","exampleCN":"这部小说暗示他们在婚前就有过性关系。","why":"Sexual contact is treated as the closest possible line between two bodies, so formal usage borrowed the word for connection and kept it behind a polite veil.","whyCN":"性接触被当作两具身体之间最紧密的一条线，于是正式用法借用了「联系」这个词，并把它藏在礼貌的帷幕后面。"},{"no":"07","title":"A relation in mathematics","titleCN":"数学中的关系","definition":"in mathematics, a set of ordered pairs showing how the elements of two sets correspond","definitionCN":"数学中表示两个集合元素如何对应的有序对集合","example":"A function is a special kind of relation in which each input has one output.","exampleCN":"函数是一种特殊的关系，其中每个输入只对应一个输出。","why":"The connection stripped of people and stories becomes a set of pairs: each first element is tied to a second by a stated rule.","whyCN":"把人和故事剥掉之后，联结变成一组有序对：每个第一个元素都按一条明说的规则系到第二个元素上。"},{"no":"08","title":"Reference or comparison in a fixed phrase","titleCN":"固定短语中的关涉与比较","definition":"the pointing of one thing at another in the phrase in relation to, meaning concerning or compared with","definitionCN":"在表示「相对于、就……而言」的固定说法中，一物指向另一物，表示「关于」或「与……相比」","example":"The fee seems small in relation to the total budget.","exampleCN":"相对于总预算，这笔费用显得很小。","why":"The word can point one thing at another for comparison rather than describe a lasting tie, and grammar freezes this pointing into a preposition-like phrase.","whyCN":"这个词可以让一物指向另一物以作比较，而不必描述持久的联结；语法把这种指向凝固成一个类似介词的短语。"}],"etymology":{"intro":{"en":"Relation came to English from Latin relatio by way of Old French. Its oldest sense was a report carried back, and the sense of a connection developed from the idea of referring to something.","cn":"relation 经古法语从拉丁 relatio 进入英语。它最古老的意思是「带回来的报告」，而「联系」义是从「关涉某物」这一观念发展出来的。"},"items":[{"era":"LATIN REFERRE","en":"Referre joined re- 'back' to ferre 'to carry, bear'. It meant 'to carry or bring back' and, in speech, 'to report, relate'.","cn":"referre 把表示「回」的前缀加到 ferre「携带、承载」上，意为「带回、拿回」，用于言语时就是「报告、讲述」。"},{"era":"LATIN RELATIO","en":"Relatio was the action noun of referre: a bringing back, a report, an account. Later prose also used it for reference or respect, the seed of the modern link sense.","cn":"relatio 是 referre 的动作名词：带回、报告、叙述。后来的散文还用它表示「关涉、指向」，这就是现代联系义的种子。"},{"era":"OLD FRENCH RELACION","en":"Old French borrowed the noun as relacion or relation and kept the meaning 'report, account'. English took the word in the fourteenth century.","cn":"古法语借入这个名词作 relacion 或 relation，保留「报告、叙述」的意思。英语在十四世纪接受了这个词。"},{"era":"MIDDLE ENGLISH","en":"In Middle English a relation was usually a telling of events. The sense of a connection between things appears later, through the notion of one thing being referred to another.","cn":"在中古英语里，relation 通常指对事件的讲述。「事物之间的联系」义后来才出现，路径是「一物被指向另一物」。"},{"era":"MODERN ENGLISH","en":"The plural relations became the standard word for dealings between countries and groups, while in everyday British speech a relation can still mean a relative.","cn":"复数 relations 成为国家与团体间往来的标准说法；在日常英式英语里，a relation 仍可指一位亲戚。"},{"era":"PROTO-INDO-EUROPEAN","en":"Standard references trace ferre to the reconstructed root *bher- 'to carry, bear'. This is a reconstructed form, not an attested word, and the reconstruction is generally accepted rather than proved.","cn":"通行资料把 ferre 追溯到重构词根 *bher-「携带、承载」。这是重构形式，不是有文献记录的词；这一重构一般被接受，而非被证明。"}]},"similar":{"note":{"en":"The first group separates close forms, including one word that only looks related; the second compares nouns that also name links but of a different reach.","cn":"第一组分辨形近词，其中有一个只是看起来像同族；第二组比较同样表示联系、但覆盖范围不同的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relationship","ipa":"/rɪˈleɪʃənʃɪp/","tag":"same stem","definition":"relation plus -ship. It adds the idea of a maintained personal tie, so it is narrower than relation in the abstract sense.","definitionCN":"relation 加表示状态的名词后缀，多出「被人持续维持的个人联结」这层意思，因此比抽象义的 relation 更窄。"},{"word":"relative","ipa":"/rɪˈleɪtɪv/","tag":"different ending","definition":"The same Latin stem with -ive: it means a family member or a comparative judgement, never a connection itself.","definitionCN":"同一拉丁词干加形容词后缀：指亲属或比较判断，从不指联系本身。"},{"word":"relate","ipa":"/rɪˈleɪt/","tag":"verb form","definition":"The verb of the family: to tell a story or to connect two things, not the connection as a noun.","definitionCN":"这一族的动词：讲述故事或把两物联系起来，而不是作为名词的「联系」。"},{"word":"relay","ipa":"/ˈriːleɪ/","tag":"not related","definition":"A race or a device that passes something on. It came through French relayer, not from Latin referre, so it is not related to relation.","definitionCN":"接力赛或传递装置，经法语 relayer 而来，并非出自拉丁 referre，所以与 relation 没有词源关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"connection","ipa":"/kəˈnekʃən/","tag":"bare link","definition":"The most general word for a link of any kind, with no hint of family, diplomacy or measurement.","definitionCN":"表示任何联系的最泛用的词，不带亲属、外交或测量的暗示。"},{"word":"correlation","ipa":"/ˌkɒrəˈleɪʃən/","tag":"statistical","definition":"A mutual relation between two sets of data, measured by how often they move together.","definitionCN":"两组数据之间相互对应的关系，用它们同时变动的频率来衡量。"},{"word":"liaison","ipa":"/liˈeɪzən/","tag":"formal and discreet","definition":"A working or romantic link, often confidential and between groups rather than individuals.","definitionCN":"工作或恋爱上的联系，常带保密色彩，且多指团体之间而非个人之间。"},{"word":"tie","ipa":"/taɪ/","tag":"close and concrete","definition":"A close link or obligation, warmer and more concrete than relation; it suggests something that binds.","definitionCN":"紧密的联系或义务，比 relation 更温暖、更具体，带有「捆住」的意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"re- plus ferre, 'carry back': a relation carries one thing back to another and makes them answerable to each other.","cn":"表示「回」的前缀加 ferre「携带」构成「带回」：relation 把一物带回到另一物那里，使两者彼此对应。"},{"en":"In relation to is a fixed phrase that turns the noun into a comparison.","cn":"表示「相对于」的固定说法把这个名词变成一种比较。"},{"en":"Diplomatic relations uses the plural because many lines run between two governments at once.","cn":"「外交关系」用复数，因为两个政府之间同时跑着许多条线。"},{"en":"Relation is the tie, relative is the person: one family, two readings of the same line.","cn":"relation 是那根联结，relative 是那个人：同一词族，同一根线的两种读法。"},{"en":"Bear no relation to means the expected line is missing altogether.","cn":"表示「与……毫无关系」的固定说法，指本该存在的线完全不见了。"}],"abstract":[{"en":"Picture a line with arrowheads at both ends: it can be read from either side.","cn":"想象一条两端都带箭头的线：从哪一头都能读。"},{"en":"The same line can also carry a report back, which is why the word once meant a narrative.","cn":"同一条线还能把报告带回来，所以这个词曾经表示叙述。"},{"en":"Squeeze the line into mathematics and it becomes a set of ordered pairs.","cn":"把这条线压进数学里，它就变成一组有序对。"}]},"examples":[{"en":"There is no simple relation between price and quality.","cn":"价格与质量之间并没有简单的关系。"},{"en":"She is a distant relation on my mother's side.","cn":"她是我母亲那边的远亲。"},{"en":"In relation to last year, sales have doubled.","cn":"与去年相比，销售额翻了一倍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞雷申」听起来像「惹累神」：一扯上关系就惹得人累神；把「累神」记住，也就记住了关系。","word":"relation"},"root":"源自拉丁 referre「带回、报告」的名词 relatio，经古法语 relation 进入英语；最古老的义项是「报告、叙述」，联系义由「关涉、指向」发展而来。ferre 更深来源一般认为是重构词根 *bher-「携带」。","sensesIntro":{"en":"Eight senses all use one line between two ends. The ends may be things, people, a storyteller and an event, governments, bodies, or numbers; the line itself may be a report, a tie, a comparison or a rule.","cn":"八个义项都在用两段之间的一根线。线的两端可以是事物、人、讲述者与事件、政府、身体或数字；线本身可以是报告、联结、比较或规则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line pointing from one thing to another, fixed by rule or experience.","cn":"核心意象：从一物指向另一物的一条线，由规则或经验固定。"},"chain":["ONE POINT","ANOTHER POINT","LINE DRAWN","REPORT CARRIED","LINK FIXED","READING CHOSEN"],"branches":[{"senses":"01","en":"THE BARE LINK: two things or facts, with no people involved.","cn":"最裸的联结：两件物或两件事实，不牵涉人。"},{"senses":"02 · 03","en":"THE HUMAN LINE: read from the far end it is a relative; read as a state it is kinship.","cn":"人的线：从远端读是亲戚，从状态读是亲属关系。"},{"senses":"04","en":"THE LINE AS A STORY: the oldest sense, a report carried back.","cn":"线作为故事：最古老的义项，一份带回来的报告。"},{"senses":"05 · 06","en":"MANY LINES OR CLOSEST LINE: whole dealings between groups, or the closest contact between two bodies.","cn":"多条线或最近的线：团体间的整套往来，或两具身体之间最紧的接触。"},{"senses":"07 · 08","en":"THE LINE MADE EXACT: a set of pairs in mathematics, and a fixed comparative phrase in grammar.","cn":"把线做得精确：数学里的一组有序对，以及语法里固定的比较短语。"}]},"affixes":{"intro":{"en":"Relation is one of the most productive stems in academic English: suffixes turn it into an adjective, a verb, an abstract noun and a statistical term.","cn":"relation 是学术英语里最能产的词干之一：各种后缀把它变成形容词、动词、抽象名词和统计术语。"},"latinIntro":{"en":"Behind the English family stands Latin referre 'to carry back' with its noun relatio and its participle relatus; the same verb also produced refer and transfer.","cn":"英语这一族的背后是拉丁 referre「带回」，连同它的名词 relatio 与分词 relatus；同一个动词还产出 refer 与 transfer。"},"items":[{"word":"relation","structure":"relat- (carried back) + -ion (noun suffix)","meaning":"a connection; a report","meaningCN":"联系；报告","example":"The relation between the two findings is still unclear.","exampleCN":"这两项发现之间的联系仍不清楚。"},{"word":"relational","structure":"relation + -al (adjective suffix)","meaning":"of or concerning relations","meaningCN":"关系上的；关于关系的","example":"The database stores data in a relational model.","exampleCN":"这个数据库用关系模型存储数据。"},{"word":"relate","structure":"re- (back) + -late (from relatus)","meaning":"to tell; to connect","meaningCN":"讲述；使有联系","example":"The two problems relate to the same cause.","exampleCN":"这两个问题源于同一个原因。"},{"word":"relative","structure":"relat- + -ive (having the quality of)","meaning":"comparative; connected by family","meaningCN":"相对的；有亲属关系的","example":"Relative humidity is measured against the maximum.","exampleCN":"相对湿度是相对于最大可能值来测量的。"},{"word":"relativity","structure":"relative + -ity (abstract noun suffix)","meaning":"the state of being relative; the physics theory","meaningCN":"相对性；相对论","example":"Relativity changed how physicists treat time.","exampleCN":"相对论改变了物理学家处理时间的方式。"},{"word":"refer","structure":"re- (back) + ferre (carry)","meaning":"to point or turn to something","meaningCN":"指向；提及；转诊","example":"The teacher referred us to the original paper.","exampleCN":"老师让我们去查那篇原始论文。"},{"word":"transfer","structure":"trans- (across) + ferre (carry)","meaning":"to carry across","meaningCN":"转移；搬运；转让","example":"He transferred the files to a new drive.","exampleCN":"他把文件转移到了新硬盘。"},{"word":"correlation","structure":"cor- (together) + relation","meaning":"a mutual relation measured between data sets","meaningCN":"数据组之间可测量的相互关联","example":"No correlation was found between the two scores.","exampleCN":"两项得分之间没有发现相关性。"},{"word":"reference","structure":"refer- (to point) + -ence (noun suffix)","meaning":"the act of pointing to a source","meaningCN":"提及；参考；推荐信","example":"The article ends with a list of references.","exampleCN":"文章末尾附有参考文献列表。"}],"latinEntries":[{"word":"referre","structure":"re- (back) + ferre (carry)","meaning":"to bring back; to report","meaningCN":"带回；报告"},{"word":"relatio","structure":"relat- + -io (action noun)","meaning":"a bringing back; a report; a reference","meaningCN":"带回；报告；关涉"},{"word":"relatus","structure":"past participle of referre","meaning":"carried back; reported","meaningCN":"被带回的；被报告的"}],"derivatives":[{"word":"relational","pos":"adj.","zh":"关系的（relation 加形容词后缀，限定到关系维度）"},{"word":"related","pos":"adj.","zh":"讲述；使有联系（表示「回」的前缀加拉丁语「携带」词干，把话或物带回原处）"},{"word":"relativity","pos":"n.","zh":"相对的；有亲属关系的（关系词干加形容词后缀，表示倾向于关联的）"},{"word":"correlation","pos":"n.","zh":"相对性（relative 加抽象名词后缀，指只能相对衡量的性质）"},{"word":"interrelation","pos":"n.","zh":"相关性（表示「共同」的前缀加 relation，指共同变动的关联）"}]}},{"word":"relational","ipa_uk":"/rɪˈleɪʃənəl/","ipa_us":"/rɪˈleɪʃənəl/","definition_zh":"关系的；关系层面的；关系型的；亲属关系的；关系模型的","definition_en":"of, relating to, or based on relations, especially the connections between people, things or data","core_image":"桌上摊着一堆小卡片，卡片本身并不起眼，真正决定整张图形状的，是卡片之间连出的那些线","scene":"工程师把订单、客户、库存拆成一张张独立的表，表与表之间只靠几个编号互相指认，任何一张表都不再重复保存别人的字段。In a relational database, each table stores one kind of record and points to the others through shared keys.","sceneCN":"这里 relational 指「数据库按关系模型来组织的」（第 2 个义项）；句意为：在关系型数据库中，每张表只存一类记录，并通过共享的键指向其他表。","pos":[{"tag":"adj.","zh":"关系的；关系层面的；关系型的；亲属关系的"}],"collocations":[{"phrase":"relational database","zh":"关系型数据库"},{"phrase":"relational model","zh":"关系模型"},{"phrase":"relational skills","zh":"处理关系的能力；人际技巧"},{"phrase":"relational network","zh":"关系网络"},{"phrase":"relational grammar","zh":"关系语法"},{"phrase":"relational contract","zh":"关系型合同（靠长期信任维系）"},{"phrase":"relational ontology","zh":"关系本体论"}],"forms":[{"label":"比较级","form":"more relational"},{"label":"最高级","form":"most relational"},{"label":"副词","form":"relationally"},{"label":"名词（关系性）","form":"relationality"}],"derivatives":[{"word":"relationally","pos":"adv.","zh":"在关系层面上（由 relational 加副词后缀，把动作限定到关系维度）"},{"word":"relationality","pos":"n.","zh":"关系性（由 relational 加抽象名词后缀，指由关系构成的性质）"},{"word":"relationalism","pos":"n.","zh":"关系主义（由 relational 加主义后缀，主张关系先于独立实体）"},{"word":"relationalist","pos":"n.","zh":"关系主义者（由 relational 加表人后缀，指持关系优先立场的人）"}],"senses":[{"no":"01","title":"Concerning connections in general","titleCN":"关于联系本身的","definition":"of or concerning the connections between people or things","definitionCN":"关于人或事物之间联系的","example":"The team looked at relational problems before blaming any single member.","exampleCN":"团队先检查关系层面的问题，再考虑该不该责怪某一个成员。","why":"The adjective takes the noun's line and turns it into a viewpoint: whatever is described is explained by the links rather than by the separate parts.","whyCN":"这个形容词把名词那根线变成一种视角：被描述的东西由「线」来解释，而不是由各自独立的部件来解释。"},{"no":"02","title":"Built as linked tables in computing","titleCN":"计算机里的关系型组织方式","definition":"in computing, organized so that data sit in tables linked by shared keys rather than in one rigid hierarchy","definitionCN":"计算机领域中按共享键连接的多张表来组织数据，而不是排成一套僵硬的层级","example":"A relational database lets one customer row serve many separate orders.","exampleCN":"关系型数据库让同一条客户记录服务于许多张订单。","why":"The abstract line becomes a key: instead of copying data, one table points at a row in another, and the link itself does the storage work.","whyCN":"抽象的线在这里变成「键」：一张表不去复制数据，而是指向另一张表里的一行，存储的重活由这条联结完成。"},{"no":"03","title":"Fixed by kinship or a network","titleCN":"由亲属或网络位置固定的","definition":"describing family ties or the position a person holds within a network of relatives","definitionCN":"描述亲属纽带，或一个人在亲属网络中所处的位置","example":"Relational ties in the village still shape who marries whom.","exampleCN":"村里的亲属关系网至今仍影响谁和谁结婚。","why":"Here the lines are drawn by birth and marriage, so the adjective describes a place in a family map rather than a feeling between two people.","whyCN":"这里的线由出生和婚姻画出，所以这个形容词描述的是家族地图上的位置，而不是两个人之间的感情。"},{"no":"04","title":"Expressing grammatical relations","titleCN":"语法上表达关系","definition":"in grammar, expressing or describing the relation between words or sentence elements","definitionCN":"语法学中表达或描述词与句子成分之间关系的","example":"Relational grammar studies how subjects and objects shift between clauses.","exampleCN":"关系语法研究主语和宾语如何在从句之间转换。","why":"Grammar turns the line into syntax: a word or a rule marks which element stands in what relation to the verb.","whyCN":"语法把线变成句法：某个词或某条规则标出哪个成分与动词处于什么关系。"},{"no":"05","title":"Identity produced by relations","titleCN":"由关系构成的身份","definition":"in philosophy and sociology, describing identity or meaning as produced by relations rather than by isolated entities","definitionCN":"哲学与社会学中，认为身份或意义由关系而非孤立实体产生","example":"A relational view of the self holds that we become who we are through others.","exampleCN":"关系性的自我观认为，我们是通过他人而成为自己的。","why":"If the line comes first, an entity is only a knot where several lines meet; identity is a position, not a substance.","whyCN":"如果线先于实体，那么一个实体只是多条线交汇的结；身份是一个位置，而不是一种实体。"},{"no":"06","title":"Belonging to the space between people","titleCN":"存在于人与人之间的心理层面","definition":"in psychology, describing needs, patterns or injuries that exist between people rather than inside one mind","definitionCN":"心理学中描述存在于人与人之间、而非单个人内心的需求、模式或创伤","example":"The therapist focused on relational trauma rather than on isolated symptoms.","exampleCN":"治疗师关注的是关系性创伤，而不是孤立的症状。","why":"The consulting room moves the unit of analysis from one head to the space between two people, so the adjective marks what belongs to that space.","whyCN":"诊室把分析单位从一个脑袋移到两个人之间的空间；这个形容词标记的正是属于那个空间的东西。"},{"no":"07","title":"Sustained by trust in long-term contracts","titleCN":"长期合同中靠信任维系的","definition":"in law and business, describing a long-term agreement sustained by trust and repeated dealing rather than by written terms alone","definitionCN":"法律与商业中，指长期协议靠信任与反复往来维系，而不只靠书面条款","example":"A relational contract relies on shared expectations, not only on clauses.","exampleCN":"关系型合同依靠双方的共同预期，而不只是条款。","why":"When a contract lasts for years, no document can foresee every case; the working line between the parties fills the gaps, and the adjective names that reliance.","whyCN":"合同一签多年，没有哪份文件能预见所有情况；双方之间那条工作中的线来填补空白，这个形容词命名的就是这种倚赖。"},{"no":"08","title":"Comparing values in programming","titleCN":"编程中比较数值的","definition":"in programming, describing an operator that compares two values and returns true or false","definitionCN":"编程中描述比较两个值并返回真或假的运算符","example":"The relational operator tests whether two values are equal.","exampleCN":"关系运算符用来检验两个值是否相等。","why":"Comparison is the smallest possible relation: two values are placed on either side of a sign, and the result is a yes or no.","whyCN":"比较是最小的一种关系：两个值被放在符号两侧，结果只剩「是」或「否」。"}],"etymology":{"intro":{"en":"Relational is relation plus the Latin adjective ending -alis, which English took over as -al. The word simply means 'having to do with a relation', and its later technical senses narrow that general meaning.","cn":"relational 是 relation 加上拉丁形容词词尾。它的字面意思就是「与关系有关的」，后来的技术义只是把这个宽泛意思收窄。"},"items":[{"era":"LATIN REFERRE","en":"Referre, from re- 'back' plus ferre 'to carry', meant to carry or bring back and to report. Its noun relatio supplied the stem for the whole English family.","cn":"referre 由表示「回」的前缀加 ferre「携带」构成，意为带回、拿回、报告；它的名词 relatio 为整个英语词族提供了词干。"},{"era":"LATIN RELATIO","en":"Relatio named a bringing back, a report and, in later usage, a reference or respect in which one thing is viewed through another.","cn":"relatio 指带回、报告，后来也指「关涉、指向」——透过一物去看另一物。"},{"era":"LATIN -ALIS","en":"The suffix -alis formed adjectives meaning 'of the kind of, pertaining to'. English borrowed it as -al and has used it ever since to turn nouns into adjectives.","cn":"那个拉丁形容词后缀构成意为「属于……一类、与……有关」的形容词。英语借用后，不断用它把名词变成形容词。"},{"era":"ENGLISH RELATION + -AL","en":"Adding -al to relation produced an adjective meaning 'of or concerning relations'. The formation is transparent and generally dated to the seventeenth century.","cn":"relation 加形容词后缀构成形容词，意为「与关系有关的」。这个构造十分透明，一般认为是十七世纪的产物。"},{"era":"MODERN ENGLISH","en":"In the twentieth century the adjective acquired narrow technical uses: relational databases in computing, relational grammar in linguistics and relational contracts in law.","cn":"到二十世纪，这个形容词获得了几种狭窄的技术义：计算机中的关系型数据库、语言学中的关系语法、法律中的关系型合同。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of ferre is reconstructed as *bher- 'to carry, bear'. That root is a reconstructed form, and no attested source word can be demonstrated.","cn":"来源不确定：ferre 的更早来源被重构为 *bher-「携带、承载」。这个词根是重构形式，无法证明存在一个有文献记录的源词。"}]},"similar":{"note":{"en":"The first group holds forms that look close, including one word from an unrelated Latin verb; the second compares adjectives that also describe how things are connected.","cn":"第一组是外形接近的词，其中有一个来自完全无关的拉丁动词；第二组是比较同样描述「事物如何相连」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"relation","ipa":"/rɪˈleɪʃən/","tag":"base noun","definition":"The noun itself, not the adjective: it names a connection, while relational describes a view or a design based on connections.","definitionCN":"名词本身而非形容词：它命名一种联系，而 relational 描述一种以联系为基础的视角或设计。"},{"word":"relative","ipa":"/rɪˈleɪtɪv/","tag":"near form","definition":"Same Latin stem, different ending: it means comparative or connected by family, not 'concerning relations in general'.","definitionCN":"同一拉丁词干、不同词尾：表示「比较的」或「有亲属关系的」，而不是「关于一般关系的」。"},{"word":"relativistic","ipa":"/ˌrelətɪˈvɪstɪk/","tag":"physics term","definition":"Belonging to relativity in physics. It looks longer and more technical, but it does not mean relational.","definitionCN":"属于物理学中的相对论。它看起来更长更技术化，但并不表示「关系的」。"},{"word":"relevant","ipa":"/ˈreləvənt/","tag":"not related","definition":"Relevant means connected to the matter at hand, but it comes from Latin relevare 'to lift up', not from referre; the two are not related.","definitionCN":"relevant 指与当前事情有关，但它来自拉丁 relevare「抬起」，并非出自 referre；两者没有词源关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"related","ipa":"/rɪˈleɪtɪd/","tag":"state, not viewpoint","definition":"It says that two things are connected; relational says that something is explained or organized by connections.","definitionCN":"它说明两件事已被连接；relational 则说明某事由联系来解释或组织。"},{"word":"comparative","ipa":"/kəmˈpærətɪv/","tag":"judged against","definition":"It measures one thing against another; relational does not require a measurement, only a link.","definitionCN":"它把一物放到另一物旁边衡量；relational 不要求测量，只要求联结。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"parts, not links","definition":"It concerns the arrangement of parts inside a whole; relational concerns the lines between parts.","definitionCN":"它关注整体内部部件如何排列；relational 关注部件之间的连线。"},{"word":"interpersonal","ipa":"/ˌɪntəˈpɜːsənəl/","tag":"people only","definition":"It is limited to relations between people; relational also covers data, grammar, law and machines.","definitionCN":"它只限人与人之间的关系；relational 还覆盖数据、语法、法律与机器。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"relation plus -al: the suffix turns the noun into an adjective of viewpoint, as in personal, natural and cultural.","cn":"relation 加形容词后缀：这个词尾把名词变成表示视角的形容词，personal、natural、cultural 都是同样的构造。"},{"en":"Relational database is the phrase most learners meet first: tables joined by keys instead of copied data.","cn":"「关系型数据库」是学习者最先遇到的搭配：用键把表连起来，而不是复制数据。"},{"en":"Relational skills appears in job ads, where the ability to handle people matters as much as technique.","cn":"「关系技能」常出现在招聘广告里，指处理人际关系的能力，其重要性不亚于技术。"},{"en":"The adverb relationally marks the level being discussed: not what a thing is, but where it stands.","cn":"副词 relationally 标出讨论的层次：不是东西本身是什么，而是它处在什么位置。"},{"en":"Relationality is the noun for the quality of being made of relations, common in sociology and philosophy.","cn":"relationality 是名词，指「由关系构成」这一性质，在社会学与哲学里很常见。"}],"abstract":[{"en":"Picture a map with no roads drawn, only dots; adding the lines is what turns dots into a system.","cn":"想象一张只画了点、没画路的地图；补上连线，点才变成系统。"},{"en":"The same shift applies to people, tables and clauses: the unit is the link, not the node.","cn":"同一种转换也适用于人、数据表和句子成分：单位是连线，而不是节点。"},{"en":"So relational always asks a second question: not 'what is it', but 'what is it joined to'.","cn":"所以 relational 总会多问一句：不是「它是什么」，而是「它连着什么」。"}]},"examples":[{"en":"Relational problems in the team were ignored for months.","cn":"团队里关系层面的问题被忽视了好几个月。"},{"en":"The company moved its records into a relational database last year.","cn":"公司去年把档案迁入了一个关系型数据库。"},{"en":"Relational grammar treats the subject as a grammatical relation rather than a fixed position.","cn":"关系语法把主语看作一种语法关系，而不是一个固定位置。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞雷申诺」听起来像「累神咯」：凡事都讲关系，人就累神咯；记住「累神咯」，就记住「关系的」。","word":"relational"},"root":"由 relation 加拉丁形容词词尾（意为「与……有关」）构成，字面义「与关系有关的」。relation 又可追溯到拉丁 referre「带回、报告」，ferre 的更早来源一般认为是重构词根，意为「携带」，属重构形式。","sensesIntro":{"en":"Eight senses share one move: look at the lines instead of the parts. The lines may run between people, tables, relatives, sentence elements, selves, minds, contracting firms or two values in code.","cn":"八个义项共享同一个动作：看线，而不是看部件。线可以跑在人与人、数据表与表、亲属、句子成分、自我、心智、签约公司或代码中的两个值之间。"},"semanticMap":{"core":{"en":"CORE IMAGE: the link matters more than the node; shape comes from what is joined.","cn":"核心意象：连线比节点更重要；形状来自「什么和什么连在一起」。"},"chain":["SEPARATE PARTS","LINES DRAWN","PATTERN APPEARS","VIEW FROM THE LINK","DOMAIN NARROWED","POSITION NOT SUBSTANCE"],"branches":[{"senses":"01","en":"THE GENERAL VIEW: explain a situation by its connections rather than by one guilty part.","cn":"总的视角：用联系解释局面，而不是找出一个该负责的部件。"},{"senses":"02 · 08","en":"COMPUTING NARROWS IT TWICE: tables joined by keys, and operators that compare two values.","cn":"计算机把它收窄两次：用键连接的表，以及比较两个值的运算符。"},{"senses":"03","en":"KINSHIP: the line is drawn by birth and marriage before anyone feels anything.","cn":"亲属：线在任何人产生感情之前，就由出生与婚姻画好了。"},{"senses":"04","en":"GRAMMAR: the line becomes syntax, marking which element stands in what relation to the verb.","cn":"语法：线变成句法，标出哪个成分与动词处于什么关系。"},{"senses":"05 · 06 · 07","en":"THREE DISCIPLINES MOVE THE UNIT: the self, the therapeutic space and the long contract are all defined by relations.","cn":"三个学科都换了单位：自我、治疗空间与长期合同，都由关系来定义。"}]},"affixes":{"intro":{"en":"Relational is a textbook suffix formation: a noun of relation plus -al, and the resulting adjective keeps feeding new technical phrases.","cn":"relational 是教科书式的后缀构词：一个表示关系的名词加形容词后缀，得到的形容词又不断喂养新的技术短语。"},"latinIntro":{"en":"The stem belongs to Latin referre and its noun relatio, while the ending -alis was the ordinary Latin way to make an adjective of belonging.","cn":"词干属于拉丁 referre 及其名词 relatio；那个拉丁形容词词尾则是拉丁语制造「所属」形容词的常规手段。"},"items":[{"word":"relation","structure":"relat- (carried back) + -ion (noun suffix)","meaning":"a connection; a report","meaningCN":"联系；报告","example":"The relation between the variables is weak.","exampleCN":"这些变量之间的联系很弱。"},{"word":"relational","structure":"relation + -al (adjective suffix)","meaning":"of or concerning relations","meaningCN":"关系上的；关于关系的","example":"Relational design avoids copying the same data twice.","exampleCN":"关系型设计避免把同一份数据存两遍。"},{"word":"relate","structure":"re- (back) + -late (from relatus)","meaning":"to tell; to connect","meaningCN":"讲述；使有联系","example":"The two cases relate in an unexpected way.","exampleCN":"这两个案例以一种意想不到的方式相关联。"},{"word":"relative","structure":"relat- + -ive (having the quality of)","meaning":"comparative; connected by family","meaningCN":"相对的；有亲属关系的","example":"The advantage is only relative.","exampleCN":"这个优势只是相对的。"},{"word":"relativity","structure":"relative + -ity (abstract noun)","meaning":"the quality of being relative","meaningCN":"相对性；相对论","example":"Relativity is taught in the final year.","exampleCN":"相对论在最后一年讲授。"},{"word":"refer","structure":"re- (back) + ferre (carry)","meaning":"to point back to something","meaningCN":"指向；提及","example":"The symbol refers to the previous chapter.","exampleCN":"这个符号指向前面的一章。"},{"word":"correlate","structure":"cor- (together) + relate (connect)","meaning":"to change together in a measurable way","meaningCN":"（两个变量）共同变化；使相互关联","example":"The two measures correlate strongly.","exampleCN":"这两项指标高度相关。"},{"word":"transfer","structure":"trans- (across) + ferre (carry)","meaning":"to carry across","meaningCN":"转移；搬运","example":"The data was transferred overnight.","exampleCN":"数据在夜间被转移了。"}],"latinEntries":[{"word":"referre","structure":"re- (back) + ferre (carry)","meaning":"to bring back; to report","meaningCN":"带回；报告"},{"word":"relatio","structure":"relat- + -io (action noun)","meaning":"a bringing back; a report; a reference","meaningCN":"带回；报告；关涉"},{"word":"relatus","structure":"past participle of referre","meaning":"carried back; reported","meaningCN":"被带回的；被报告的"}],"derivatives":[{"word":"relationally","pos":"adv.","zh":"在关系层面上（relational 加副词后缀，把动作限定到关系维度）"},{"word":"relationality","pos":"n.","zh":"关系性（relational 加抽象名词后缀，指由关系构成的性质）"},{"word":"relationalism","pos":"n.","zh":"关系主义（relational 加主义后缀，主张关系先于实体）"},{"word":"relationalist","pos":"n.","zh":"关系主义者（relational 加表人后缀，指持关系优先立场的人）"}]}},{"word":"interpersonal","ipa_uk":"/ˌɪntəˈpɜːsənəl/","ipa_us":"/ˌɪntərˈpɜːrsənəl/","definition_zh":"人际的；人与人之间的；人际交往的","definition_en":"existing or happening between people, or concerning the way people deal with one another","core_image":"两个人隔着一张小桌相对而坐，桌上没有文件，只有彼此的语气、眼神和说话之间的停顿","scene":"新主管上任第一周没有急着改流程，而是把每个人的名字、班次和最近家里的难处记进本子，开会前先问一句周末过得怎样。New managers are often advised to invest in interpersonal skills before they try to change any process.","sceneCN":"这里 interpersonal 指「与人打交道的能力」（第 2 个义项）；句意为：人们常建议新主管先投入人际技能，然后再去改动任何流程。","pos":[{"tag":"adj.","zh":"人际的；人与人之间的；人际交往的"}],"collocations":[{"phrase":"interpersonal skills","zh":"人际交往技能"},{"phrase":"interpersonal relationships","zh":"人际关系"},{"phrase":"interpersonal communication","zh":"人际沟通"},{"phrase":"interpersonal conflict","zh":"人际冲突"},{"phrase":"interpersonal attraction","zh":"人际吸引"},{"phrase":"interpersonal distance","zh":"人际距离"},{"phrase":"interpersonal comparison","zh":"人与人之间的比较"}],"forms":[{"label":"比较级","form":"more interpersonal"},{"label":"最高级","form":"most interpersonal"},{"label":"副词","form":"interpersonally"}],"derivatives":[{"word":"interpersonally","pos":"adv.","zh":"在人际层面上（由 interpersonal 加副词后缀，把行为限定到人与人之间）"},{"word":"impersonal","pos":"adj.","zh":"非个人的；没有人情味的（由否定前缀加 personal，把个人因素抽走）"},{"word":"impersonality","pos":"n.","zh":"非个人性；冷淡（由否定前缀加 personal 再加名词后缀，指抽掉个人情感后的状态）"},{"word":"personalization","pos":"n.","zh":"个性化（由 personal 加表示过程的名词后缀，把公共的东西调整到某个人身上）"}],"senses":[{"no":"01","title":"Happening between people","titleCN":"发生在人与人之间的","definition":"existing or taking place between two or more people rather than inside one person","definitionCN":"存在于或发生在两个或更多个人之间，而不是单个人内部","example":"The office layout changed the whole interpersonal atmosphere.","exampleCN":"办公室的布局改变了整个人际氛围。","why":"The prefix inter- means 'between', so the adjective marks whatever sits in the space that two people share rather than in either head alone.","whyCN":"那个前缀意为「在……之间」，所以这个形容词标记的是两人共享的那片空间里的东西，而不是任何一个人脑中的东西。"},{"no":"02","title":"Skill in handling people","titleCN":"与人打交道的能力","definition":"describing the ability to read, respect and manage other people in everyday dealings","definitionCN":"描述在日常交往中读懂、尊重并处理好他人的能力","example":"Her interpersonal skills made a difficult client stay with the firm.","exampleCN":"她的人际技巧让一个难缠的客户留在了公司。","why":"Once the space between people is recognised, it can be worked on like any other skill: listening, turn-taking and repair after a mistake.","whyCN":"一旦承认两人之间那片空间存在，它就能像别的技能一样被练习：倾听、轮流说话、出错后修补。"},{"no":"03","title":"Friction between people","titleCN":"人与人之间的摩擦","definition":"describing conflict, tension or misunderstanding that arises between people","definitionCN":"描述人与人之间产生的冲突、紧张或误解","example":"The project failed not from bad planning but from interpersonal conflict.","exampleCN":"这个项目失败的原因不是计划糟糕，而是人际冲突。","why":"The same shared space can hold irritation as well as trust; the adjective simply locates the friction between the parties instead of inside one of them.","whyCN":"同一片共享空间既能装信任，也能装恼火；这个形容词只是把摩擦定位在双方之间，而不是某一个人内部。"},{"no":"04","title":"Communication between people","titleCN":"人与人之间的沟通","definition":"describing the exchange of messages, meaning or feeling between people","definitionCN":"描述人与人之间信息、意义或情感的交换","example":"Most of the misunderstanding came from interpersonal communication, not from the data.","exampleCN":"大部分误解来自人际沟通，而不是数据本身。","why":"A message must be sent and received; when both ends are people, the channel between them is the thing the adjective describes.","whyCN":"信息要被送出也要被接收；当两端都是人时，这个形容词描述的就是两人之间那条通道。"},{"no":"05","title":"Attraction and closeness","titleCN":"人际吸引与亲近","definition":"describing the pull of liking, trust or romantic interest that draws people together","definitionCN":"描述把人们拉到一起的喜欢、信任或恋爱兴趣","example":"Interpersonal attraction grows when people find their views confirmed.","exampleCN":"当人们发现对方印证了自己的观点时，人际吸引会增强。","why":"The line between two people has a direction and a strength; attraction is the force that shortens it, and the adjective names the field in which that force operates.","whyCN":"两人之间那条线有方向也有强度；吸引就是缩短这条线的力，这个形容词命名的是这股力起作用的场域。"},{"no":"06","title":"Distance and personal space","titleCN":"人际距离与个人空间","definition":"describing how close people stand or sit in relation to one another and how that spacing is read","definitionCN":"描述人们彼此站得多近、坐得多近，以及这种间距如何被解读","example":"Interpersonal distance shrinks when two people share a secret.","exampleCN":"当两个人共享一个秘密时，人际距离会缩短。","why":"If closeness is a line, it can be measured in centimetres; the adjective applies the same idea to physical spacing and the comfort it signals.","whyCN":"如果亲近是一条线，它就能用厘米来量；这个形容词把同一个观念用到身体间距以及间距所传达的舒适感上。"},{"no":"07","title":"A psychological and therapeutic frame","titleCN":"心理学与治疗中的框架","definition":"in psychology, describing a theory or therapy that treats relations with other people as central to mental life","definitionCN":"心理学中描述把与他人的关系视为心理生活核心的理论或疗法","example":"Interpersonal therapy treats depression by working on how the patient handles other people.","exampleCN":"人际疗法通过处理患者与他人的相处方式来治疗抑郁。","why":"A clinical school can take the between-person space as its unit and build a whole method around repairing it, which turns the adjective into a label for that method.","whyCN":"一个临床学派可以把「人与人之间」当作单位，并围绕修复它建立整套方法；这个形容词于是成了那套方法的标签。"},{"no":"08","title":"Comparison across persons in economics","titleCN":"经济学中跨人的比较","definition":"in economics and philosophy, describing the comparison of welfare, utility or well-being between different people","definitionCN":"经济学与哲学中描述不同人之间福利、效用或幸福感的比较","example":"Policy debates often depend on interpersonal comparisons of well-being.","exampleCN":"政策争论常常取决于对人们幸福感的跨人比较。","why":"Once well-being is put on one scale, the line between two people becomes a comparison of two readings, and the adjective marks that move across separate persons.","whyCN":"一旦把幸福感放到同一把尺子上，两人之间的线就变成两个读数的比较；这个形容词标记的正是跨越不同个体的那一步。"}],"etymology":{"intro":{"en":"Interpersonal is a modern English compound of inter- 'between' and personal. The prefix is Latin, and personal goes back through Latin personalis to persona, a word whose deeper origin is uncertain.","cn":"interpersonal 是近代英语的复合词：表示「在……之间」的前缀加 personal。前缀来自拉丁语，personal 则经拉丁 personalis 追溯到 persona，而 persona 的更早来源不确定。"},"items":[{"era":"LATIN INTER","en":"Inter was a Latin preposition and prefix meaning 'between, among, during'. English keeps it in international, interact and interpersonal.","cn":"inter 是拉丁语介词兼前缀，意为「在……之间、在……之中、在……期间」。英语把它保留在 international、interact 与 interpersonal 里。"},{"era":"LATIN PERSONA, SOURCE UNCERTAIN","en":"Persona first meant a mask worn by an actor and then the role or character played, later a human being. Source uncertain: an Etruscan origin has been proposed, but no single source can be demonstrated.","cn":"persona 最初指演员戴的面具，随后指所扮演的角色，再后来指人。来源不确定：有伊特鲁里亚来源的假说，但无法证明唯一来源。"},{"era":"LATIN PERSONALIS","en":"The adjective personalis meant 'of a person, belonging to a person'. It passed into Old French and then into English as personal.","cn":"形容词 personalis 意为「人的、属于个人的」，经古法语进入英语，成为 personal。"},{"era":"ENGLISH INTER- + PERSONAL","en":"English joined the Latin prefix to the borrowed adjective to make interpersonal, generally dated to the nineteenth century and meaning simply 'between persons'.","cn":"英语把拉丁前缀加到借来的形容词上，构成 interpersonal，一般认为是十九世纪的产物，字面意思就是「人与人之间的」。"},{"era":"MODERN ENGLISH","en":"In the twentieth century psychology and management gave the word its familiar phrases: interpersonal relations, interpersonal skills and interpersonal therapy.","cn":"到二十世纪，心理学与管理学给了这个词一批常见搭配：人际关系、人际技能、人际疗法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the chain beyond persona is debated. Competing proposals exist, and none is generally accepted as proven; the word is best treated as having no demonstrated deeper root.","cn":"来源不确定：persona 再往前的链条不确定。存在几种互相竞争的假说，没有一种被普遍接受为已证明；最好把这个词当作没有可证实的更深词根。"}]},"similar":{"note":{"en":"The first group separates forms built on the same root with different prefixes or endings; the second compares words that also concern contact between people but from another angle.","cn":"第一组分辨同一词根配不同前缀或词尾的形式；第二组比较同样涉及人与人接触、但角度不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impersonal","ipa":"/ɪmˈpɜːsənəl/","tag":"related, opposite","definition":"Same personal base with a negative prefix: it means without personal warmth, the reverse of what interpersonal usually praises.","definitionCN":"否定前缀加 personal：把个人因素抽走，指不带人情味的制度或态度。"},{"word":"intrapersonal","ipa":"/ˌɪntrəˈpɜːsənəl/","tag":"different prefix","definition":"intra- means 'within', so this word is about what happens inside one person, the opposite side of the same boundary.","definitionCN":"表示「在内」的前缀意为「在……之内」，所以这个词指发生在一个人内部的事，是同一道边界的另一侧。"},{"word":"personal","ipa":"/pəˈsɜːnəl/","tag":"base adjective","definition":"The base word: it means belonging to one person, while interpersonal requires at least two.","definitionCN":"基础形容词：意为属于某一个人；而 interpersonal 至少需要两个人。"},{"word":"personable","ipa":"/ˈpɜːsənəbl/","tag":"same root, different suffix","definition":"Built on person with -able: it means pleasant and easy to like, not 'between people'.","definitionCN":"由 person 加表示「能……」的形容词后缀构成：意为讨人喜欢、容易相处，而不是「人与人之间的」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"group level","definition":"It concerns society, groups and public life; interpersonal is limited to the contact between particular people.","definitionCN":"它涉及社会、群体与公共生活；interpersonal 则限于具体个人之间的接触。"},{"word":"communicative","ipa":"/kəˈmjuːnɪkətɪv/","tag":"willing to talk","definition":"It describes a person's willingness or ability to convey messages; interpersonal describes the space or skill of dealing with people.","definitionCN":"它描述一个人愿意或能够传达信息；interpersonal 描述的是与人相处的空间或能力。"},{"word":"relational","ipa":"/rɪˈleɪʃənəl/","tag":"any link","definition":"It applies to any kind of link, including data and grammar; interpersonal is the human-only case.","definitionCN":"它适用于任何联结，包括数据与语法；interpersonal 只是其中专指人的那一种。"},{"word":"interactive","ipa":"/ˌɪntərˈæktɪv/","tag":"two-way action","definition":"It stresses action and response between parties, often with machines; interpersonal stresses that both parties are people.","definitionCN":"它强调双方的动作与回应，常涉及机器；interpersonal 强调双方都是人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"inter- means 'between' and personal means 'of a person': the compound literally places something between persons.","cn":"表示「在……之间」的前缀加 personal「个人的」：这个复合词字面上把东西放在人与人之间。"},{"en":"Impersonal is its mirror image: im- negates personal, so the warmth is removed.","cn":"impersonal 是它的镜像：否定前缀否定 personal，人情味被抽走。"},{"en":"Intrapersonal uses intra- 'within': the same boundary, but looking inward instead of across.","cn":"intrapersonal 用表示「在内」的前缀：同一道边界，只是向内看而不是向对面看。"},{"en":"Interpersonal skills is the phrase in job advertisements, where technique alone is not enough.","cn":"「人际技能」是招聘广告里的常见说法，光有技术还不够。"},{"en":"Interpersonal conflict is the phrase used when the disagreement belongs to the relationship, not to the task.","cn":"「人际冲突」用于分歧属于关系本身、而不属于任务的时候。"}],"abstract":[{"en":"Picture a table with two chairs: whatever happens in the air above that table is interpersonal.","cn":"想象一张桌子配两把椅子：桌子上方那片空气里发生的事，就是人际的。"},{"en":"The air can carry trust, irritation, a joke or a silence; the adjective does not choose which.","cn":"那片空气能承载信任、恼火、玩笑或沉默；这个形容词并不挑选是哪一种。"},{"en":"Move one chair away and the distance itself becomes a message.","cn":"把一把椅子挪远，距离本身就成了一条信息。"}]},"examples":[{"en":"Interpersonal relationships at work affect how quickly problems are reported.","cn":"工作中的人际关系会影响问题被多快上报。"},{"en":"The training focused on interpersonal communication rather than on software.","cn":"这次培训侧重人际沟通，而不是软件操作。"},{"en":"Interpersonal conflict between the two leads delayed the whole project.","cn":"两位负责人之间的人际冲突拖慢了整个项目。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因特怕森诺」听起来像「因他怕生」：因为他一见生人就怕，才更需要练人际交往；记住「怕生」，就记住「人际的」。","word":"interpersonal"},"root":"由拉丁前缀（意为「在……之间」）加 personal「个人的」构成；personal 经拉丁 personalis 来自 persona「面具、角色」，persona 更深来源不确定，有伊特鲁里亚来源假说，不能定论。","sensesIntro":{"en":"Eight senses all sit in the space between two people: the space itself, the skill of working in it, its friction, its messages, its pull, its measured width, its clinical method and its use as a scale for comparing welfare.","cn":"八个义项都落在两个人之间的那片空间里：空间本身、在其中运作的技能、其中的摩擦、其中的信息、其中的拉力、被量出的宽度、围绕它建立的临床方法，以及把它当作比较福利的尺子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shared space between two people, filled by tone, look and pause.","cn":"核心意象：两个人之间共享的一片空间，被语气、眼神与停顿填满。"},"chain":["TWO PERSONS","SPACE BETWEEN","CONTACT MADE","TENSION OR TRUST","SKILL LEARNED","DISCIPLINE NAMED"],"branches":[{"senses":"01","en":"THE SPACE ITSELF: whatever happens between people rather than inside one of them.","cn":"空间本身：发生在人与人之间、而非某人内部的一切。"},{"senses":"02 · 04","en":"WORKING IN THE SPACE: the skill of handling people and the messages that pass between them.","cn":"在这片空间里作业：处理他人的技能，以及在两人之间传递的信息。"},{"senses":"03","en":"WHEN THE SPACE HEATS UP: friction and misunderstanding located between the parties.","cn":"空间升温时：摩擦与误解被定位在双方之间。"},{"senses":"05 · 06","en":"FORCE AND MEASURE: attraction shortens the space, distance reports how wide it is.","cn":"拉力与量度：吸引把空间缩短，距离报告它有多宽。"},{"senses":"07 · 08","en":"FROM SPACE TO METHOD AND SCALE: a therapy built on it, and an economic comparison across persons.","cn":"从空间到方法与尺子：围绕它建立的疗法，以及跨人的经济比较。"}]},"affixes":{"intro":{"en":"Interpersonal can be read morpheme by morpheme: a Latin prefix of position, a root for person, an adjective ending, and a compound that puts them together.","cn":"interpersonal 可以逐个语素读出来：一个表示位置关系的拉丁前缀、一个表示人的词根、一个形容词词尾，以及把它们拼在一起的复合过程。"},"latinIntro":{"en":"Latin inter 'between' and persona 'mask, role' combined through the adjective personalis; English then prefixed the borrowed adjective to make the modern word.","cn":"拉丁语 inter「在……之间」与 persona「面具、角色」经形容词 personalis 结合；英语再给借来的形容词加上前缀，构成现代这个词。"},"items":[{"word":"inter-","structure":"Latin prefix inter- (between, among)","meaning":"between; among","meaningCN":"在……之间；在……之中","example":"The prefix marks a position between two sides.","exampleCN":"这个前缀标出位于两侧之间的位置。"},{"word":"person","structure":"person (root from Latin persona, mask or role)","meaning":"an individual human being","meaningCN":"一个人；个体","example":"The room held only one person.","exampleCN":"房间里只有一个人。"},{"word":"personal","structure":"person + -al (adjective suffix)","meaning":"belonging to one person","meaningCN":"属于个人的","example":"She kept a personal record of the meetings.","exampleCN":"她为这些会议保留了一份私人记录。"},{"word":"interpersonal","structure":"inter- (between) + personal","meaning":"existing between people","meaningCN":"存在于人与人之间的","example":"The job requires strong interpersonal judgement.","exampleCN":"这份工作需要很强的人际判断力。"},{"word":"impersonate","structure":"im- (in) + person + -ate (verb suffix)","meaning":"to play the role of another person","meaningCN":"扮演他人；冒充","example":"He was arrested for impersonating an officer.","exampleCN":"他因冒充官员而被捕。"},{"word":"personality","structure":"personal + -ity (abstract noun)","meaning":"the enduring pattern of a person's character","meaningCN":"性格；人格","example":"Her personality suits front-line work.","exampleCN":"她的性格适合做一线工作。"},{"word":"personify","structure":"person + -ify (to make)","meaning":"to treat a thing as a person, or to be a perfect example","meaningCN":"把事物拟人化；是……的化身","example":"The old tree personified patience.","exampleCN":"那棵老树仿佛是耐心的化身。"},{"word":"personalization","structure":"personal + -ization (process noun)","meaning":"the act of adapting something to one person","meaningCN":"个性化；使适合某人","example":"Personalization made the service feel less anonymous.","exampleCN":"个性化让这项服务少了些冷冰冰的感觉。"}],"latinEntries":[{"word":"inter","structure":"Latin preposition and prefix","meaning":"between, among","meaningCN":"在……之间、在……之中"},{"word":"persona","structure":"Latin noun of uncertain deeper origin","meaning":"a mask; a role; a person","meaningCN":"面具；角色；人（更深来源不确定）"},{"word":"personalis","structure":"persona + -alis (adjective suffix)","meaning":"of a person; belonging to a person","meaningCN":"人的；属于个人的"}],"derivatives":[{"word":"interpersonally","pos":"adv.","zh":"在人际层面上（interpersonal 加副词后缀，把行为限定到两人之间）"},{"word":"impersonal","pos":"adj.","zh":"非个人的（否定前缀加 personal，抽掉个人温度）"},{"word":"impersonality","pos":"n.","zh":"非个人性（否定前缀加 personal 再加名词后缀，指冷淡无人的状态）"},{"word":"personalization","pos":"n.","zh":"个性化（personal 加表示过程的名词后缀，把公共事物调到某个人身上）"}]}},{"word":"communicative","ipa_uk":"/kəˈmjuːnɪkətɪv/","ipa_us":"/kəˈmjuːnəkətɪv/","definition_zh":"乐于交流的；健谈的；传达信息的；交际的；交流的","definition_en":"willing to communicate, or relating to the conveying of information and meaning between people","core_image":"一个人把手里的小纸条递出去，对方接住、点头，再把回应递回来，信息在两人之间走完一个来回","scene":"平时最沉默的同事在系统崩掉那天忽然站到白板前，一条条解释故障、分配任务，还主动问每个人听懂了没有。Normally quiet, she became unusually communicative once the system failed and everyone needed straight answers.","sceneCN":"这里 communicative 指「愿意开口交流的」（第 1 个义项）；句意为：她平时很安静，但系统一出故障、人人都需要明确答复时，她变得异常愿意沟通。","pos":[{"tag":"adj.","zh":"乐于交流的；健谈的；传达信息的；交际的"}],"collocations":[{"phrase":"communicative competence","zh":"交际能力（语言学术语）"},{"phrase":"communicative approach","zh":"交际教学法"},{"phrase":"communicative function","zh":"交际功能"},{"phrase":"communicative strategy","zh":"交际策略"},{"phrase":"communicative action","zh":"交往行为（社会理论术语）"},{"phrase":"communicative silence","zh":"有含义的沉默"},{"phrase":"communicative gesture","zh":"示意动作"}],"forms":[{"label":"比较级","form":"more communicative"},{"label":"最高级","form":"most communicative"},{"label":"副词","form":"communicatively"},{"label":"名词（愿意交流的特质）","form":"communicativeness"}],"derivatives":[{"word":"communicatively","pos":"adv.","zh":"在交际层面上（由 communicative 加副词后缀，把动作限定为传达信息）"},{"word":"communicativeness","pos":"n.","zh":"乐于交流；表达力（由 communicative 加名词后缀，指愿意传达的特质）"},{"word":"communication","pos":"n.","zh":"交流；通信（由 communicate 加名词后缀，指传达这件事本身）"},{"word":"communicator","pos":"n.","zh":"传达者；善于沟通的人（由 communicate 加表人后缀，指发出信息的一方）"},{"word":"communicable","pos":"adj.","zh":"可传达的；可传染的（由 communicate 加表示「可被……」的形容词后缀，指能被传递出去）"}],"senses":[{"no":"01","title":"Willing to talk and share","titleCN":"愿意开口、愿意分享的","definition":"ready to speak, listen and give information rather than staying silent","definitionCN":"愿意说、愿意听、愿意提供信息，而不是保持沉默","example":"He is far more communicative in small meetings than in large ones.","exampleCN":"他在小会上比在大会上健谈得多。","why":"The core idea is making something common: a communicative person opens the channel and puts what is inside within reach of others.","whyCN":"核心观念是「使某物成为共同拥有的」：一个愿意交流的人会打开通道，把心里的东西放到别人够得着的地方。"},{"no":"02","title":"Carrying meaning without words","titleCN":"不用语言也能传达意思的","definition":"expressing meaning through a look, gesture, silence or tone rather than through words","definitionCN":"通过眼神、手势、沉默或语气而非文字来传达意思","example":"Her communicative silence told the room more than a speech would have.","exampleCN":"她那有含义的沉默，比一场演讲更能让满屋人明白。","why":"If communication is the passing of meaning, words are only one carrier; a pause or a glance can carry the same load, so the adjective follows the meaning, not the medium.","whyCN":"如果交流是意义的传递，词语就只是其中一种载体；一个停顿或一瞥能承载同样的分量，所以这个形容词跟着意义走，而不跟着媒介走。"},{"no":"03","title":"Relating to communication as a process","titleCN":"与交流过程有关的","definition":"concerning the act or process of exchanging information, messages or meaning","definitionCN":"关于信息、消息或意义交换这一行为或过程的","example":"The study maps the communicative process from sender to receiver.","exampleCN":"这项研究描绘了从发送者到接收者的整个交流过程。","why":"Once the channel itself becomes an object of study, the adjective simply labels anything that belongs to that process rather than to the people in it.","whyCN":"一旦通道本身成为研究对象，这个形容词就用来标记属于这个过程、而不属于其中某个人的东西。"},{"no":"04","title":"Competence in using language socially","titleCN":"语言使用中的交际能力","definition":"in linguistics, describing the ability to use language appropriately in real social situations, not only to form correct sentences","definitionCN":"语言学中描述在真实社交场合恰当使用语言的能力，而不只是造出语法正确的句子","example":"Communicative competence includes knowing when to stay silent.","exampleCN":"交际能力包括知道什么时候该保持沉默。","why":"Grammar proves only that a sentence is well formed; a speaker also needs to know whom to say it to, when and how, and that extra knowledge is what the adjective names.","whyCN":"语法只能证明句子造得对；说话者还得知道对谁说、什么时候说、怎么说，这份额外的知识正是这个形容词命名的东西。"},{"no":"05","title":"A teaching method built on use","titleCN":"以实际使用为基础的教学法","definition":"in language teaching, describing an approach that organizes lessons around real communication rather than around grammar drills","definitionCN":"语言教学中描述一种把课程围绕真实交流、而非语法操练来组织的方法","example":"The communicative approach asks students to order food before they analyse the tense.","exampleCN":"交际教学法让学生在分析时态之前先去点餐。","why":"If competence means using language socially, then practice should look social too: the classroom is rearranged around tasks, and the adjective becomes the name of that arrangement.","whyCN":"如果能力指的是在社会中使用语言，那么练习也该像社会交往：教室围绕任务重新安排，这个形容词就成了这种安排的名称。"},{"no":"06","title":"Signals exchanged by animals","titleCN":"动物交换的交流信号","definition":"in animal behaviour, describing signals, displays or calls that transfer information between animals","definitionCN":"动物行为学中描述在动物之间传递信息的信号、展示或叫声","example":"The bright tail is a communicative signal, not merely decoration.","exampleCN":"那条鲜艳的尾巴是一种交流信号，而不只是装饰。","why":"The same definition of passing information applies when neither party has words: colour, posture and sound become carriers, and the adjective needs no change.","whyCN":"当双方都没有词语时，「传递信息」这一定义照样适用：颜色、姿态和声音成为载体，这个形容词不必改动。"},{"no":"07","title":"Action aimed at mutual understanding","titleCN":"以相互理解为目标的交往行为","definition":"in social theory, describing action directed at reaching shared understanding rather than at winning or manipulating","definitionCN":"社会理论中描述以达成共同理解、而非以取胜或操纵为目标的行为","example":"Habermas separates communicative action from strategic bargaining.","exampleCN":"哈贝马斯把交往行为与策略性讨价还价区分开来。","why":"A theory can single out the kind of talk whose goal is agreement rather than victory; the adjective then marks the intention behind the act, not just its channel.","whyCN":"一种理论可以挑出以共识而非取胜为目标的谈话；这个形容词于是标记行为背后的意图，而不只是它的通道。"},{"no":"08","title":"A clinical label for communication disorders","titleCN":"交流障碍的临床标签","definition":"in medicine and education, describing conditions that impair a person's ability to send or receive messages","definitionCN":"医学与教育中描述损害一个人发送或接收信息能力的状况","example":"The clinic assesses communicative disorders in children after stroke or hearing loss.","exampleCN":"诊所评估儿童在中风或听力损失之后的交流障碍。","why":"When the channel breaks, the adjective moves from describing a skill to naming a deficit; the same word now labels what has gone wrong in the passing of meaning.","whyCN":"当通道损坏时，这个形容词从描述一种能力转为命名一种缺陷；同一个词现在标记的是意义传递中出错的地方。"}],"etymology":{"intro":{"en":"Communicative goes back to Latin communis 'common, shared', then to communicare 'to share, impart'. The English adjective adds -ive to communicate and first meant 'that may be shared'.","cn":"communicative 可追溯到拉丁 communis「共同的、共享的」，再到 communicare「分享、传达」。英语形容词是 communicate 加形容词后缀，最初意为「可以被分享的」。"},"items":[{"era":"LATIN COMMUNIS","en":"Communis meant 'common, shared, public'. It is usually analysed as com- 'together' plus munus 'service, duty, gift'; the deeper origin of munus is uncertain.","cn":"communis 意为「共同的、共享的、公共的」。通常把它分析为表示「共同」的前缀加 munus「义务、服务、礼物」；munus 的更早来源不确定。"},{"era":"LATIN COMMUNICARE","en":"Communicare meant 'to share, impart, make common', and later 'to communicate' in the modern sense. It is the verb behind the whole English family.","cn":"communicare 意为「分享、传达、使共同拥有」，后来才表示现代意义上的「交流」。它是整个英语词族背后的动词。"},{"era":"LATE LATIN COMMUNICATIVUS","en":"Late Latin is generally cited for an adjective communicativus meaning 'that may be shared'. English sources often derive the word from this form, with the ending -ive.","cn":"资料通常提到晚期拉丁形容词 communicativus，意为「可以被分享的」。英语词源资料常认为这个词由它加形容词词尾而来。"},{"era":"ENGLISH COMMUNICATE + -IVE","en":"English formed the adjective in the sixteenth century. Its earliest sense was passive, 'capable of being communicated or shared', not 'talkative'.","cn":"英语在十六世纪构成这个形容词。最早的义项是被动的「可以被传达或分享的」，而不是「健谈的」。"},{"era":"MODERN ENGLISH","en":"By the seventeenth century communicative could describe a person who readily shares thoughts. Twentieth-century linguistics added competence, approach and disorder as fixed partners.","cn":"到十七世纪，communicative 已可形容乐于分享想法的人。二十世纪的语言学又添上「交际能力」「交际教学法」与「交际障碍」等固定搭配。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the origin of munus is debated. Several competing proposals exist, none of them generally accepted as proved, so no single deeper root should be presented as fact.","cn":"munus 的来源不确定。存在几种互相竞争的假说，没有一种被普遍接受为已证明，因此不应把任何单一更深词根当作事实。"}]},"similar":{"note":{"en":"The first group separates forms from the same family and one word from a different Latin verb; the second compares adjectives about talking or showing meaning.","cn":"第一组分辨同族形式，以及一个来自不同拉丁动词的词；第二组比较表示「爱说话」或「能表达」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"communication","ipa":"/kəˌmjuːnɪˈkeɪʃən/","tag":"noun form","definition":"The noun for the process or a message; communicative is the adjective about willingness or meaning.","definitionCN":"指过程或消息的名词；communicative 则是关于意愿或传达的形容词。"},{"word":"communicable","ipa":"/kəˈmjuːnɪkəbl/","tag":"same verb, other suffix","definition":"It means able to be passed on, especially a disease; it is related but never means 'talkative'.","definitionCN":"意为可传递的，尤指疾病可传染；它同族，但从不表示「健谈的」。"},{"word":"commutative","ipa":"/kəˈmjuːtətɪv/","tag":"not related","definition":"It comes from Latin commutare 'to change, exchange', not from communicare, and describes an operation whose order does not matter.","definitionCN":"它来自拉丁 commutare「改变、交换」，并非出自 communicare，描述的是与顺序无关的运算。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"shared root, different noun","definition":"It shares the Latin root communis but names a group that holds things in common, not a person's willingness to talk.","definitionCN":"它共享拉丁词根 communis，但命名的是共同拥有某些东西的群体，而不是一个人是否愿意说话。"}]},{"heading":"NEAR MEANING","entries":[{"word":"talkative","ipa":"/ˈtɔːkətɪv/","tag":"talks a lot","definition":"It stresses the amount of speech; communicative stresses the willingness to share meaning, which may need only a few words.","definitionCN":"它强调说话的数量；communicative 强调愿意分享意义，也许只需几个字。"},{"word":"expressive","ipa":"/ɪkˈspresɪv/","tag":"shows feeling","definition":"It highlights visible feeling or artistry; communicative highlights the transfer of information to another mind.","definitionCN":"它突出可见的情感或艺术性；communicative 突出信息向另一颗心灵的传递。"},{"word":"outgoing","ipa":"/ˌaʊtˈɡəʊɪŋ/","tag":"socially forward","definition":"It describes a sociable temperament; a quiet person can still be communicative in the right situation.","definitionCN":"它描述外向的性情；一个安静的人在对的场合仍可能很愿意交流。"},{"word":"articulate","ipa":"/ɑːˈtɪkjələt/","tag":"clear in speech","definition":"It judges how clearly words are formed; communicative judges whether meaning actually reaches the other person.","definitionCN":"它评判词语组织得清不清楚；communicative 评判意义是否真的到达对方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"communis means 'common': to communicate is to make something common between two people.","cn":"communis 意为「共同的」：交流就是把某样东西在两人之间变成共同拥有的。"},{"en":"communicate plus -ive gives the adjective, just as act gives active and create gives creative.","cn":"communicate 加形容词后缀构成形容词，正如 act 构成 active、create 构成 creative。"},{"en":"Communicative competence is the linguistics phrase for knowing when and how to speak, not only how to form a sentence.","cn":"「交际能力」是语言学术语，指知道何时、如何说话，而不只是会造句。"},{"en":"Communicative silence shows that meaning can travel without sound.","cn":"「交际性沉默」说明意义可以不出声地传递。"},{"en":"Communicative approach names a classroom built around real exchanges rather than drills.","cn":"「交际教学法」命名一种围绕真实交流、而非操练组织起来的课堂。"}],"abstract":[{"en":"Picture a note passed hand to hand until two people hold the same sentence.","cn":"想象一张纸条被一手交到另一手，直到两个人握有同一句话。"},{"en":"The note can be a word, a glance, a pause or a bright tail; the medium changes, the transfer does not.","cn":"这张纸条可以是一个词、一瞥、一个停顿或一条鲜艳的尾巴；媒介在变，传递不变。"},{"en":"When the hand-off fails, the same adjective turns into a clinical label for what is missing.","cn":"当这次交接失败时，同一个形容词就变成标记「缺了什么」的临床标签。"}]},"examples":[{"en":"She became more communicative after the team moved to a smaller room.","cn":"团队搬进更小的房间后，她变得更愿意交流了。"},{"en":"A communicative gesture can replace a whole sentence in a noisy station.","cn":"在嘈杂的车站里，一个示意动作能替代一整句话。"},{"en":"The school adopted a communicative approach to teaching English.","cn":"这所学校采用了交际教学法来教英语。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「科缪尼凯提夫」听起来像「可缪你可提否」：能说会道，什么妙处都可提出来问一句 → 乐于交流的。","word":"communicative"},"root":"源自拉丁 communicare「分享、传达」，来自 communis「共同的」（由表示「共同」的前缀加 munus「义务、礼物」构成）；munus 更深来源不确定，几种假说并存，不能定论。","sensesIntro":{"en":"Eight senses follow one transfer: something held by one person is made common with another. The transfer can start with willingness, run without words, become a field of study, a competence, a method, an animal signal, a theory of action or a clinical deficit.","cn":"八个义项都沿着同一次传递展开：一个人手里的东西被另一个人共同拥有。这次传递可以从意愿开始，不用词语地进行，变成一门研究领域、一种能力、一种教学法、一种动物信号、一种行为理论，或一种临床缺陷。"},"semanticMap":{"core":{"en":"CORE IMAGE: something private is handed over and becomes shared.","cn":"核心意象：私有的东西被递出去，变成共同拥有的。"},"chain":["ONE HOLDER","SOMETHING SHARED","PASSED ACROSS","RECEIVED","MEANING MADE","COMMON GROUND"],"branches":[{"senses":"01","en":"THE CHANNEL OPENS: a person is willing to let others reach what is inside.","cn":"通道打开：一个人愿意让别人够到里面的东西。"},{"senses":"02","en":"NO WORDS NEEDED: a look, a pause or a gesture carries the same load.","cn":"不需要词语：一瞥、一个停顿或一个手势承载同样的分量。"},{"senses":"03 · 04 · 05","en":"THE TRANSFER BECOMES A FIELD: the process itself, the competence to use it, and a method that teaches it.","cn":"传递变成领域：过程本身、使用它的能力，以及教授它的方法。"},{"senses":"06","en":"OTHER SPECIES JOIN: colour, posture and call do the same work without language.","cn":"其他物种加入：颜色、姿态与叫声不用语言也能完成同样的工作。"},{"senses":"07 · 08","en":"INTENTION AND BREAKDOWN: action aimed at agreement, and the clinical name for a broken channel.","cn":"意图与故障：以共识为目标的行为，以及通道损坏时的临床名称。"}]},"affixes":{"intro":{"en":"Communicative is a suffix formation on a Latin verb, and the whole family shares one core of 'making common'.","cn":"communicative 是在一个拉丁动词上加后缀构成的，整个词族共享「使之共同」这一个核心。"},"latinIntro":{"en":"Latin communis 'common' produced communicare 'to share', which produced the Late Latin adjective communicativus and, through English suffixes, the noun, the person and the adjective.","cn":"拉丁 communis「共同的」产出 communicare「分享」，后者又产出晚期拉丁形容词 communicativus，并经英语后缀产出名词、指人的词与形容词。"},"items":[{"word":"communis","structure":"com- (together) + munus (service, gift)","meaning":"common, shared, public","meaningCN":"共同的、共享的、公共的","example":"The root names what several people hold together.","exampleCN":"这个词根命名的是若干人共同持有的东西。"},{"word":"communicate","structure":"communic- (make common) + -ate (verb suffix)","meaning":"to share, impart or exchange information","meaningCN":"分享、传达或交换信息","example":"They communicate through short daily notes.","exampleCN":"他们通过每日短笺交流。"},{"word":"communication","structure":"communicate + -ion (action noun)","meaning":"the act of sharing information; a message","meaningCN":"交流的行为；消息","example":"Clear communication prevented a second mistake.","exampleCN":"清晰的沟通避免了第二次错误。"},{"word":"communicator","structure":"communicate + -or (person who acts)","meaning":"a person who conveys ideas well","meaningCN":"善于传达的人","example":"She is a patient communicator.","exampleCN":"她是一个有耐心的沟通者。"},{"word":"communicative","structure":"communicate + -ive (tending to)","meaning":"willing to share meaning; relating to communication","meaningCN":"乐于传达意义的；与交流有关的","example":"The class is built around communicative tasks.","exampleCN":"这门课围绕交际任务来组织。"},{"word":"communicatively","structure":"communicative + -ly (adverb suffix)","meaning":"in a way that conveys meaning","meaningCN":"以传达意义的方式","example":"The two rooms are communicatively linked by a corridor.","exampleCN":"这两个房间通过一条走廊连通。"},{"word":"communicativeness","structure":"communicative + -ness (quality noun)","meaning":"the quality of being willing to communicate","meaningCN":"乐于交流的特质","example":"Her communicativeness surprised the new team.","exampleCN":"她乐于交流的样子让新团队感到意外。"},{"word":"community","structure":"commun- (common) + -ity (abstract noun)","meaning":"a group sharing something in common","meaningCN":"共享某些东西的群体","example":"The whole community joined the repair.","exampleCN":"整个社区都参与了修缮。"},{"word":"communicable","structure":"communicate + -able (capable of)","meaning":"able to be passed on, as a disease","meaningCN":"可传递的；可传染的","example":"The infection is communicable before symptoms appear.","exampleCN":"这种感染在症状出现之前就能传染。"}],"latinEntries":[{"word":"communis","structure":"com- (together) + munus (service, gift)","meaning":"common, shared","meaningCN":"共同的、共享的"},{"word":"communicare","structure":"communis + -are (verb suffix)","meaning":"to share, impart, make common","meaningCN":"分享、传达、使共同拥有"},{"word":"communicativus","structure":"communicare + -ivus (tending to)","meaning":"that may be shared","meaningCN":"可以被分享的"}],"derivatives":[{"word":"communicatively","pos":"adv.","zh":"以传达意义的方式（communicative 加副词后缀，把动作限定为传达）"},{"word":"communicativeness","pos":"n.","zh":"乐于交流（communicative 加名词后缀，指愿意传达的特质）"},{"word":"communication","pos":"n.","zh":"交流；通信（communicate 加名词后缀，指传达这件事）"},{"word":"communicator","pos":"n.","zh":"传达者（communicate 加表人后缀，指发出信息的人）"},{"word":"communicable","pos":"adj.","zh":"可传达的；可传染的（communicate 加表示「可被……」的形容词后缀，指能被传递出去）"}]}}]);
